/*
 * Working in a background tab (1.7.266): the browser slows the timers of a
 * tab that is not the selected one — to once a second, and after five
 * minutes to once a MINUTE — and stops its animation frames altogether. The
 * dashboard runs on timers (mod's rounds, the answers of Full auto, the
 * refresh countdown, every "wait 500 ms" of a workflow), so in the
 * background it crawled or stood still.
 *
 * This extension's own timers are therefore kept in a list here. While the
 * tab is the selected one they are driven by the browser's timer exactly as
 * before. While it is hidden a small worker — whose clock the browser does
 * not slow down — ticks five times a second and runs what is due. Animation
 * frames asked for while hidden are run by a timer instead. Content scripts
 * have their own copy of these functions: the CRM's own page is not touched.
 */
(function() {
    try {
        if (window.wpTimersKept) return;
        window.wpTimersKept = true;
        const nativeSetTimeout = window.setTimeout.bind(window);
        const nativeClearTimeout = window.clearTimeout.bind(window);
        const nativeSetInterval = window.setInterval.bind(window);
        const nativeClearInterval = window.clearInterval.bind(window);
        const nativeFrame = window.requestAnimationFrame.bind(window);
        const nativeCancelFrame = window.cancelAnimationFrame.bind(window);
        const FIRST_ID = 1000000000;
        const timers = new Map();
        let nextId = FIRST_ID;
        let armed = null;
        let armedAt = Infinity;
        let worker = null;
        let running = false;

        const run = function() {
            if (running) return;
            running = true;
            try {
                // what is due now, oldest first; a timer set while these run waits for the next pass
                for (let pass = 0; pass < 3; pass++) {
                    const now = Date.now();
                    const due = [];
                    timers.forEach(function(timer, id) { if (timer.at <= now) due.push([id, timer]); });
                    if (!due.length) break;
                    due.sort(function(a, b) { return (a[1].at - b[1].at) || (a[0] - b[0]); });
                    for (let i = 0; i < due.length; i++) {
                        const id = due[i][0];
                        const timer = due[i][1];
                        if (timers.get(id) !== timer) continue;
                        if (timer.every) timer.at = Math.max(timer.at + timer.every, Date.now());
                        else timers.delete(id);
                        try { timer.fn.apply(window, timer.args); } catch (error) { try { console.error(error); } catch (_) {} }
                    }
                }
            } finally {
                running = false;
                arm();
            }
        };
        const arm = function() {
            let soonest = Infinity;
            timers.forEach(function(timer) { if (timer.at < soonest) soonest = timer.at; });
            if (soonest === Infinity) {
                if (armed !== null) { nativeClearTimeout(armed); armed = null; armedAt = Infinity; }
                return;
            }
            if (armed !== null && armedAt <= soonest && armedAt > Date.now() - 50) return;
            if (armed !== null) nativeClearTimeout(armed);
            armedAt = soonest;
            armed = nativeSetTimeout(function() { armed = null; armedAt = Infinity; run(); }, Math.max(0, soonest - Date.now()));
        };
        const add = function(fn, ms, args, repeat) {
            const wait = Math.max(repeat ? 4 : 0, Number(ms) || 0);
            const id = nextId++;
            timers.set(id, { fn: fn, args: args, at: Date.now() + wait, every: repeat ? wait : 0 });
            arm();
            return id;
        };
        const drop = function(id) {
            if (timers.delete(id)) return true;
            return false;
        };
        window.setTimeout = function(fn, ms) {
            if (typeof fn !== 'function') return nativeSetTimeout.apply(null, arguments);
            return add(fn, ms, Array.prototype.slice.call(arguments, 2), false);
        };
        window.setInterval = function(fn, ms) {
            if (typeof fn !== 'function') return nativeSetInterval.apply(null, arguments);
            return add(fn, ms, Array.prototype.slice.call(arguments, 2), true);
        };
        window.clearTimeout = function(id) { if (!drop(id)) { nativeClearTimeout(id); nativeClearInterval(id); } };
        window.clearInterval = function(id) { if (!drop(id)) { nativeClearInterval(id); nativeClearTimeout(id); } };
        // animation frames: none are given to a hidden tab
        window.requestAnimationFrame = function(fn) {
            if (typeof fn === 'function' && document.hidden) {
                return add(function() { fn(performance.now()); }, 100, [], false);
            }
            return nativeFrame(fn);
        };
        window.cancelAnimationFrame = function(id) { if (!drop(id)) nativeCancelFrame(id); };

        // the clock that is not slowed down, only while the tab is hidden
        const tick = function() {
            if (document.hidden) {
                if (worker) return;
                try {
                    const url = URL.createObjectURL(new Blob(['setInterval(function(){postMessage(0)},200)'], { type: 'text/javascript' }));
                    worker = new Worker(url);
                    worker.onmessage = run;
                    worker.onerror = function() { try { worker.terminate(); } catch (_) {} worker = null; };
                    try { URL.revokeObjectURL(url); } catch (_) {}
                } catch (_) { worker = null; }
            } else if (worker) {
                try { worker.terminate(); } catch (_) {}
                worker = null;
                run();
            }
        };
        document.addEventListener('visibilitychange', tick);
        tick();
        window.wpTimersState = function() { return { kept: timers.size, hidden: Boolean(document.hidden), worker: Boolean(worker) }; };
    } catch (_) {}
})();


/*
 * Performance (1.7.185): classList.add / remove of a class that is already
 * there / already gone still counts as a change of the page (every other
 * script watching the page — Dark Reader, this extension's own watchers —
 * is woken up for it). The dashboard re-applies its row classes every few
 * seconds, so with hundreds of rows that was thousands of empty changes.
 * Content scripts have their own copy of these prototypes: only this
 * extension's calls are affected, and a real change behaves exactly as before.
 */
(function() {
    try {
        const add = DOMTokenList.prototype.add;
        const remove = DOMTokenList.prototype.remove;
        DOMTokenList.prototype.add = function() {
            for (let i = 0; i < arguments.length; i++) {
                if (!this.contains(arguments[i])) return add.apply(this, arguments);
            }
        };
        DOMTokenList.prototype.remove = function() {
            for (let i = 0; i < arguments.length; i++) {
                if (this.contains(arguments[i])) return remove.apply(this, arguments);
            }
        };
    } catch (_) {}
})();

/*
 * Welcome Pickups Transfer Assistant - Chrome extension bridge
 * Replaces Tampermonkey's GM_openInTab while keeping the original
 * Transfer Assistant logic intact.
 */
function wpExtensionOpenInTab(url, options = {}) {
    let tabId = null;
    let closed = false;

    const request = {
        type: 'WP_TRANSFER_ASSISTANT_OPEN_TAB',
        url: String(url),
        options: {
            active: options.active === true,
            pinned: options.pinned === true,
            index: Number.isFinite(options.index) ? options.index : undefined
        }
    };

    try {
        chrome.runtime.sendMessage(request, (response) => {
            if (chrome.runtime.lastError) {
                return;
            }
            if (response && Number.isInteger(response.tabId)) {
                tabId = response.tabId;
                if (closed) {
                    chrome.runtime.sendMessage({
                        type: 'WP_TRANSFER_ASSISTANT_CLOSE_TAB',
                        tabId
                    });
                }
            }
        });
    } catch (_error) {}

    return {
        get closed() {
            return closed;
        },
        close() {
            closed = true;
            if (Number.isInteger(tabId)) {
                try {
                    chrome.runtime.sendMessage({
                        type: 'WP_TRANSFER_ASSISTANT_CLOSE_TAB',
                        tabId
                    });
                } catch (_error) {}
            }
        }
    };
}

async function wpTransferAssistantExtensionEnabled() {
    try {
        const result = await chrome.storage.local.get({ enabled: true });
        return result.enabled !== false;
    } catch (_error) {
        return true;
    }
}

