    function wpGetCityCarTypes(city) {
        const key = wpNormalizeCityKey(city);
        if (!key) return null;
        const names = Object.keys(WP_CITY_CAR_TYPES);
        for (let i = 0; i < names.length; i++) {
            if (wpNormalizeCityKey(names[i]) === key) return WP_CITY_CAR_TYPES[names[i]];
        }
        return null;
    }

    function wpFindTransferCapacityInput(kind) {
        const wanted = kind === 'pax' ? 'pax' : 'lug';

        // First use the exact transfer header row the CRM exposes.  The
        // numeric inputs live in the corresponding column of the same table.
        const headerCell = Array.from(document.querySelectorAll('td, th')).find(function(cell) {
            return wpNormalizeDetailText(cell.textContent || '').trim().toLowerCase() === wanted;
        });

        if (headerCell) {
            const table = headerCell.closest('table');
            const headerRow = headerCell.parentElement;
            if (table && headerRow) {
                const headerCells = Array.from(headerRow.children);
                const columnIndex = headerCells.indexOf(headerCell);
                if (columnIndex >= 0) {
                    const rows = Array.from(table.querySelectorAll('tr'));
                    for (const row of rows) {
                        if (row === headerRow) continue;
                        const cells = Array.from(row.children);
                        const cell = cells[columnIndex];
                        if (!cell) continue;
                        const input = cell.querySelector('input');
                        if (!input) continue;
                        const r = input.getBoundingClientRect();
                        if (r.width > 0 && r.height > 0 && !input.disabled) return input;
                    }
                }
            }
        }

        // Conservative fallback for CRM variants.
        const selectors = wanted === 'pax'
            ? ['input[name="pax"]', 'input[id*="pax" i]', 'input[name*="pax" i]']
            : ['input[name="lug"]', 'input[name="luggage"]', 'input[id*="lug" i]', 'input[id*="luggage" i]', 'input[name*="lug" i]', 'input[name*="luggage" i]'];

        for (const selector of selectors) {
            const node = Array.from(document.querySelectorAll(selector)).find(function(input) {
                const r = input.getBoundingClientRect();
                return r.width > 0 && r.height > 0 && !input.disabled;
            });
            if (node) return node;
        }

        return null;
    }

    function wpFindBookedCarType() {
        const knownTypes = [
            'Sedan', 'Mini Van', 'Minivan', 'Mini Bus', 'Minibus',
            'SUV', 'Van', 'Bus', 'Maxi Sedan'
        ];

        const normalizedType = function(value) {
            return String(value || '')
                .replace(/\s+/g, ' ')
                .trim()
                .replace(/^Mini\s+Van$/i, 'Minivan')
                .replace(/^Mini\s+Bus$/i, 'Minibus')
                .toLowerCase();
        };

        const canonicalType = function(value) {
            const key = normalizedType(value);
            for (const type of knownTypes) {
                if (normalizedType(type) === key) {
                    return type === 'Mini Van' ? 'Minivan' :
                           type === 'Mini Bus' ? 'Minibus' :
                           type;
                }
            }
            return String(value || '').trim();
        };

        /*
         * The CRM renders Car Type as a normal table row, e.g.:
         *   <td>Car Type</td><td>Sedan</td>
         * Read that exact row first. This is more reliable than scanning
         * the whole page for the word "Sedan" because a transfer may have
         * other vehicle text elsewhere on the page.
         */
        const carTypeLabel = Array.from(
            document.querySelectorAll('td, th')
        ).find(function(node) {
            return wpNormalizeDetailText(
                node.textContent || ''
            ).toLowerCase() === 'car type';
        });

        if (carTypeLabel) {
            const row = carTypeLabel.parentElement;
            if (row) {
                const cells = Array.from(row.children);
                const index = cells.indexOf(carTypeLabel);
                if (index >= 0 && index + 1 < cells.length) {
                    const valueText = wpNormalizeDetailText(
                        cells[index + 1].textContent ||
                        cells[index + 1].innerText ||
                        ''
                    );
                    if (valueText) {
                        for (const type of knownTypes) {
                            const re = new RegExp(
                                '^' + type.replace(/ /g, '\\s+') + '$',
                                'i'
                            );
                            if (re.test(valueText)) {
                                return canonicalType(valueText);
                            }
                        }
                        const match = valueText.match(
                            /^(Sedan|Mini\s*Van|Minivan|Mini\s*Bus|Minibus|SUV|Van|Bus|Maxi\s*Sedan)$/i
                        );
                        if (match) {
                            return canonicalType(match[1]);
                        }
                    }
                }
            }
        }

        // Small fallback for CRM variants that render Car Type as plain text.
        const pageText = wpNormalizeDetailText(
            document.body && document.body.innerText || ''
        );
        const match = pageText.match(
            /Car\s*Type\s*[:\-]?\s*(Sedan|Mini\s*Van|Minivan|Mini\s*Bus|Minibus|SUV|Van|Bus|Maxi\s*Sedan)\b/i
        );
        return match ? canonicalType(match[1]) : '';
    }

    function wpVehicleEmoji(carType) {
        const key = String(carType || '').trim().toLowerCase();
        if (key.includes('minibus') || key === 'bus') return '🚌';
        if (key.includes('minivan') || key === 'van') return '🚐';
        if (key.includes('suv')) return '🚙';
        if (key.includes('maxi sedan')) return '🚘';
        return '🚗';
    }

    function wpFindVehicleCapacityForType(city, carType) {
        const cars = wpGetCityCarTypes(city) || [];
        if (!cars.length || !carType) return null;

        const key = String(carType)
            .replace(/\s+/g, ' ')
            .trim()
            .replace(/^Mini\s+Van$/i, 'Minivan')
            .replace(/^Mini\s+Bus$/i, 'Minibus')
            .toLowerCase();

        return cars.find(function(car) {
            const carKey = String(car[0] || '')
                .replace(/\s+/g, ' ')
                .trim()
                .replace(/^Mini\s+Van$/i, 'Minivan')
                .replace(/^Mini\s+Bus$/i, 'Minibus')
                .toLowerCase();
            return carKey === key;
        }) || null;
    }


    function wpGetTransferPaxLugHeaderCells() {
        const result = { pax: null, lug: null };
        const table = Array.from(document.querySelectorAll('table')).find(function(tbl) {
            const texts = Array.from(tbl.querySelectorAll('td, th')).map(function(cell) {
                return wpNormalizeDetailText(cell.textContent || '')
                    .trim()
                    .toLowerCase()
                    .replace(/\s*\/\s*\d+\s*$/, '')
                    .trim();
            });
            return texts.includes('pax') && texts.includes('lug');
        });
        if (!table) return result;
        Array.from(table.querySelectorAll('td, th')).forEach(function(cell) {
            const text = wpNormalizeDetailText(cell.textContent || '')
                .trim()
                .toLowerCase()
                .replace(/\s*\/\s*\d+\s*$/, '')
                .trim();
            if (text === 'pax' && !result.pax) result.pax = cell;
            if (text === 'lug' && !result.lug) result.lug = cell;
        });
        return result;
    }

    function wpSetCapacityHeaderText(cell, maxValue, label) {
        if (!cell) return;
        if (!cell.dataset.wpCapacityOriginalLabel) {
            const current = String(label || cell.textContent || '')
                .replace(/\s*\/\s*\d+\s*$/, '')
                .trim();
            cell.dataset.wpCapacityOriginalLabel = current;
        }

        const original = cell.dataset.wpCapacityOriginalLabel || String(label || '').trim();
        const max = Number(maxValue);
        const nextText = Number.isFinite(max)
            ? original + ' / ' + max
            : original;

        if (cell.textContent.trim() !== nextText) {
            cell.textContent = nextText;
        }
    }

    function wpUpdateCapacityInputColor(input, maxValue) {
        if (!input) return;

        input.style.color = '';
        const value = Number(input.value);
        const max = Number(maxValue);

        if (!Number.isFinite(value) || !Number.isFinite(max)) return;

        if (value > max) {
            input.style.color = '#ff5f56';
        } else if (value === max) {
            input.style.color = '#ffd54a';
        }
    }

    function wpInstallCapacityInputMonitoring(input, maxValue) {
        if (!input) return;

        input.dataset.wpCapacityMax = String(maxValue);
        wpUpdateCapacityInputColor(input, maxValue);

        if (input.dataset.wpCapacityColorBound === 'true') return;
        input.dataset.wpCapacityColorBound = 'true';

        const refresh = function() {
            wpUpdateCapacityInputColor(input, Number(input.dataset.wpCapacityMax));
        };

        input.addEventListener('input', refresh);
        input.addEventListener('change', refresh);
    }

    function wpInstallCapacityHeaderTooltip(cell, text) {
        if (!cell) return;
        const key = String(text || '');
        cell.title = key;
        cell.dataset.wpCapacityTooltip = key;
        cell.style.cursor = key ? 'help' : '';
    }

    function wpApplyTransferCapacityDisplay(city, cityLink) {
        const carType = wpFindBookedCarType();
        const car = wpFindVehicleCapacityForType(city, carType);

        let carTypeLink = document.getElementById('wp-transfer-car-type-link');

        if (cityLink && !carTypeLink) {
            carTypeLink = document.createElement('span');
            carTypeLink.id = 'wp-transfer-car-type-link';
            carTypeLink.className = 'wp-transfer-car-type-link';
            carTypeLink.title = 'Booked car type';
            cityLink.parentElement.insertBefore(carTypeLink, cityLink);
        }

        if (carTypeLink) {
            carTypeLink.textContent = carType ? wpVehicleEmoji(carType) : '🚘';
            carTypeLink.classList.toggle('is-ready', Boolean(carType));
            carTypeLink.title = carType
                ? 'Booked car type: ' + carType
                : 'Waiting for the CRM Car Type field…';
            carTypeLink.setAttribute('aria-label', carType || 'Car type');
            // Keep the separate vehicle box clearly to the left of City.
            carTypeLink.style.marginLeft = '-24px';
            carTypeLink.style.marginRight = '18px';
        }

        const headers = wpGetTransferPaxLugHeaderCells();
        const paxInput = wpFindTransferCapacityInput('pax');
        const lugInput = wpFindTransferCapacityInput('lug');

        if (!car) {
            wpSetCapacityHeaderText(headers.pax, NaN, 'Pax');
            wpSetCapacityHeaderText(headers.lug, NaN, 'Lug');
            wpInstallCapacityHeaderTooltip(headers.pax, '');
            wpInstallCapacityHeaderTooltip(headers.lug, '');
            wpInstallCapacityInputMonitoring(paxInput, NaN);
            wpInstallCapacityInputMonitoring(lugInput, NaN);
            return;
        }

        const maxPax = Number(car[1]);
        const maxLug = Number(car[2]);

        wpSetCapacityHeaderText(headers.pax, maxPax, 'Pax');
        wpSetCapacityHeaderText(headers.lug, maxLug, 'Lug');

        wpInstallCapacityHeaderTooltip(
            headers.pax,
            'Max Pax: ' + maxPax + ' · ' + carType
        );
        wpInstallCapacityHeaderTooltip(
            headers.lug,
            'Max Lug: ' + maxLug + ' · ' + carType
        );

        wpInstallCapacityInputMonitoring(paxInput, maxPax);
        wpInstallCapacityInputMonitoring(lugInput, maxLug);
    }

