    // WhatsApp group links changed from the Terminal (1.7.227): kept on this
    // PC (wp_wa_links_v1) and laid over the list above, so everything that
    // reads WHATSAPP_LINKS gets your link. Keys: a city of the list
    // ("Bucharest"), or "multi:<city>:<Welcomers|Dispatchers>" for a city
    // with two groups.
    const WP_WA_LINKS_KEY = 'wp_wa_links_v1';
    const WP_WA_LINKS_BUILT_IN = Object.assign({}, WHATSAPP_LINKS);
    function wpWaLinksLoad() {
        let saved = null;
        try { saved = JSON.parse(localStorage.getItem(WP_WA_LINKS_KEY) || '{}'); } catch (_) {}
        const out = {};
        Object.keys(saved && typeof saved === 'object' ? saved : {}).forEach(function(key) {
            if (/^https:\/\/chat\.whatsapp\.com\/[A-Za-z0-9]{16,32}$/.test(String(saved[key])) && key.length <= 80) out[key] = String(saved[key]);
        });
        return out;
    }
    function wpWaLinksApply() {
        const mine = wpWaLinksLoad();
        Object.keys(WHATSAPP_LINKS).forEach(function(key) { if (!(key in WP_WA_LINKS_BUILT_IN)) delete WHATSAPP_LINKS[key]; });
        Object.assign(WHATSAPP_LINKS, WP_WA_LINKS_BUILT_IN);
        Object.keys(mine).forEach(function(key) { if (key.indexOf('multi:') !== 0) WHATSAPP_LINKS[key] = mine[key]; });
        return mine;
    }
    wpWaLinksApply();

