    // ============================================================
    // CITY PRICE INCREASE TOOLTIP
    // ============================================================

    let cityPriceTooltip = null;

    function getCityPriceTooltip() {

        if (cityPriceTooltip) {
            return cityPriceTooltip;
        }

        cityPriceTooltip =
            document.createElement('div');

        cityPriceTooltip.id =
            'wp-city-price-tooltip';

        document.body.appendChild(
            cityPriceTooltip
        );

        return cityPriceTooltip;
    }

    function getCityPriceInfo(city) {

        const key =
            city
                .trim()
                .replace(/\s+/g, ' ')
                .toLowerCase();

        return CITY_PRICE_INCREASES[key] || null;
    }

    function positionCityPriceTooltip(event) {

        const tooltip =
            getCityPriceTooltip();

        const gap = 12;

        let left =
            event.clientX + gap;

        let top =
            event.clientY + gap;

        const rect =
            tooltip.getBoundingClientRect();

        if (
            left + rect.width >
            window.innerWidth - 8
        ) {
            left =
                event.clientX -
                rect.width -
                gap;
        }

        if (
            top + rect.height >
            window.innerHeight - 8
        ) {
            top =
                event.clientY -
                rect.height -
                gap;
        }

        tooltip.style.left =
            Math.max(8, left) + 'px';

        tooltip.style.top =
            Math.max(8, top) + 'px';
    }

