    const WP_PRICING_CACHE_KEY =
        'wp_em_project_pricing_cache_v1';

    function wpParseCsv(csv) {

        const rows = [];
        let row = [];
        let cell = '';
        let quoted = false;

        for (let i = 0; i < csv.length; i++) {

            const ch = csv[i];
            const next = csv[i + 1];

            if (quoted) {

                if (ch === '"' && next === '"') {
                    cell += '"';
                    i++;
                    continue;
                }

                if (ch === '"') {
                    quoted = false;
                    continue;
                }

                cell += ch;
                continue;

            }

            if (ch === '"') {
                quoted = true;
                continue;
            }

            if (ch === ',' || ch === '\t') {
                row.push(cell);
                cell = '';
                continue;
            }

            if (ch === '\n' || ch === '\r') {

                if (ch === '\r' && next === '\n') {
                    i++;
                }

                row.push(cell);
                rows.push(row);
                row = [];
                cell = '';
                continue;

            }

            cell += ch;

        }

        row.push(cell);

        if (row.some(function(v) { return v !== ''; })) {
            rows.push(row);
        }

        return rows;

    }

    function wpCsvHeaderIndex(headers, names) {

        for (const name of names) {

            const target =
                String(name)
                    .trim()
                    .replace(/\s+/g, ' ')
                    .toLowerCase();

            const index =
                headers.indexOf(target);

            if (index >= 0) {
                return index;
            }

        }

        return -1;

    }

    function wpApplyLivePricingRows(csv) {

        const rows = wpParseCsv(csv);

        if (rows.length < 2) {
            return false;
        }

        const headers =
            rows[0].map(function(value) {
                return String(value || '')
                    .trim()
                    .replace(/\s+/g, ' ')
                    .toLowerCase();
            });

        const cityIndex =
            wpCsvHeaderIndex(headers, [
                'Destination',
                'City'
            ]);

        if (cityIndex < 0) {
            return false;
        }

        const raiseIndex =
            wpCsvHeaderIndex(headers, ['Raise price']);

        const howMuchIndex =
            wpCsvHeaderIndex(headers, ['How much']);

        const carTypeIndex =
            wpCsvHeaderIndex(headers, ['Car Type']);

        const slotIndex =
            wpCsvHeaderIndex(headers, ['Slot of Day']);

        const skuIndex =
            wpCsvHeaderIndex(headers, ['SKU']);

        const notesIndex =
            wpCsvHeaderIndex(headers, ['Notes']);

        rows.slice(1).forEach(function(values) {

            const city =
                String(values[cityIndex] || '').trim();

            if (!city) {
                return;
            }

            const key =
                wpNormalizeCityKey(city);

            const raise =
                raiseIndex >= 0
                    ? String(values[raiseIndex] || '').trim()
                    : '';

            const howMuch =
                howMuchIndex >= 0
                    ? String(values[howMuchIndex] || '').trim()
                    : '';

            CITY_PRICING_DATA[key] = {
                city: city,
                raise: raise,
                howMuch: howMuch,
                carType:
                    carTypeIndex >= 0
                        ? String(values[carTypeIndex] || '').trim()
                        : '',
                slotOfDay:
                    slotIndex >= 0
                        ? String(values[slotIndex] || '').trim()
                        : '',
                sku:
                    skuIndex >= 0
                        ? String(values[skuIndex] || '').trim()
                        : '',
                notes:
                    notesIndex >= 0
                        ? String(values[notesIndex] || '').trim()
                        : '',
            };

            CITY_PRICE_INCREASES[key] =
                howMuch || raise;

        });

        return true;

    }

    function wpGetPricingCache() {

        try {
            return JSON.parse(localStorage.getItem(WP_PRICING_CACHE_KEY) || 'null');
        } catch (error) {
            return null;
        }

    }

    function wpFormatSyncClock(timestamp) {

        if (!timestamp) {
            return '--:--:--';
        }

        return new Date(timestamp).toLocaleTimeString([], {
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit'
        });

    }

    function wpEnsurePricingSyncStatusUI() {

        if (!document.body) {
            return null;
        }

        let wrap = document.getElementById('wp-em-project-sync-wrap');

        if (!wrap) {
            wrap = document.createElement('div');
            wrap.id = 'wp-em-project-sync-wrap';
            wrap.innerHTML =
                '<div id="wp-em-project-sync-status"></div>' +
                '<button id="wp-em-project-sync-button" type="button">Sync</button>' +
                '<input id="wp-em-project-sync-file" type="file" accept=".csv,.txt,text/csv,text/plain" style="display:none">';
            document.body.appendChild(wrap);

            const button =
                wrap.querySelector('#wp-em-project-sync-button');

            const input =
                wrap.querySelector('#wp-em-project-sync-file');

            button.addEventListener(
                'click',
                function(event) {
                    event.preventDefault();
                    event.stopPropagation();
                    input.value = '';
                    input.click();
                }
            );

            input.addEventListener(
                'change',
                function() {
                    const file = input.files && input.files[0];

                    if (!file) {
                        return;
                    }

                    button.disabled = true;
                    button.textContent = 'Reading…';
                    wpSetPricingSyncStatus('EM Project: reading file…');

                    const reader = new FileReader();

                    reader.onload = function() {

                        try {
                            const csv = String(reader.result || '');

                            if (!wpApplyLivePricingRows(csv)) {
                                throw new Error(
                                    'Could not find Destination/City column'
                                );
                            }

                            const syncedAt = Date.now();

                            localStorage.setItem(
                                WP_PRICING_CACHE_KEY,
                                JSON.stringify({
                                    csv: csv,
                                    updatedAt: syncedAt,
                                    fileName: file.name
                                })
                            );

                            wpUpdatePricingSyncStatus();

                        } catch (error) {
                            console.error(
                                'Welcome Pickups EM Project file error:',
                                error
                            );
                            wpSetPricingSyncStatus(
                                'EM Project: invalid file'
                            );
                        }

                        button.disabled = false;
                        button.textContent = 'Sync';

                    };

                    reader.onerror = function() {
                        button.disabled = false;
                        button.textContent = 'Sync';
                        wpSetPricingSyncStatus('EM Project: file read failed');
                    };

                    reader.readAsText(file);
                }
            );
        }

        return wrap;
    }

    // ---- EM Project straight from Google Drive (1.7.266) ----
    // The EM Project sheet's link is pasted once (EMP File → Google Drive
    // link). From then on the "Prices  blockings (dynamic)" tab is read as
    // CSV by the extension itself, with this Chrome's own Google sign-in:
    // when the dashboard opens and again every 3 hours (a new day always
    // reads it again). A sheet that does not look like the EM Project
    // prices (no "Raise price" column) is never taken. Uploading a file by
    // hand still works.
    const WP_EMP_DRIVE_KEY = 'wp_emp_drive_v1';
    const WP_EMP_DRIVE_CHECKED_KEY = 'wp_emp_drive_checked_v1';
    var wpEmpDriveBusy = false;
    function wpEmpDriveLink() {
        try { return String((JSON.parse(localStorage.getItem(WP_EMP_DRIVE_KEY) || '{}') || {}).url || ''); } catch (_) { return ''; }
    }
    function wpEmpDriveLast() {
        try { return JSON.parse(localStorage.getItem(WP_EMP_DRIVE_CHECKED_KEY) || 'null'); } catch (_) { return null; }
    }
    // A Sheets / Drive link → the CSV addresses to try, best first.
    function wpEmpDriveUrls(link) {
        const text = String(link || '').trim();
        const id = (text.match(/\/spreadsheets\/d\/([A-Za-z0-9_-]{20,})/) || text.match(/\/file\/d\/([A-Za-z0-9_-]{20,})/) || text.match(/[?&]id=([A-Za-z0-9_-]{20,})/) || [])[1];
        if (!id) return [];
        const gid = (text.match(/[#&?]gid=(\d+)/) || [])[1];
        const base = 'https://docs.google.com/spreadsheets/d/' + id;
        const urls = [];
        if (gid) urls.push(base + '/export?format=csv&gid=' + gid);
        urls.push(base + '/gviz/tq?tqx=out:csv&sheet=' + encodeURIComponent('Prices / blockings (dynamic)'));
        urls.push(base + '/gviz/tq?tqx=out:csv&sheet=' + encodeURIComponent('Prices  blockings (dynamic)'));
        urls.push(base + '/gviz/tq?tqx=out:csv&sheet=' + encodeURIComponent('Prices blockings (dynamic)'));
        if (!gid) urls.push(base + '/export?format=csv');
        return urls;
    }
    async function wpEmpDriveCheck(why) {
        const link = wpEmpDriveLink();
        if (!link || wpEmpDriveBusy) return false;
        const urls = wpEmpDriveUrls(link);
        const note = function(ok, error) {
            try { localStorage.setItem(WP_EMP_DRIVE_CHECKED_KEY, JSON.stringify({ at: Date.now(), ok: ok, error: String(error || '').slice(0, 200) })); } catch (_) {}
        };
        if (!urls.length) {
            note(false, 'the link is not a Google Sheets / Drive file link');
            wpDashLog('EM Project: the Google Drive link is not a Sheets / Drive file link — paste it again (EMP File)', 'warn');
            return false;
        }
        wpEmpDriveBusy = true;
        let lastError = '';
        try {
            for (let i = 0; i < urls.length; i++) {
                const reply = await new Promise(function(resolve) {
                    try {
                        chrome.runtime.sendMessage({ type: 'WP_EMP_FETCH', url: urls[i] }, function(answer) {
                            void chrome.runtime.lastError;
                            resolve(answer || { ok: false, error: 'no answer from the extension' });
                        });
                    } catch (error) { resolve({ ok: false, error: String(error && error.message || error) }); }
                });
                if (!reply.ok) { lastError = reply.error || 'not read'; continue; }
                const csv = String(reply.text || '');
                const head = (csv.split(/\r?\n/)[0] || '');
                if (!/raise\s*price/i.test(head) || !/destination|city/i.test(head)) { lastError = 'that sheet is not the EM Project prices tab (no "Raise price" column)'; continue; }
                let applied = false;
                try { applied = wpApplyLivePricingRows(csv); } catch (_) { applied = false; }
                if (!applied) { lastError = 'the sheet could not be read as EM Project prices'; continue; }
                const syncedAt = Date.now();
                try { localStorage.setItem(WP_PRICING_CACHE_KEY, JSON.stringify({ csv: csv, updatedAt: syncedAt, fileName: 'Google Drive' })); } catch (_) {}
                note(true, '');
                try { wpUpdatePricingSyncStatus(); } catch (_) {}
                const cities = Math.max(0, csv.split(/\r?\n/).filter(function(line) { return line.trim(); }).length - 1);
                wpDashLog('✓ EM Project updated from Google Drive (' + cities + ' rows)' + (why === 'auto' ? '' : ' — by hand'));
                // 1.7.278: and the hero drivers from the same file
                try { const sheetId = (urls[i].match(/\/spreadsheets\/d\/([A-Za-z0-9_-]{20,})/) || [])[1]; if (sheetId) await wpEmpHeroesCheck(sheetId); } catch (_) {}
                return true;
            }
        } finally {
            wpEmpDriveBusy = false;
        }
        note(false, lastError);
        wpDashLog('EM Project: could not read it from Google Drive — ' + lastError + '. The last file read stays in use.', 'warn');
        return false;
    }
    // The dashboard checks by itself: at once when it is due, then every 10 minutes whether it is due.
    function wpEmpDriveAuto() {
        try { if (wpIsTransferDetailPage()) return; } catch (_) {}
        const due = function() {
            if (!wpEmpDriveLink()) return false;
            const last = wpEmpDriveLast();
            if (!last || !Number(last.at)) return true;
            if (new Date(Number(last.at)).toDateString() !== new Date().toDateString()) return true;
            return Date.now() - Number(last.at) > (last.ok ? 3 * 3600000 : 30 * 60000);
        };
        window.setTimeout(function() { if (due()) wpEmpDriveCheck('auto'); }, 8000);
        window.setInterval(function() { if (due()) wpEmpDriveCheck('auto'); }, 10 * 60000);
    }
    // EMP File: a small window — the Drive link, "Check now", or a file by hand.
    function wpEmpMenu(anchor, uploadByHand) {
        const old = document.getElementById('wp-emp-menu');
        if (old) { old.remove(); return; }
        const box = document.createElement('div');
        box.id = 'wp-emp-menu';
        Object.assign(box.style, { position: 'fixed', zIndex: '2147483646', width: '360px', maxWidth: 'calc(100vw - 24px)', boxSizing: 'border-box', padding: '12px 14px', borderRadius: '14px', background: 'rgba(14,20,22,0.92)', backdropFilter: 'blur(22px)', border: '1px solid rgba(143,255,213,0.35)', boxShadow: '0 16px 44px rgba(0,0,0,0.45)', color: '#dfe4e6', font: '12px/1.45 Consolas, "Cascadia Mono", monospace' });
        const add = function(tag, text, style, parent) {
            const node = document.createElement(tag);
            if (text !== undefined && text !== null) node.textContent = text;
            if (style) Object.assign(node.style, style);
            (parent || box).appendChild(node);
            return node;
        };
        const head = add('div', null, { display: 'flex', alignItems: 'center', marginBottom: '6px' });
        add('span', 'EM Project file', { color: '#8fffd5', fontWeight: '700', fontSize: '13px' }, head);
        const x = add('span', '×', { marginLeft: 'auto', cursor: 'pointer', fontSize: '16px', color: '#8b979e' }, head);
        x.addEventListener('click', function() { box.remove(); });
        add('div', 'Google Drive / Sheets link of the EM Project (read every 3 hours and every new day, with this Chrome\'s Google sign-in):', { color: '#9aa6ad', margin: '2px 0 6px' });
        const input = add('input');
        input.type = 'text';
        input.placeholder = 'https://docs.google.com/spreadsheets/d/…';
        input.value = wpEmpDriveLink();
        Object.assign(input.style, { width: '100%', boxSizing: 'border-box', background: '#161a1d', color: '#e8ecee', border: '1px solid rgba(143,255,213,0.3)', borderRadius: '8px', padding: '6px 9px', font: 'inherit' });
        ['keydown', 'click', 'mousedown'].forEach(function(type) { input.addEventListener(type, function(event) { event.stopPropagation(); }); });
        const status = add('div', '', { margin: '8px 0', color: '#9aa6ad', minHeight: '16px' });
        const show = function() {
            const cached = wpGetPricingCache();
            const last = wpEmpDriveLast();
            status.style.color = last && !last.ok ? '#ff8a80' : '#9aa6ad';
            const heroes = wpHeroesFromDrive();
            status.textContent = (cached && cached.updatedAt ? 'In use: ' + (cached.fileName || 'file') + ', ' + new Date(Number(cached.updatedAt)).toLocaleString([], { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', hour12: false }) : 'No EM Project read yet') +
                ' · heroes: ' + (heroes ? heroes.count + ' from the sheet "' + (heroes.sheet || '') + '"' : 'the built-in list') +
                (last && !last.ok ? ' · last Drive check failed: ' + (last.error || '') : '');
        };
        show();
        const row = add('div', null, { display: 'flex', gap: '8px', flexWrap: 'wrap' });
        const button = function(label, onClick) {
            const node = add('button', label, { height: '28px', padding: '0 12px', borderRadius: '9px', border: '1px solid rgba(143,255,213,0.45)', background: 'rgba(14,20,22,0.6)', color: '#8fffd5', font: 'inherit', fontWeight: '700', cursor: 'pointer' }, row);
            node.type = 'button';
            node.addEventListener('click', function(event) { event.preventDefault(); event.stopPropagation(); onClick(node); });
            return node;
        };
        button('Save & check now', async function(node) {
            const link = String(input.value || '').trim();
            if (link && !wpEmpDriveUrls(link).length) { status.style.color = '#ff8a80'; status.textContent = 'That is not a Google Sheets / Drive file link.'; return; }
            try { localStorage.setItem(WP_EMP_DRIVE_KEY, JSON.stringify({ url: link, at: Date.now() })); } catch (_) {}
            if (!link) { status.textContent = 'Drive link removed — only a file by hand now.'; return; }
            node.disabled = true;
            node.textContent = 'Reading…';
            await wpEmpDriveCheck('hand');
            node.disabled = false;
            node.textContent = 'Save & check now';
            show();
        });
        button('Upload a file instead', function() { box.remove(); uploadByHand(); });
        document.body.appendChild(box);
        const r = anchor.getBoundingClientRect();
        const b = box.getBoundingClientRect();
        box.style.left = Math.max(12, Math.min(r.left, window.innerWidth - b.width - 12)) + 'px';
        box.style.top = Math.max(12, r.top - b.height - 8) + 'px';
    }

    // ---- Hero drivers from the same Google Sheet (1.7.278) ----
    // With the prices, the EM Project's heroes sheet (the one named
    // "…hero…", else the second sheet) is read too. Once read, it is the
    // list the Heroes buttons use (your own additions / removals still
    // apply on top); until then — or when it cannot be read — the list
    // built into the extension is used, as before.
    const WP_HEROES_DRIVE_KEY = 'wp_heroes_drive_v1';
    function wpHeroesFromDrive() {
        try {
            const stored = JSON.parse(localStorage.getItem(WP_HEROES_DRIVE_KEY) || 'null');
            return stored && stored.byCity && typeof stored.byCity === 'object' && Number(stored.count) > 0 ? stored : null;
        } catch (_) { return null; }
    }
    function wpEmpAsk(url, html) {
        return new Promise(function(resolve) {
            try {
                chrome.runtime.sendMessage({ type: 'WP_EMP_FETCH', url: url, html: Boolean(html) }, function(answer) {
                    void chrome.runtime.lastError;
                    resolve(answer || { ok: false, error: 'no answer from the extension' });
                });
            } catch (error) { resolve({ ok: false, error: String(error && error.message || error) }); }
        });
    }
    // The sheet's rows → { city: [ { name, whatsapp, carType, notes } ] }, or null when the columns are not there.
    function wpHeroesParse(csv) {
        const rows = wpParseCsv(String(csv || ''));
        const clean = function(value) { return String(value === null || value === undefined ? '' : value).replace(/\s+/g, ' ').trim(); };
        let head = -1, col = {};
        for (let i = 0; i < Math.min(rows.length, 12) && head < 0; i++) {
            const cells = rows[i].map(function(value) { return clean(value).toLowerCase(); });
            const find = function(pattern, not) { return cells.findIndex(function(text) { return pattern.test(text) && !(not && not.test(text)); }); };
            const city = find(/\b(city|destination|location)\b/);
            // 1.7.279: "What's App link" (with the apostrophe) in the EM Project heroes sheet
            const phone = find(/what[’']?s\s*app|\bwa\b|phone|number|link|contact\s*details/);
            let name = find(/\b(hero|name|contact)\b/, /\b(phone|what[’']?s\s*app|number|car|type|note|link)\b/);
            // the heroes sheet's name column has no header: the first empty-headed column before the city
            if (name < 0 && city > 0) { for (let k = 0; k < city; k++) { if (!cells[k]) { name = k; break; } } }
            if (city >= 0 && name >= 0 && phone >= 0 && name !== phone && name !== city) {
                head = i;
                col = { city: city, name: name, phone: phone, car: find(/\bcar\b|vehicle/), notes: find(/\bnotes?\b|comment|remarks?/) };
            }
        }
        if (head < 0) return null;
        const byCity = {};
        let lastCity = '';
        let count = 0;
        rows.slice(head + 1).forEach(function(cells) {
            const city = clean(cells[col.city]) || lastCity;
            const name = clean(cells[col.name]);
            const phone = clean(cells[col.phone]);
            if (clean(cells[col.city])) lastCity = clean(cells[col.city]);
            if (!city || !name || !phone) return;
            const key = wpNormalizeCityKey(city);
            (byCity[key] = byCity[key] || []).push({
                name: name.slice(0, 120), whatsapp: phone.slice(0, 400),
                carType: col.car >= 0 ? clean(cells[col.car]).slice(0, 80) : '',
                notes: col.notes >= 0 ? clean(cells[col.notes]).slice(0, 500) : ''
            });
            count += 1;
        });
        return count ? { byCity: byCity, count: count, cities: Object.keys(byCity).length } : null;
    }
    // id: the spreadsheet id. Tells the Terminal what happened.
    async function wpEmpHeroesCheck(id) {
        const base = 'https://docs.google.com/spreadsheets/d/' + id;
        const tried = [];
        // the sheets of the file, in order (from the file's own page)
        let sheets = [];
        const page = await wpEmpAsk(base + '/htmlview', true);
        if (page.ok) {
            const text = String(page.text || '');
            let match;
            // 1.7.279: how the file's page lists its sheets (read on the real EM Project file)
            const listed = /name:\s*"((?:[^"\\]|\\.)+)"[^}]{0,400}?gid:\s*"(\d+)"/g;
            while ((match = listed.exec(text))) sheets.push({ gid: match[2], name: match[1].replace(/\\\//g, '/').replace(/\\(.)/g, '$1').trim() });
            if (!sheets.length) {
                const buttons = /id="sheet-button-(\d+)"[^>]*>\s*(?:<a[^>]*>)?\s*([^<]+?)\s*</g;
                while ((match = buttons.exec(text))) sheets.push({ gid: match[1], name: match[2].replace(/&amp;/g, '&').trim() });
            }
        }
        const pick = sheets.filter(function(sheet) { return /hero/i.test(sheet.name); })[0] || sheets[1] || null;
        const urls = [];
        if (pick) urls.push([base + '/export?format=csv&gid=' + pick.gid, pick.name]);
        ['Active Heroes List (dynamic)', 'Heroes', 'Active Heroes', 'Heroes List', 'Hero Drivers'].forEach(function(name) { urls.push([base + '/gviz/tq?tqx=out:csv&sheet=' + encodeURIComponent(name), name]); });
        for (let i = 0; i < urls.length; i++) {
            const reply = await wpEmpAsk(urls[i][0], false);
            if (!reply.ok) { tried.push(urls[i][1] + ': ' + (reply.error || 'not read')); continue; }
            const parsed = wpHeroesParse(reply.text);
            if (!parsed) { tried.push(urls[i][1] + ': no city / name / WhatsApp columns'); continue; }
            try { localStorage.setItem(WP_HEROES_DRIVE_KEY, JSON.stringify({ at: Date.now(), sheet: urls[i][1], byCity: parsed.byCity, count: parsed.count })); } catch (_) {}
            wpDashLog('✓ Hero drivers updated from Google Drive ("' + urls[i][1] + '"): ' + parsed.count + ' heroes in ' + parsed.cities + ' cities');
            return true;
        }
        wpDashLog('Hero drivers: could not read them from Google Drive (' + (tried.slice(0, 3).join(' · ') || 'no heroes sheet found') + ') — the list in the extension stays in use.', 'warn');
        return false;
    }

    function wpSetPricingSyncStatus(text) {

        const wrap = wpEnsurePricingSyncStatusUI();

        if (!wrap) {
            return;
        }

        const status =
            wrap.querySelector('#wp-em-project-sync-status');

        if (status) {
            status.textContent = text;
        }

    }

    function wpUpdatePricingSyncStatus() {

        const wrap = wpEnsurePricingSyncStatusUI();

        if (!wrap) {
            return;
        }

        const status =
            wrap.querySelector('#wp-em-project-sync-status');

        if (!status) {
            return;
        }

        const cached = wpGetPricingCache();

        if (!cached || !cached.updatedAt) {
            status.textContent = 'EM Project: not synced yet';
            return;
        }

        const fileName = cached.fileName
            ? ' · ' + cached.fileName
            : '';

        status.textContent =
            'EM Project synced ' +
            wpFormatSyncClock(Number(cached.updatedAt)) +
            fileName +
            ' · next manual';

    }

    function wpLoadLivePricing() {

        const cached = wpGetPricingCache();

        if (!cached || !cached.csv) {
            wpUpdatePricingSyncStatus();
            return;
        }

        wpApplyLivePricingRows(cached.csv);
        wpUpdatePricingSyncStatus();

    }

    function wpStartPricingSyncStatus() {

        if (window.__wpPricingStatusInterval) {
            return;
        }

        wpLoadLivePricing();
        wpUpdatePricingSyncStatus();

        // This is only the small "synced at" label; 5s is visually
        // identical while avoiding needless DOM churn every second.
        window.__wpPricingClockInterval = window.setInterval(
            wpUpdatePricingSyncStatus,
            5000
        );

    }

    /*
     * Manual transfer-page hover data for cities whose pricing record is
     * not present as a normal CITY_PRICING_DATA entry.
     */

    const WP_TRANSFER_CITY_HOVER_DATA = {
        'larnaca': { inheritCity: 'Cyprus' },
        'paphos': { inheritCity: 'Cyprus' },
        'heraklion': { inheritCity: 'Crete' },
        'herakleion': { inheritCity: 'Crete' },
        'chania': { inheritCity: 'Crete' }
    };

    function getTransferCityHoverData(city) {

        const key = wpNormalizeCityKey(city);
        const transferData = WP_TRANSFER_CITY_HOVER_DATA[key];

        if (transferData && transferData.inheritCity) {
            return getCityPricingData(transferData.inheritCity);
        }

        return transferData || getCityPricingData(city) || null;
    }

    function getCityPricingData(city) {

        return (
            CITY_PRICING_DATA[
                wpNormalizeCityKey(city)
            ] || null
        );

    }

    function setupCityPriceTooltip(
        cityCell,
        pricingProvider
    ) {

        if (
            cityCell.dataset.wpPriceTooltipSetup === 'true'
        ) {
            return;
        }

        const city =
            cityCell.textContent.trim();

        const initialInfo =
            getCityPriceInfo(city);

        const initialPricing =
            typeof pricingProvider === 'function'
                ? pricingProvider(city)
                : getCityPricingData(city);

        const initialSkuComment =
            getCitySkuComment(city);

        if (
            !initialInfo &&
            !initialPricing &&
            !initialSkuComment
        ) {
            return;
        }

        cityCell.dataset.wpPriceTooltipSetup =
            'true';

        cityCell.addEventListener(
            'mouseenter',
            function(event) {

                const info =
                    getCityPriceInfo(city);

                const pricing =
                    typeof pricingProvider === 'function'
                        ? pricingProvider(city)
                        : getCityPricingData(city);

                const skuComment =
                    getCitySkuComment(city);

                const tooltip =
                    getCityPriceTooltip();

                const escapedCity =
                    city.replace(/[&<>"']/g, function(char) {
                        return {
                            '&': '&amp;',
                            '<': '&lt;',
                            '>': '&gt;',
                            '"': '&quot;',
                            "'": '&#39;'
                        }[char];
                    });

                const escapedInfo =
                    info
                        ? info.replace(/[&<>"']/g, function(char) {
                            return {
                                '&': '&amp;',
                                '<': '&lt;',
                                '>': '&gt;',
                                '"': '&quot;',
                                "'": '&#39;'
                            }[char];
                        })
                        : '';

                const escapedComment =
                    skuComment
                        ? skuComment.replace(/[&<>"']/g, function(char) {
                            return {
                                '&': '&amp;',
                                '<': '&lt;',
                                '>': '&gt;',
                                '"': '&quot;',
                                "'": '&#39;'
                            }[char];
                        })
                        : '';

                function escapeTooltipValue(
                    value
                ) {

                    return String(value || '')
                        .replace(/[&<>"']/g, function(char) {
                            return {
                                '&': '&amp;',
                                '<': '&lt;',
                                '>': '&gt;',
                                '"': '&quot;',
                                "'": '&#39;'
                            }[char];
                        });

                }

                const raisePrice =
                    pricing
                        ? escapeTooltipValue(
                            pricing.raise
                        )
                        : '';

                const howMuch =
                    pricing
                        ? escapeTooltipValue(
                            pricing.howMuch
                        )
                        : '';

                const carType =
                    pricing
                        ? escapeTooltipValue(
                            pricing.carType
                        )
                        : '';

                const slotOfDay =
                    pricing
                        ? escapeTooltipValue(
                            pricing.slotOfDay
                        )
                        : '';

                const sku =
                    pricing
                        ? escapeTooltipValue(
                            pricing.sku
                        )
                        : '';

                const notes =
                    pricing
                        ? escapeTooltipValue(
                            pricing.notes
                        )
                        : '';

                let detailsHtml = '';

                /*
                 * Keep the existing percentage/value first.
                 */
                if (
                    escapedInfo
                ) {

                    detailsHtml +=
                        '<div class="wp-price-value">' +
                        escapedInfo +
                        '</div>';

                } else if (
                    raisePrice &&
                    raisePrice.toLowerCase() !== 'no'
                ) {

                    detailsHtml +=
                        '<div class="wp-price-value">' +
                        raisePrice +
                        (
                            howMuch
                                ? ' · ' + howMuch
                                : ''
                        ) +
                        '</div>';

                }

                /*
                 * Show the existing city pricing details.
                 */
                if (pricing) {

                    detailsHtml +=
                        '<div class="wp-tooltip-details">' +

                        (
                            raisePrice
                                ? '<div><span class="wp-tooltip-label">Raise price:</span> ' +
                                  raisePrice +
                                  '</div>'
                                : ''
                        ) +

                        (
                            howMuch
                                ? '<div><span class="wp-tooltip-label">How much:</span> ' +
                                  howMuch +
                                  '</div>'
                                : ''
                        ) +

                        (
                            carType
                                ? '<div><span class="wp-tooltip-label">Car Type:</span> ' +
                                  carType +
                                  '</div>'
                                : ''
                        ) +

                        (
                            slotOfDay
                                ? '<div><span class="wp-tooltip-label">Slot of Day:</span> ' +
                                  slotOfDay +
                                  '</div>'
                                : ''
                        ) +

                        (
                            sku
                                ? '<div><span class="wp-tooltip-label">SKU:</span> ' +
                                  sku +
                                  '</div>'
                                : ''
                        ) +

                        '<div class="wp-tooltip-notes">' +
                        '<div class="wp-tooltip-notes-title">Notes</div>' +
                        (
                            notes
                                ? '<div class="wp-tooltip-notes-text">' +
                                  notes +
                                  '</div>'
                                : '<div class="wp-tooltip-notes-text">—</div>'
                        ) +
                        '</div>' +

                        '</div>';

                }

                if (
                    escapedComment
                ) {

                    detailsHtml +=
                        '<div class="wp-sku-comment">' +
                        escapedComment +
                        '</div>';

                }

                // 1.7.276: the local time there
                let clockHtml = '';
                try { const clockText = wpCityClockText(city); if (clockText) clockHtml = '<div class="wp-city-clock" style="margin:3px 0 4px;color:#8fffd5;font-weight:700;font-size:12px;white-space:nowrap">' + clockText.replace(/[&<>"']/g, '') + '</div>'; } catch (_) {}

                tooltip.innerHTML =
                    '<span class="wp-price-city">' +
                    escapedCity +
                    '</span>' +
                    clockHtml +
                    detailsHtml;

                tooltip.style.display =
                    'block';

                positionCityPriceTooltip(
                    event
                );
            }
        );

        cityCell.addEventListener(
            'mousemove',
            function(event) {

                const tooltip =
                    getCityPriceTooltip();

                if (
                    tooltip.style.display === 'block'
                ) {
                    positionCityPriceTooltip(
                        event
                    );
                }
            }
        );

        cityCell.addEventListener(
            'mouseleave',
            function() {

                const tooltip =
                    getCityPriceTooltip();

                tooltip.style.display =
                    'none';
            }
        );
    }

