    function wpCityZone(city) {
        const key = String(city || '').replace(/\s+/g, ' ').trim().toLowerCase();
        if (WP_CITY_ZONES[key]) return WP_CITY_ZONES[key];
        try { const norm = wpNormalizeCityKey(key); if (WP_CITY_ZONES[norm]) return WP_CITY_ZONES[norm]; } catch (_) {}
        return '';
    }
    // "Local time 14:32 Sat · 1 h ahead of you" (or '' when the city's zone is not known).
    function wpCityClockText(city, now) {
        const zone = wpCityZone(city);
        if (!zone) return '';
        const at = now ? new Date(now) : new Date();
        let clock = '', day = '', offsetThere = null;
        try {
            const parts = new Intl.DateTimeFormat('en-GB', { timeZone: zone, hour: '2-digit', minute: '2-digit', weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit', hour12: false }).formatToParts(at);
            const get = function(type) { const found = parts.find(function(part) { return part.type === type; }); return found ? found.value : ''; };
            clock = get('hour').replace(/^24$/, '00') + ':' + get('minute');
            day = get('weekday');
            const asUtc = Date.UTC(Number(get('year')), Number(get('month')) - 1, Number(get('day')), Number(get('hour').replace(/^24$/, '0')), Number(get('minute')));
            offsetThere = Math.round((asUtc - Math.floor(at.getTime() / 60000) * 60000) / 60000);
        } catch (_) { return ''; }
        const mine = -at.getTimezoneOffset();
        const diff = offsetThere === null ? null : offsetThere - mine;
        let gap = '';
        if (diff !== null) {
            if (diff === 0) gap = 'same time as you';
            else {
                const whole = Math.floor(Math.abs(diff) / 60), rest = Math.abs(diff) % 60;
                const text = (whole ? whole + ' h' : '') + (whole && rest ? ' ' : '') + (rest ? rest + ' min' : '');
                gap = text + (diff > 0 ? ' ahead of you' : ' behind you');
            }
        }
        const myDay = at.toLocaleDateString('en-GB', { weekday: 'short' });
        return 'Local time ' + clock + (day && day !== myDay ? ' ' + day : '') + (gap ? ' · ' + gap : '');
    }

