    const WP_HERO_CUSTOM_STORAGE_KEY =
        'wp_transfer_assistant_hero_overrides_v1';

    function wpReadHeroOverrides() {

        try {
            const raw =
                localStorage.getItem(
                    WP_HERO_CUSTOM_STORAGE_KEY
                );

            if (!raw) {
                return { additions: {}, removals: {} };
            }

            const parsed = JSON.parse(raw);

            return {
                additions:
                    parsed && parsed.additions &&
                    typeof parsed.additions === 'object'
                        ? parsed.additions
                        : {},
                removals:
                    parsed && parsed.removals &&
                    typeof parsed.removals === 'object'
                        ? parsed.removals
                        : {}
            };

        } catch (error) {
            return { additions: {}, removals: {} };
        }

    }

    function wpWriteHeroOverrides(overrides) {

        try {
            localStorage.setItem(
                WP_HERO_CUSTOM_STORAGE_KEY,
                JSON.stringify(overrides)
            );
        } catch (error) {
            console.warn(
                '[Transfer Assistant] Could not save Hero Driver changes.',
                error
            );
        }

    }

    function wpHeroDriverKey(driver) {
        return (
            String(driver && driver.name || '')
                .trim() +
            '||' +
            String(driver && driver.whatsapp || '')
                .trim()
        ).toLowerCase();
    }

    function wpGetHeroDriversForCity(
        city
    ) {

        if (!city) {
            return [];
        }

        const cityKey =
            wpNormalizeCityKey(city);

        const overrides =
            wpReadHeroOverrides();

        // 1.7.278: the heroes sheet from Google Drive when it was read, else the built-in list
        const fromDrive = wpHeroesFromDrive();
        const baseDrivers = fromDrive
            ? (Array.isArray(fromDrive.byCity[cityKey]) ? fromDrive.byCity[cityKey] : [])
            : (Array.isArray(WP_HERO_DRIVERS_BY_CITY[cityKey]) ? WP_HERO_DRIVERS_BY_CITY[cityKey] : []);

        const removals =
            Array.isArray(overrides.removals[cityKey])
                ? overrides.removals[cityKey]
                : [];

        const additions =
            Array.isArray(overrides.additions[cityKey])
                ? overrides.additions[cityKey]
                : [];

        const removalSet =
            new Set(removals);

        return baseDrivers
            .filter(function(driver) {
                return !removalSet.has(
                    wpHeroDriverKey(driver)
                );
            })
            .concat(additions);

    }

    // Digits of a hero's WhatsApp link (…send?phone=30691… / wa.me/30691…).
    function wpHeroPhone(url) {
        const text = String(url || '');
        const match = text.match(/[?&]phone=\+?(\d{7,15})/) || text.match(/wa\.me\/\+?(\d{7,15})/);
        if (match) return match[1];
        // 1.7.278: a plain number from the sheet ("PN: +30 693 410 3267", "phone=1305-613-0837")
        const plain = text.match(/(?:\+|phone=)\s?(\d[\d\s-]{6,20}\d)/);
        const digits = plain ? plain[1].replace(/\D/g, '') : '';
        return digits.length >= 7 && digits.length <= 15 ? digits : '';
    }

    function wpOpenHeroDriverWhatsApp(
        url
    ) {

        if (!url) {
            return;
        }

        // WhatsApp Web (auto-send on): open the chat in the WhatsApp Web
        // tab — the api.whatsapp.com link no longer reaches WhatsApp.
        const phone = wpHeroPhone(url);
        if (phone && wpWhatsAppAutoSendOn()) {
            try {
                chrome.runtime.sendMessage({ type: 'WP_WA_OPEN', url: 'https://web.whatsapp.com/send?phone=' + phone });
                return;
            } catch (_) {}
        }

        /*
         * Reuse the existing WhatsApp behaviour: background tab,
         * rightmost position, close after 3 seconds.
         */
        wpOpenCityWhatsAppUrl(
            url
        );

    }

    function wpShowHeroDriversManager(
        city
    ) {

        const existing =
            document.getElementById(
                'wp-hero-drivers-manager'
            );

        if (existing) {
            existing.remove();
            return;
        }

        const cityKey =
            wpNormalizeCityKey(city);

        const overrides =
            wpReadHeroOverrides();

        const modal =
            document.createElement('div');

        modal.id =
            'wp-hero-drivers-manager';

        modal.className =
            'wp-hero-drivers-manager';

        const title =
            document.createElement('div');
        title.className = 'wp-hero-manager-title';
        title.textContent =
            'Manage Hero Drivers — ' + city;
        modal.appendChild(title);

        const close =
            document.createElement('button');
        close.type = 'button';
        close.className = 'wp-hero-manager-close';
        close.textContent = '×';
        close.title = 'Close';
        close.addEventListener('click', function() {
            modal.remove();
        });
        modal.appendChild(close);

        const info =
            document.createElement('div');
        info.className = 'wp-hero-manager-info';
        info.textContent =
            'Changes are saved permanently in this browser. Additions and removals survive page reloads and script updates.';
        modal.appendChild(info);

        const removeTitle =
            document.createElement('div');
        removeTitle.className = 'wp-hero-manager-section';
        removeTitle.textContent = 'Remove a hero';
        modal.appendChild(removeTitle);

        const currentDrivers =
            wpGetHeroDriversForCity(city);

        if (!currentDrivers.length) {
            const none = document.createElement('div');
            none.className = 'wp-hero-manager-empty';
            none.textContent = 'No heroes currently listed.';
            modal.appendChild(none);
        } else {
            currentDrivers.forEach(function(driver) {
                const row = document.createElement('div');
                row.className = 'wp-hero-manager-row';

                const label = document.createElement('div');
                label.className = 'wp-hero-manager-row-label';
                label.textContent = driver.name;
                row.appendChild(label);

                const removeBtn = document.createElement('button');
                removeBtn.type = 'button';
                removeBtn.className = 'wp-hero-manager-remove';
                removeBtn.textContent = 'REMOVE';
                removeBtn.addEventListener('click', function() {

                    const latest = wpReadHeroOverrides();
                    const removals =
                        Array.isArray(latest.removals[cityKey])
                            ? latest.removals[cityKey]
                            : [];

                    const key = wpHeroDriverKey(driver);

                    if (!removals.includes(key)) {
                        removals.push(key);
                    }

                    latest.removals[cityKey] = removals;
                    wpWriteHeroOverrides(latest);
                    modal.remove();

                    wpShowHeroDriversPanel(city);
                    wpShowHeroDriversManager(city);
                });
                row.appendChild(removeBtn);
                modal.appendChild(row);
            });
        }

        const addTitle =
            document.createElement('div');
        addTitle.className = 'wp-hero-manager-section';
        addTitle.textContent = 'Permanently add a hero';
        modal.appendChild(addTitle);

        const form = document.createElement('form');
        form.className = 'wp-hero-manager-form';

        const fields = [
            ['name', 'Hero name', 'e.g. John Smith', true],
            ['whatsapp', 'WhatsApp / contact link', 'https://api.whatsapp.com/send?phone=...', true],
            ['carType', 'Car type', 'e.g. Sedan + Minivan', false],
            ['notes', 'Notes', 'Optional notes', false]
        ];

        const inputs = {};

        fields.forEach(function(def) {
            const wrap = document.createElement('label');
            wrap.className = 'wp-hero-manager-field';

            const label = document.createElement('span');
            label.textContent = def[1] + (def[3] ? ' *' : '');
            wrap.appendChild(label);

            const input = document.createElement('input');
            input.type = 'text';
            input.name = def[0];
            input.placeholder = def[2];
            input.required = !!def[3];
            input.autocomplete = 'off';
            wrap.appendChild(input);

            inputs[def[0]] = input;
            form.appendChild(wrap);
        });

        const addBtn = document.createElement('button');
        addBtn.type = 'submit';
        addBtn.className = 'wp-hero-manager-add';
        addBtn.textContent = 'ADD HERO PERMANENTLY';
        form.appendChild(addBtn);

        const status = document.createElement('div');
        status.className = 'wp-hero-manager-status';
        form.appendChild(status);

        form.addEventListener('submit', function(event) {
            event.preventDefault();

            const driver = {
                name: inputs.name.value.trim(),
                whatsapp: inputs.whatsapp.value.trim(),
                carType: inputs.carType.value.trim(),
                notes: inputs.notes.value.trim()
            };

            if (!driver.name || !driver.whatsapp) {
                status.textContent = 'Hero name and WhatsApp/contact are required.';
                status.classList.add('is-error');
                return;
            }

            const latest = wpReadHeroOverrides();
            const additions =
                Array.isArray(latest.additions[cityKey])
                    ? latest.additions[cityKey]
                    : [];

            const key = wpHeroDriverKey(driver);

            const alreadyExists =
                wpGetHeroDriversForCity(city).some(function(existingDriver) {
                    return wpHeroDriverKey(existingDriver) === key;
                });

            if (alreadyExists) {
                status.textContent = 'That hero is already in the list.';
                status.classList.add('is-error');
                return;
            }

            additions.push(driver);
            latest.additions[cityKey] = additions;

            // If this driver had previously been removed, undo that removal.
            latest.removals[cityKey] =
                (Array.isArray(latest.removals[cityKey])
                    ? latest.removals[cityKey]
                    : []
                ).filter(function(removedKey) {
                    return removedKey !== key;
                });

            wpWriteHeroOverrides(latest);

            status.textContent = 'Hero added permanently.';
            status.classList.remove('is-error');

            inputs.name.value = '';
            inputs.whatsapp.value = '';
            inputs.carType.value = '';
            inputs.notes.value = '';

            const oldPanel = document.getElementById('wp-hero-drivers-panel');
            if (oldPanel) {
                oldPanel.remove();
            }
            wpShowHeroDriversPanel(city);
            setTimeout(function() {
                const managerAgain = document.getElementById('wp-hero-drivers-manager');
                if (managerAgain) managerAgain.remove();
                wpShowHeroDriversManager(city);
            }, 0);
        });

        modal.appendChild(form);
        document.body.appendChild(modal);

    }

    function wpShowHeroDriversPanel(
        city
    ) {

        const existing =
            document.getElementById(
                'wp-hero-drivers-panel'
            );

        if (existing) {
            existing.remove();
        }

        const drivers =
            wpGetHeroDriversForCity(
                city
            );

        const panel =
            document.createElement(
                'div'
            );

        panel.id =
            'wp-hero-drivers-panel';

        // Hero Drivers starts OPEN on each newly opened transfer page.
        panel.classList.remove('is-collapsed');

        const collapseToggle =
            document.createElement(
                'button'
            );

        collapseToggle.type = 'button';
        collapseToggle.className = 'wp-panel-collapse-toggle';
        collapseToggle.textContent = 'Hero Drivers';
        collapseToggle.title = 'Collapse Hero Drivers';

        collapseToggle.addEventListener('click', function(event) {
            event.preventDefault();
            event.stopPropagation();

            const collapsed =
                panel.classList.toggle('is-collapsed');

            collapseToggle.textContent = 'Hero Drivers';
            collapseToggle.title =
                collapsed
                    ? 'Show Hero Drivers'
                    : 'Collapse Hero Drivers';

            requestAnimationFrame(function() {
                if (typeof wpPositionTransferCityNotesPanel === 'function') {
                    wpPositionTransferCityNotesPanel();
                }
            });
        });

        panel.appendChild(collapseToggle);

        const closeButton =
            document.createElement(
                'button'
            );

        closeButton.type =
            'button';

        closeButton.className =
            'wp-hero-drivers-close';

        closeButton.textContent =
            '×';

        closeButton.title =
            'Hide Hero Drivers';

        closeButton.addEventListener(
            'click',
            function(event) {

                event.preventDefault();
                event.stopPropagation();

                panel.classList.add('is-collapsed');
                collapseToggle.textContent = 'Hero Drivers';
                collapseToggle.title = 'Show Hero Drivers';

            }
        );

        panel.appendChild(
            closeButton
        );

        const manageButton =
            document.createElement('button');
        manageButton.type = 'button';
        manageButton.className = 'wp-hero-drivers-manage';
        manageButton.textContent = 'Manage';
        manageButton.title = 'Add or permanently remove Hero Drivers';
        manageButton.addEventListener('click', function(event) {
            event.preventDefault();
            event.stopPropagation();
            wpShowHeroDriversManager(city);
        });

        if (!drivers.length) {

            const empty =
                document.createElement(
                    'div'
                );

            empty.className =
                'wp-hero-drivers-empty';

            empty.textContent =
                'No hero drivers listed for this city.';

            panel.appendChild(
                empty
            );

        } else {

            const list =
                document.createElement(
                    'div'
                );

            list.className =
                'wp-hero-drivers-list';

            drivers.forEach(
                function(driver) {

                    const button =
                        document.createElement(
                            'button'
                        );

                    button.type =
                        'button';

                    button.className =
                        'wp-hero-driver-name';

                    button.innerHTML =
                        '<span class="wp-hero-driver-name-text">' +
                        driver.name.replace(/[&<>"']/g, function(char) {
                            return {
                                '&': '&amp;',
                                '<': '&lt;',
                                '>': '&gt;',
                                '"': '&quot;',
                                "'": '&#39;'
                            }[char];
                        }) +
                        '</span>' +
                        (
                            driver.carType
                                ? '<span class="wp-hero-driver-car">' +
                                  driver.carType.replace(/[&<>"']/g, function(char) {
                                      return {
                                          '&': '&amp;',
                                          '<': '&lt;',
                                          '>': '&gt;',
                                          '"': '&quot;',
                                          "'": '&#39;'
                                      }[char];
                                  }) +
                                  '</span>'
                                : ''
                        );

                    button.title =
                        driver.carType
                            ? driver.name +
                              ' — ' +
                              driver.carType
                            : driver.name;

                    button.addEventListener(
                        'click',
                        function(event) {

                            event.preventDefault();
                            event.stopPropagation();

                            wpOpenHeroDriverWhatsApp(
                                driver.whatsapp
                            );

                        }
                    );

                    list.appendChild(
                        button
                    );

                }
            );

            panel.appendChild(
                list
            );

        }

        // Keep management available as a subtle secondary action.
        panel.appendChild(
            manageButton
        );

        /*
         * Put the panel in the upper-right part of the transfer page,
         * below the refresh controls. It is fixed once and never moves.
         */
        panel.style.position =
            'fixed';

        panel.style.top =
            '86px';

        panel.style.right =
            '14px';

        document.body.appendChild(
            panel
        );

        requestAnimationFrame(function() {
            if (typeof wpPositionTransferCityNotesPanel === 'function') {
                wpPositionTransferCityNotesPanel();
            }
        });

    }

    function wpSetupHeroDriversOnTransferPage() {

        /*
         * This feature is only for transfer-detail pages.
         * It uses the same destination resolver as the city WhatsApp
         * button, so the displayed heroes correspond to the pickup city.
         */
        if (
            !wpIsTransferDetailPage()
        ) {
            return;
        }

        const city =
            wpFindTransferCity();

        if (!city) {
            return;
        }

        if (
            document.querySelector(
                '#wp-hero-drivers-panel'
            )
        ) {
            return;
        }

        wpShowHeroDriversPanel(
            city
        );

    }

    function wpOpenCityWhatsAppUrl(
        url
    ) {

        if (!url) {
            return;
        }

        /*
         * Keep the pre-v3.10.80 behavior that was working:
         * open the full WhatsApp invite URL in a background tab so the
         * browser/WhatsApp can handle the invite, then close that helper tab.
         */
        if (
            typeof wpExtensionOpenInTab === 'function'
        ) {

            const whatsappTab =
                wpExtensionOpenInTab(
                    url,
                    {
                        active: false,
                        insert: false,
                        setParent: true
                    }
                );

            if (
                whatsappTab &&
                typeof whatsappTab.close === 'function'
            ) {

                setTimeout(
                    function() {

                        if (
                            whatsappTab.closed !== true
                        ) {

                            try {
                                whatsappTab.close();
                            } catch (error) {}

                        }

                    },
                    3000
                );

            }

        } else {

            const newTab =
                window.open(
                    url,
                    '_blank'
                );

            if (newTab) {

                try {
                    newTab.opener = null;
                } catch (error) {}

                setTimeout(
                    function() {

                        try {

                            if (!newTab.closed) {
                                newTab.close();
                            }

                        } catch (error) {}

                    },
                    3000
                );

            }

        }

    }

    function wpShowCityWhatsAppChooser(
        city,
        options
    ) {

        const existing =
            document.getElementById(
                'wp-city-whatsapp-chooser'
            );

        if (existing) {
            existing.remove();
        }

        const overlay =
            document.createElement('div');

        overlay.id =
            'wp-city-whatsapp-chooser';

        const box =
            document.createElement('div');

        box.className =
            'wp-city-whatsapp-box';

        const title =
            document.createElement('div');

        title.className =
            'wp-city-whatsapp-title';

        title.textContent =
            'Choose ' +
            city +
            ' WhatsApp group';

        box.appendChild(title);

        Object.keys(options).forEach(
            function(name) {

                const button =
                    document.createElement('button');

                button.type =
                    'button';

                button.className =
                    'wp-city-whatsapp-option';

                button.textContent =
                    name;

                button.addEventListener(
                    'click',
                    function(event) {

                        event.preventDefault();
                        event.stopPropagation();

                        wpOpenCityWhatsAppUrl(
                            options[name]
                        );

                        overlay.remove();

                    }
                );

                box.appendChild(button);

            }
        );

        const cancel =
            document.createElement('button');

        cancel.type =
            'button';

        cancel.className =
            'wp-city-whatsapp-cancel';

        cancel.textContent =
            'Cancel';

        cancel.addEventListener(
            'click',
            function(event) {

                event.preventDefault();
                event.stopPropagation();

                overlay.remove();

            }
        );

        box.appendChild(cancel);
        overlay.appendChild(box);
        document.body.appendChild(overlay);

        overlay.addEventListener(
            'click',
            function(event) {

                if (
                    event.target === overlay
                ) {
                    overlay.remove();
                }

            }
        );

    }

    function setupCity(
        cityCell
    ) {

        const city =
            cityCell.textContent
                .replace(/\s+/g, ' ')
                .trim();

        const normalized =
            wpNormalizeCityKey(city);

        let url =
            '';

        Object.keys(
            WHATSAPP_LINKS
        ).some(function(key) {

            if (
                wpNormalizeCityKey(key) === normalized
            ) {

                url =
                    WHATSAPP_LINKS[key];

                return true;

            }

            return false;

        });

        if (!url) {
            /*
             * Multi-group cities use the same chooser as Crete/Cyprus.
             * Keep them linkable even though they have no single URL.
             */
            if (
                normalized !== 'crete' &&
                normalized !== 'cyprus' &&
                !WP_MULTI_WHATSAPP_GROUPS[normalized]
            ) {
                return;
            }
        }

        if (
            cityCell.dataset.wpSetup === 'true'
        ) {
            return;
        }

        cityCell.dataset.wpSetup =
            'true';

        cityCell.classList.add(
            'wp-city-link'
        );

        setupCityPriceTooltip(
            cityCell
        );

        cityCell.addEventListener(
            'click',
            function(event) {

                event.preventDefault();
                event.stopPropagation();

                const normalized =
                    wpNormalizeCityKey(city);

                if (
                    normalized === 'crete'
                ) {

                    wpShowCityWhatsAppChooser(
                        'Crete',
                        {
                            "Chania":
                                WHATSAPP_LINKS.Chania,
                            "Herakleion":
                                WHATSAPP_LINKS.Herakleion
                        }
                    );

                    return;

                }

                if (
                    normalized === 'cyprus'
                ) {

                    wpShowCityWhatsAppChooser(
                        'Cyprus',
                        {
                            "Paphos":
                                WHATSAPP_LINKS.Paphos,
                            "Larnaca":
                                WHATSAPP_LINKS.Larnaca
                        }
                    );

                    return;

                }

                if (WP_MULTI_WHATSAPP_GROUPS[normalized]) {
                    wpShowCityWhatsAppChooser(
                        city,
                        WP_MULTI_WHATSAPP_GROUPS[normalized]
                    );
                    return;
                }

                wpOpenCityWhatsApp(
                    city
                );

            }
        );

    }

    // ============================================================
    // FIND LAST TRANSFER TASK CELL
    // ============================================================

    function getLastTransferTaskCell(row) {

        const cells = row.querySelectorAll('td');

        if (!cells.length) {
            return null;
        }

        /* Prefer the semantic class assigned by arrangeColumns(). This is
         * more reliable than assuming the CRM header lives in <thead>. */
        const markedTaskCell =
            row.querySelector('td.wp-last-transfer-task');

        if (markedTaskCell) {
            return markedTaskCell;
        }

        // First try to find the column from the table header.
        const table = row.closest('table');

        if (table) {

            const headerRows = table.querySelectorAll('thead tr');

            for (const headerRow of headerRows) {

                const headers = headerRow.querySelectorAll('th, td');

                for (let i = 0; i < headers.length; i++) {

                    const headerText =
                        headers[i].textContent
                            .trim()
                            .toLowerCase();

                    if (
                        headerText.includes('last transfer task')
                    ) {

                        return cells[i] || null;

                    }
                }
            }
        }

        // Fallback: the Last Transfer Task cell normally
        // contains [Task].
        for (const cell of cells) {

            const text =
                cell.textContent.trim();

            if (
                text.includes('[Task]')
            ) {

                return cell;

            }
        }

        return null;
    }

    // ============================================================
    // SHORTEN EMPLOYEE BYLINE IN LAST TRANSFER TASK
    // ============================================================


    // ============================================================
    // TRANSFER TAG COLUMN
    // ============================================================

    function getTransferTagsCell(row) {

        if (!row) {
            return null;
        }

        return row.querySelector('td.wp-transfer-tags');
    }

    function wpDetectTransferTag(text) {

        const value = String(text || '').replace(/\s+/g, ' ').trim();

        // FINAL TAG HAS ABSOLUTE PRIORITY.
        // If a task contains final/final bc together with any other
        // operational or percentage instruction, always show FINAL BC.
        // "…on final bc", "at final", "before final" is a condition for later,
        // not a Final BC now (1.7.161).
        const finalNow = value.replace(/\b(?:on|at|for|before|when|if|until|till|by|after)\s+(?:the\s+)?final\b(?:\s*bc)?/gi, ' ');
        if (/\bfinal\s*(?:bc)?\b/i.test(finalNow)) {
            return {
                text: 'final bc',
                type: 'final'
            };
        }

        // PRICE-INCREASE TAGS HAVE PRIORITY AFTER FINAL.
        // If both are present, 20% wins over 10%.
        if (/(?:\bDC\s*)?(?:\+\s*)?20\s*%(?:\s*DC)?/i.test(value)) {
            return {
                text: '20%',
                type: '20'
            };
        }

        if (/(?:\bDC\s*)?(?:\+\s*)?10\s*%(?:\s*DC)?/i.test(value)) {
            return {
                text: '10%',
                type: '10'
            };
        }

        // "hero" / "heroes" (the old /heroes?/ needed "heroe").
        if (/\bhero(?:es)?\b/i.test(value)) {
            return {
                text: 'hero',
                type: 'hero'
            };
        }

        if (/(?:\bDC\s*=\s*TC\b|\bDC\s*TC\b|\bDC\s*=\s*\bTC\b)/i.test(value)) {
            return {
                text: 'dc = tc',
                type: 'dc-tc'
            };
        }

        // TC deductions: normalize all common forms to "-N TC".
        // Supports: TC -1, TC=-1, TC = -2, -2 TC, etc.
        const tcMinusMatch = value.match(/\bTC\s*(?:=\s*)?-\s*(\d+)\b/i);
        if (tcMinusMatch) {
            return {
                text: '-' + tcMinusMatch[1] + ' TC',
                type: 'tc-minus'
            };
        }

        const minusTcMatch = value.match(/(?:^|[\s(/])(-\s*\d+)\s*TC\b/i);
        if (minusTcMatch) {
            return {
                text: minusTcMatch[1].replace(/\s+/g, '') + ' TC',
                type: 'minus-tc'
            };
        }

        // Common broadcast instruction tags.
        // "send to BC and group", "send to BC & group", etc. -> BC & G
        // Any BC mention followed by the group ("sent to BC, Group", "sent
        // to BC,posted on group", "BC/group", "BC & G").
        if (/\bBC\b[^\n]*?\b(?:group|grp)\b/i.test(value) ||
            /\bBC\s*(?:&|and|,|\/|\+)\s*G\b/i.test(value)) {
            return {
                text: 'BC & G',
                type: 'bc-grp'
            };
        }

        // Plain broadcast references -> BC. Keep the more specific BC & G
        // test above first so combined instructions get the combined badge.
        if (/\b(?:broadcast|send\s+to\s+BC|sent\s+to\s+BC|\bto\s+BC\b)\b/i.test(value) ||
            /\b\bBC\b\s*(?:broadcast)?\b/i.test(value)) {
            return {
                text: 'BC',
                type: 'bc'
            };
        }

        // High-volume handling notes.
        if (/\bhigh[\s-]*vol(?:ume)?\b/i.test(value)) {
            return {
                text: 'HIGH VOL',
                type: 'high-vol'
            };
        }

        if (/\braised\s+a\s+bit\s+more\s+to\s+save\b/i.test(value)) {
            return {
                text: 'raised',
                type: 'raised-save'
            };
        }

        if (/\braised\b/i.test(value)) {
            return {
                text: 'raised',
                type: 'raised'
            };
        }

        return null;
    }

    // Tags that come from the notes: only instructions the CRM has no field
    // for (final bc, BC, BC & G, hero, high vol). Price wording in a note
    // ("20%", "dc=tc", "TC -1", "raised") is ignored: price tags come from
    // the real CRM prices (wpCrmPriceTags).
    var WP_PRICE_TAG_TYPES = ['20', '10', 'dc-tc', 'tc-minus', 'minus-tc', 'raised', 'raised-save'];
    function wpDetectNoteTag(text) {
        const withoutPrices = String(text || '')
            .replace(/(?:\bDC\s*)?(?:\+\s*)?\d+(?:[.,]\d+)?\s*%(?:\s*DC)?/gi, ' ')
            .replace(/\bDC\s*=?\s*TC\b/gi, ' ')
            .replace(/\bTC\s*(?:=\s*)?-\s*\d+\b/gi, ' ')
            .replace(/(^|[\s(/])-\s*\d+\s*TC\b/gi, '$1 ')
            .replace(/\braised(?:\s+a\s+bit\s+more\s+to\s+save)?\b/gi, ' ');
        const tag = wpDetectTransferTag(withoutPrices);
        return tag && WP_PRICE_TAG_TYPES.indexOf(tag.type) < 0 ? tag : null;
    }

    function wpUpdateTransferTag(row, taskText) {
        wpUpdateTransferNoteTag(row, taskText);
        // Keep the real price tags (loaded in the background) in place.
        try { if (row && row.dataset.wpCrmPath) wpRowCrmPaint(row); } catch (_) {}
    }

    function wpUpdateTransferNoteTag(row, taskText) {

        const tagCell = getTransferTagsCell(row);

        if (!tagCell) {
            return;
        }

        const cleanTaskText = String(taskText || '')
            .replace(/\s+/g, ' ')
            .trim();

        const tag = wpDetectNoteTag(cleanTaskText);

        // Performance (1.7.185): the cell was emptied and rebuilt on every
        // pass; now only when the tag is different or the badge is missing.
        const noteSignature = !cleanTaskText ? 'no tag' : (tag ? tag.type + '|' + tag.text : '');
        const noteBadges = tagCell.querySelectorAll('.wp-transfer-tag:not(.wp-price-tag)');
        if (tagCell.dataset.wpNoteSig === noteSignature && noteBadges.length === (noteSignature ? 1 : 0) &&
            (!noteSignature || noteBadges[0].textContent === (cleanTaskText ? tag.text : 'no tag'))) {
            return;
        }
        tagCell.dataset.wpNoteSig = noteSignature;

        tagCell.replaceChildren();

        // Empty Last Transfer Task gets an explicit "no tag" badge in the
        // dedicated Tags column so the task cell itself remains untouched.
        if (!cleanTaskText) {
            const noTagBadge = document.createElement('span');
            noTagBadge.className = 'wp-transfer-tag wp-transfer-tag-no-tag';
            noTagBadge.textContent = 'no tag';
            tagCell.appendChild(noTagBadge);
            return;
        }

        if (!tag) {
            return;
        }

        const badge = document.createElement('span');
        badge.className = 'wp-transfer-tag wp-transfer-tag-' + tag.type;
        badge.textContent = tag.text;
        tagCell.appendChild(badge);
    }

    // ============================================================
    // NORMALIZE LAST TRANSFER TASK DISPLAY
    // ============================================================

    function wpFormatLastTransferTask(taskCell) {

        const originalText =
            String(taskCell.dataset.wpOriginalTask || taskCell.textContent || '')
                .replace(/^\s*\[(?:Task|Refund)\]\s*/i, '')
                .replace(/\s+/g, ' ')
                .trim();

        taskCell.classList.remove('wp-last-task-no-tag');
        taskCell.style.removeProperty('background');
        taskCell.style.removeProperty('background-color');
        taskCell.style.removeProperty('background-image');

        if (!originalText) {
            taskCell.title = 'No Last Transfer Task';
            taskCell.replaceChildren();
            return;
        }

        /*
         * Keep the original wording and order exactly as the teammate wrote it.
         * Only remove the operational tag text because that information now
         * lives in the dedicated Tags column.
         */
        let displayText = originalText;

        displayText = displayText
            // hero
            .replace(/\bhero\b/ig, ' ')
            // final / final bc
            .replace(/\bfinal\s*(?:bc)?\b/ig, ' ')
            // dc = tc
            .replace(/\bDC\s*=\s*TC\b/ig, ' ')
            // tc -1 / tc -2 / ...
            .replace(/\bTC\s*-\s*\d+\b/ig, ' ')
            // -1 tc / -2 tc / ...
            .replace(/(?:^|[\s(/])-\s*\d+\s*\bTC\b/ig, ' ')
            // 10% / 20% with optional DC / + spacing
            .replace(/(?:\bDC\s*)?(?:\+\s*)?(?:10|20)\s*%(?:\s*DC)?/ig, ' ')
            // Exact raised-a-bit-more phrasing is a single tag.
            .replace(/\braised\s+a\s+bit\s+more\s+to\s+save\b/ig, ' ')
            // Other raised mentions are also removed as the generic raised tag.
            .replace(/\braised\b/ig, ' ')
            // Clean only the whitespace/separators left behind by tag removal.
            .replace(/\s{2,}/g, ' ')
            .replace(/\s+([,;:])/g, '$1')
            .replace(/([,;:])\s+(?=[,;:])/g, '$1 ')
            .replace(/^\s*[-–—,:;|/]+\s*/, '')
            .replace(/\s*[-–—,:;|/]+\s*$/g, '')
            .trim();

        taskCell.title = 'Original task: ' + originalText;

        const display = document.createElement('span');
        display.className = 'wp-last-task-display';

        const main = document.createElement('span');
        main.className = 'wp-last-task-main';
        main.textContent = displayText;

        display.appendChild(main);
        taskCell.replaceChildren(display);
    }

    // ============================================================
    // LAST TRANSFER TASK STATUS MARKER
    // ============================================================

    function highlightFinalTask(row) {

        const taskCell = getLastTransferTaskCell(row);

        if (!taskCell) {
            return;
        }

        taskCell.classList.add('wp-last-transfer-task');

        const hasCapturedTaskSource =
            taskCell.dataset.wpTaskSourceCaptured === '1';

        const rawOriginalTaskText = hasCapturedTaskSource
            ? String(taskCell.dataset.wpOriginalTask || '')
            : String(taskCell.textContent || '')
                .replace(/\s+/g, ' ')
                .trim();

        if (!hasCapturedTaskSource) {
            taskCell.dataset.wpOriginalTask = rawOriginalTaskText;
            taskCell.dataset.wpTaskSourceCaptured = '1';
        }

        wpUpdateTransferTag(
            row,
            rawOriginalTaskText
        );

        // Performance (1.7.185): the cell was rebuilt on every pass. When it
        // was already formatted for this same task text and still shows our
        // formatted content (or is empty for no task), nothing is redone.
        if (taskCell.dataset.wpTaskHighlightsProcessed === 'true' &&
            taskCell.dataset.wpFormattedFor === rawOriginalTaskText &&
            (rawOriginalTaskText
                ? (taskCell.children.length === 1 && taskCell.firstElementChild.classList.contains('wp-last-task-display'))
                : (taskCell.childNodes.length === 0 && taskCell.classList.contains('wp-last-task-no-tag')))) {
            return;
        }

        /*
         * Persist the CRM's original [Task]/[Refund] state because the
         * formatter replaces the visible cell contents on every pass.
         */
        if (!taskCell.dataset.wpHasCrmTag) {
            const rawTaskText =
                String(taskCell.textContent || '')
                    .replace(/\s+/g, ' ')
                    .trim();
            const rawTaskHtml = String(taskCell.innerHTML || '');

            const hasCrmTag =
                /^\s*\[(?:Task|Refund)\]\b/i.test(rawTaskText) ||
                /\[(?:Task|Refund)\]/i.test(rawTaskHtml);

            taskCell.dataset.wpHasCrmTag = hasCrmTag ? '1' : '0';
        }

        // Remove only the CRM prefix. The original task is retained in the tooltip.
        const walker = document.createTreeWalker(taskCell, NodeFilter.SHOW_TEXT);
        let node;
        while (node = walker.nextNode()) {
            const before = node.nodeValue || '';
            const after = before.replace(/^\s*\[(?:Task|Refund)\]\s*/i, '');
            if (after !== before) {
                node.nodeValue = after;
                break;
            }
        }

        const taskText = String(taskCell.textContent || '')
            .replace(/\s+/g, ' ')
            .trim();

        if (/\bfinal\s*(?:bc)?\b/i.test(taskText)) {
            taskCell.dataset.wpTaskBadge = 'FINAL';
        } else if (/(?:\bDC\s*)?(?:\+\s*)?20\s*%(?:\s*DC)?\b/i.test(taskText)) {
            taskCell.dataset.wpTaskBadge = '20';
        } else if (/(?:\bDC\s*)?(?:\+\s*)?10\s*%(?:\s*DC)?\b/i.test(taskText)) {
            taskCell.dataset.wpTaskBadge = '10';
        } else if (taskCell.dataset.wpHasCrmTag === '1') {
            taskCell.dataset.wpTaskBadge = 'TAG';
        } else {
            taskCell.dataset.wpTaskBadge = 'NO TAG';
        }

        wpFormatLastTransferTask(taskCell);

        // Re-assert the empty-state class from the original CRM task source.
        // This prevents the formatter's visible "no tag" label from being
        // mistaken for real task text on the next processing pass.
        if (!rawOriginalTaskText) {
            taskCell.classList.add('wp-last-task-no-tag');
        } else {
            taskCell.classList.remove('wp-last-task-no-tag');
        }

        taskCell.dataset.wpTaskHighlightsProcessed = 'true';
        taskCell.dataset.wpFormattedFor = rawOriginalTaskText;
    }

    // TO LOCATION ICON IN TBO COLUMN
    // ============================================================

    function updateToLocationIcon(row) {
        const toCell =
            wpGetRowLocationCell(row, 'to');

        const tboCell =
            getTBOCell(row);

        if (!toCell || !tboCell) {
            return;
        }

        const toText =
            String(toCell.textContent || '')
                .replace(/\s+/g, ' ')
                .trim()
                .toLowerCase();

        let icon = '';
        let label = '';

        // Shared airport / port / train detector (whole words, multi-language).
        const toTypes = wpDetectLocationTypesFromText(wpLocationCellText(toCell));
        if (toTypes.airport) {
            icon = '✈️';
            label = 'Airport / terminal';
        } else if (toTypes.port) {
            icon = '🚢';
            label = 'Port / ferry';
        } else if (toTypes.train) {
            icon = '🚆';
            label = 'Train / station';
        }

        let iconEl =
            tboCell.querySelector('.wp-to-location-icon');

        if (!icon) {
            if (iconEl) {
                iconEl.remove();
            }
            return;
        }

        if (!iconEl) {
            iconEl = document.createElement('span');
            iconEl.className = 'wp-to-location-icon';
            tboCell.appendChild(iconEl);
        }

        iconEl.textContent = ' ' + icon;
        iconEl.title = label + ': ' + toCell.textContent.trim();
        iconEl.setAttribute('aria-label', label);
    }

    // ============================================================
    // CLEAR TBO STATE
    // ============================================================

    function clearTBOState(row) {

        row.classList.remove(
            'wp-tbo-orange',
            'wp-tbo-red',
            'wp-tbo-dark-red',
            'wp-tbo-gray',
            'wp-tbo-flash'
        );

    }

    // ============================================================
    // APPLY TBO STATE
    // ============================================================

    function setTBOState(
        row,
        minutes,
        isBooking
    ) {

        clearTBOState(row);

        if (minutes === null) {
            return;
        }

        // ========================================================
        // BOOKING.COM
        // ========================================================

        if (isBooking) {

            // TOMORROW BOOKING.COM
            // 1d 1h30 -> 1d 1h11 = RED
            if (
                minutes >= BOOKING_1DAY_RED_END &&
                minutes <= BOOKING_1DAY_RED_START
            ) {
                row.classList.add('wp-tbo-red');
                return;
            }

            // 1d 1h10 -> 1d 1h01 = FLASH
            if (
                minutes >= BOOKING_1DAY_FLASH_END &&
                minutes <= BOOKING_1DAY_FLASH_START
            ) {
                row.classList.add('wp-tbo-flash');
                return;
            }

            // Everything else at 1 day or more = NO TBO COLOUR.
            if (minutes >= 24 * 60) {
                return;
            }

            // 2h00 -> 0 = GRAY
            if (minutes <= BOOKING_GRAY) {
                row.classList.add('wp-tbo-gray');
                return;
            }

            // 3h30 -> 3h00 = BRIGHT RED
            // Booking.com no longer has a flashing range here.
            if (
                minutes >= BOOKING_RED_END &&
                minutes <= BOOKING_RED_START
            ) {
                row.classList.add('wp-tbo-red');
                return;
            }

            // 2h59 -> 2h01 = DARK RED
            if (
                minutes >= BOOKING_DARK_RED_END &&
                minutes <= BOOKING_DARK_RED_START
            ) {
                row.classList.add('wp-tbo-dark-red');
                return;
            }

            // 4h00 -> 3h31 = ORANGE
            if (
                minutes >= BOOKING_RED_START + 1 &&
                minutes <= BOOKING_ORANGE
            ) {
                row.classList.add('wp-tbo-orange');
                return;
            }

            return;
        }

        // ========================================================
        // NORMAL TRANSFERS
        // ========================================================

        // Airport / port / train drop-offs are cancelled 1h30 before
        // operation, so move every normal warning state 30 minutes
        // earlier. Booking.com keeps its existing thresholds above.
        const toCell =
            wpGetRowLocationCell(row, 'to');

        const toText =
            String(toCell?.textContent || '')
                .replace(/\s+/g, ' ')
                .trim()
                .toLowerCase();

        // Shared detector: whole words only, so e.g. an address in Porto or
        // a "transport" company no longer counts as a port drop-off.
        const toTypes = wpDetectLocationTypesFromText(wpLocationCellText(toCell));
        const earlyCancel =
            toTypes.airport || toTypes.port || toTypes.train;

        const shift =
            earlyCancel
                ? SPECIAL_NORMAL_SHIFT
                : 0;

        const orange =
            NORMAL_ORANGE + shift;
        const orangeEnd =
            NORMAL_ORANGE_END + shift;
        const red =
            NORMAL_RED + shift;
        const flashStart =
            NORMAL_FLASH_START + shift;
        const flashEnd =
            NORMAL_FLASH_END + shift;
        const darkRedStart =
            NORMAL_DARK_RED_START + shift;
        const darkRedEnd =
            NORMAL_DARK_RED_END + shift;
        const gray =
            NORMAL_GRAY + shift;

        // 1 day or more = NO TBO COLOUR
        if (minutes >= 24 * 60) {
            return;
        }

        // Flash window
        if (
            minutes >= flashEnd &&
            minutes <= flashStart
        ) {
            row.classList.add('wp-tbo-flash');
            return;
        }

        // Gray until cancellation cutoff
        if (minutes <= gray) {
            row.classList.add('wp-tbo-gray');
            return;
        }

        // Dark red
        if (
            minutes >= darkRedEnd &&
            minutes <= darkRedStart
        ) {
            row.classList.add('wp-tbo-dark-red');
            return;
        }

        // Red
        if (
            minutes >= flashStart + 1 &&
            minutes <= red
        ) {
            row.classList.add('wp-tbo-red');
            return;
        }

        // Orange
        if (
            minutes >= orangeEnd &&
            minutes <= orange
        ) {
            row.classList.add('wp-tbo-orange');
            return;
        }

    }

    // ============================================================
    // FIND AUTOCANCEL CELL
    // ============================================================

    function getAutoCancelCell(row) {

        // AutoCancel styling belongs ONLY to the transfer overview table.
        // Transfer-detail pages also contain .auto-cancel elements, and
        // touching those rows can distort the detail-page layout.
        const table = row.closest('table.transfers');

        if (!table) {
            return null;
        }

        const cells = row.querySelectorAll('td');

        if (!cells.length) {
            return null;
        }

        // Most reliable method: the CRM renders the label as
        // <span class="auto-cancel">EmNad</span> inside the AutoCancel cell.
        for (const cell of cells) {
            if (
                cell.querySelector('span.auto-cancel') ||
                /\bemnad\b/i.test(cell.textContent)
            ) {
                cell.classList.add('wp-autocancel-cell');
                return cell;
            }
        }

        // Header-based fallback. The CRM can place its transfer-table
        // headers in the first tbody row instead of a thead.
        const headerRows = table.querySelectorAll(
            'thead tr, tbody > tr:first-child'
        );

        for (const headerRow of headerRows) {
            const headers = headerRow.querySelectorAll('th, td');

            for (let i = 0; i < headers.length; i++) {
                const headerText =
                    headers[i].textContent
                        .trim()
                        .toLowerCase()
                        .replace(/\s+/g, ' ');

                if (
                    headerText.includes('autocancel') ||
                    headerText.includes('auto cancel')
                ) {
                    const cell = cells[i] || null;

                    if (cell) {
                        cell.classList.add('wp-autocancel-cell');
                    }

                    return cell;
                }
            }
        }

        return null;
    }

    // ============================================================
    // PARSE AUTOCANCEL TIME
    // ============================================================

    function parseAutoCancelMinutes(text) {

        if (!text) {
            return null;
        }

        // Examples supported:
        // 59m
        // 58m
        // 1h 05m
        // 1h5m
        // The CRM may prepend "EmNad"; it is ignored for parsing.

        const lower = text
            .replace(/^\s*EmNad\s*/i, '')
            .toLowerCase()
            .replace(/\s+/g, ' ')
            .trim();

        const hoursMatch = lower.match(/(\d+)\s*h/);
        const minutesMatch = lower.match(/(\d+)\s*m/);

        if (!hoursMatch && !minutesMatch) {
            return null;
        }

        const hours = hoursMatch
            ? parseInt(hoursMatch[1], 10)
            : 0;

        const minutes = minutesMatch
            ? parseInt(minutesMatch[1], 10)
            : 0;

        return hours * 60 + minutes;
    }

    // ============================================================
    // APPLY AUTOCANCEL WARNING
    // ============================================================

    function setAutoCancelState(row) {

        const autoCancelCell =
            getAutoCancelCell(row);

        if (!autoCancelCell) {
            row.classList.remove(
                'wp-autocancel-danger'
            );
            return;
        }

        // Remove only the CRM's EmNad label span. Do NOT replace
        // textContent, because the countdown is a sibling text node.
        autoCancelCell
            .querySelectorAll('span.auto-cancel')
            .forEach(function(label) {
                label.remove();
            });

        // Also handle a plain-text EmNad fallback without destroying the timer.
        autoCancelCell.childNodes.forEach(function(node) {
            if (node.nodeType === Node.TEXT_NODE) {
                const withoutLabel = node.nodeValue.replace(/\bEmNad\b\s*/ig, '');
                if (withoutLabel !== node.nodeValue) node.nodeValue = withoutLabel;
            }
        });

        const timerText =
            Array.from(autoCancelCell.childNodes)
                .map(function(node) {
                    return node.textContent || '';
                })
                .join(' ')
                .replace(/\s+/g, ' ')
                .trim();

        const minutes =
            parseAutoCancelMinutes(timerText);

        if (autoCancelCell.style.color) autoCancelCell.style.color = '';

        // Performance (1.7.185): none/60+ = white, 30-59 = orange, under 30
        // = red + row danger — as before, but only the difference is written
        // (all classes were removed and added back on every pass).
        const state = (minutes === null || minutes >= 60) ? 'white' : minutes >= 30 ? 'orange' : 'red';
        ['white', 'orange', 'red'].forEach(function(name) {
            if (name === state) autoCancelCell.classList.add('wp-autocancel-' + name);
            else autoCancelCell.classList.remove('wp-autocancel-' + name);
        });
        if (state === 'red') row.classList.add('wp-autocancel-danger');
        else row.classList.remove('wp-autocancel-danger');

        // 1.7.294: the timer against the TBO. "→ 1:40" = AutoCancel runs out
        // at 1:40 to pickup. Marked when that is AFTER mod's cancellation limit
        // (2:00 Booking.com, 1:08 drop-offs, 0:38 pickups). The cell's own text
        // is not touched.
        try {
            const tboCell = getTBOCell(row);
            const tbo = tboCell ? parseTBO(tboCell.textContent) : null;
            // 1.7.294: Booking.com 2:00, drop-offs 1:08, pickups 0:38
            const limitInfo = wpTopLimitFor(row);
            const limit = limitInfo.limit;
            let mark = '', at = '';
            if (minutes !== null && Number.isFinite(minutes) && Number.isFinite(tbo)) {
                const left = Math.max(0, tbo - minutes);
                mark = left < limit ? 'late' : 'intime';
                at = Math.floor(left / 60) + ':' + String(left % 60).padStart(2, '0');
            }
            if ((autoCancelCell.dataset.wpAcAt || '') !== at) { if (at) autoCancelCell.dataset.wpAcAt = at; else delete autoCancelCell.dataset.wpAcAt; }
            if (autoCancelCell.classList.contains('wp-ac-late') !== (mark === 'late')) autoCancelCell.classList.toggle('wp-ac-late', mark === 'late');
            if (autoCancelCell.classList.contains('wp-ac-intime') !== (mark === 'intime')) autoCancelCell.classList.toggle('wp-ac-intime', mark === 'intime');
            const title = mark ? 'AutoCancel runs out at ' + at + ' to pickup — ' + (mark === 'late' ? 'AFTER' : 'before') + ' the ' + limitInfo.mark : '';
            if (autoCancelCell.title !== title) autoCancelCell.title = title;
        } catch (_) {}
        // 1.7.296: mod's own auto-cancel coming (set by wpAutoTopRuleCheck each
        // round): "cancel in 12m" in front of the timer. Dropped when mod has
        // not confirmed it for 3 minutes (mod off, assigned, gone).
        try {
            const cancelAt = Number(row.dataset.wpCancelAt || 0);
            const fresh = cancelAt && Date.now() - Number(row.dataset.wpCancelSeen || 0) < 3 * 60000;
            const left = fresh ? Math.max(0, Math.round((cancelAt - Date.now()) / 60000)) : null;
            const label = left === null ? '' : (left <= 0 ? 'cancelling now' : 'cancel in ' + left + 'm');
            if ((autoCancelCell.dataset.wpCancelIn || '') !== label) { if (label) autoCancelCell.dataset.wpCancelIn = label; else delete autoCancelCell.dataset.wpCancelIn; }
            if (autoCancelCell.classList.contains('wp-ac-soon') !== Boolean(label)) autoCancelCell.classList.toggle('wp-ac-soon', Boolean(label));
        } catch (_) {}
    }

    // ============================================================
    // PROCESS ROW
    // ============================================================

    // ============================================================
    // MINIVAN UPGRADE INDICATOR
    //
    // The CRM does not expose the route code reliably, so this uses
    // the city-level eligibility list from the manager's sense-check.
    // The icon is placed in the TBO/icon cell.
    // ============================================================

    function applyMinivanUpgradeIcon(
        row,
        cityCell,
        orderCell
    ) {

        if (!orderCell) {
            return;
        }

        const existing =
            orderCell.querySelector(
                '.wp-minivan-upgrade-order-icon'
            );

        if (existing) {
            existing.remove();
        }

        const city =
            cityCell
                ? cityCell.textContent
                : '';

        // The manager's viable-city list is intentionally inverted here:
        // most cities can use a Minivan upgrade, so the icon marks the
        // exceptions where the 2× TC sense-check does NOT support it.
        if (wpIsMinivanUpgradeCity(city)) {
            return;
        }

        const icon =
            document.createElement('span');

        icon.className =
            'wp-minivan-upgrade-order-icon';

        icon.innerHTML =
            '<svg aria-hidden="true" viewBox="0 0 24 16" width="15" height="12" focusable="false">' +
            '<path d="M2 3.5h11.2l3.1 3.1H21a1 1 0 0 1 1 1v4.2h-1.7a3.1 3.1 0 0 1-6.1 0H9.8a3.1 3.1 0 0 1-6.1 0H2a1 1 0 0 1-1-1V4.5a1 1 0 0 1 1-1zm2.8 7.8a1.7 1.7 0 1 0 0 3.4 1.7 1.7 0 0 0 0-3.4zm12.3 0a1.7 1.7 0 1 0 0 3.4 1.7 1.7 0 0 0 0-3.4zM13 4.9H3.1v4h11.2V8l-1.3-3.1z" fill="currentColor"/>' +
            '</svg>';

        icon.title =
            'Minivan upgrade is NOT indicated for this city by the current 2× TC sense-check';

        orderCell.appendChild(
            icon
        );

    }

    // ============================================================
    // ORDER# QUICK ACTIONS
    //
    // A normal click on the native Order# link opens a compact action
    // bar inside that Order# cell. Ctrl/Cmd-click is deliberately left
    // completely native so the CRM/browser opens the transfer normally.
    // ============================================================
    // ---- Was this transfer already sent to Final? (1.7.264) ----
    // Read from the transfer page's own task notes, with the same rule the
    // "final bc" tag uses. A raise made after that writes one note only:
    // "raised a bit more to save".
    const WP_AFTER_FINAL_NOTE = 'raised a bit more to save';
    // the address this page was opened with (a job tab cleans its own address right away)
    const WP_PAGE_OPENED_WITH = String(location.search || '');
    function wpPageHasFinalNote() {
        return Array.from(document.querySelectorAll('#transfer-task-list td.task-name, table.transfer-tasks td.task-name')).some(function(cell) {
            const labelEl = cell.querySelector('.task-label');
            const label = String(labelEl ? labelEl.textContent : '').replace(/\s+/g, ' ').trim();
            let note = String(cell.textContent || '');
            if (label && note.indexOf(label) === 0) note = note.slice(label.length);
            try { return wpDetectTransferTag(note).type === 'final'; } catch (_) { return false; }
        });
    }
    function wpPageHasEmNote() {
        return Array.from(document.querySelectorAll('#transfer-task-list td.task-name, table.transfer-tasks td.task-name')).some(function(cell) {
            const labelEl = cell.querySelector('.task-label');
            const label = String(labelEl ? labelEl.textContent : '').replace(/\s+/g, ' ').trim();
            let note = String(cell.textContent || '');
            if (label && note.indexOf(label) === 0) note = note.slice(label.length);
            note = note.replace(/\s+/g, ' ').trim();
            return /^em$/i.test(note) || /^em$/i.test(label) || /\bTransfer marked as EM\b/i.test(note);
        });
    }

    // ---- Quickbar on the transfer page (1.7.264) ----
    // The same quickbar as on the dashboard (Raise % with the new price,
    // Note, BC, Final BC, Apply, A/C Off), opened from a small "Quickbar"
    // button at the bottom left of the transfer page. It is the dashboard's
    // own bar built for this one transfer, so everything it does — the
    // workflow in a background tab, the WhatsApp message — is the same. When
    // the work is done this page loads again to show the result.
    function wpTransferPageQuickbar() {
        if (!wpIsTransferDetailPage() || document.getElementById('wp-page-quickbar')) return;
        // not on the tabs the extension itself opened to do a job
        if (/[?&]wp(City|Quick|AutoCancel|AutoEnable|Tick|BatchCopy)/.test(WP_PAGE_OPENED_WITH + location.search)) return;
        const id = (location.pathname.match(/transfers\/(\d+)/) || [])[1];
        if (!id) return;
        const order = (String(document.title || '').match(/\bw-\d+-\d+\b/) || [])[0];
        let city = '';
        try { city = String(wpFindTransferCity() || ''); } catch (_) {}
        let minutes = null;
        try { minutes = wpParseAcOffMinutes(document.body && document.body.innerText || ''); } catch (_) {}

        const host = document.createElement('div');
        host.id = 'wp-page-quickbar';
        Object.assign(host.style, { position: 'fixed', left: '12px', bottom: '12px', zIndex: '2147482000', display: 'flex', alignItems: 'center', gap: '8px', font: '12px Consolas, "Cascadia Mono", monospace' });
        const table = document.createElement('table');
        Object.assign(table.style, { borderCollapse: 'collapse', margin: '0', width: 'auto', background: 'transparent', border: '0' });
        const row = document.createElement('tr');
        const cell = document.createElement('td');
        cell.className = 'order-number';
        Object.assign(cell.style, { padding: '0', border: '0', background: 'transparent' });
        const link = document.createElement('a');
        link.href = location.pathname;
        link.textContent = 'Quickbar';
        link.title = 'Open the quickbar for this transfer: raise, note, BC, Final BC, A/C Off';
        Object.assign(link.style, { display: 'inline-block', padding: '7px 13px', borderRadius: '9px', background: 'rgba(14,20,22,0.62)', backdropFilter: 'blur(18px)', border: '1px solid rgba(143,255,213,0.45)', color: '#8fffd5', fontWeight: '700', textDecoration: 'none', cursor: 'pointer', boxShadow: '0 6px 18px rgba(0,0,0,0.35)' });
        const tags = document.createElement('td');
        tags.className = 'wp-transfer-tags';
        tags.style.display = 'none';
        tags.textContent = wpPageHasFinalNote() ? 'final bc' : wpPageHasEmNote() ? 'em' : 'no tag';
        const status = document.createElement('span');
        Object.assign(status.style, { display: 'none', padding: '6px 10px', borderRadius: '9px', background: 'rgba(14,20,22,0.80)', border: '1px solid rgba(255,255,255,0.18)', color: '#dfe4e6', maxWidth: '520px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' });
        cell.appendChild(link);
        row.appendChild(cell);
        row.appendChild(tags);
        const body = document.createElement('tbody');
        body.appendChild(row);
        table.appendChild(body);
        host.appendChild(table);
        host.appendChild(status);
        document.body.appendChild(host);

        const say = function(text, tone) {
            status.textContent = text;
            status.style.display = text ? '' : 'none';
            status.style.color = tone === 'error' ? '#ff8a80' : tone === 'ok' ? '#6fd16f' : '#dfe4e6';
        };
        row.__wpTransferPage = true;
        row.__wpCityText = city;
        row.__wpOrderLabel = order ? '#' + order : '#' + id;
        row.__wpAcMinutes = Number(minutes) > 0 ? Number(minutes) : 0;
        // A job was started from the bar: follow it, then show the result.
        row.__wpAfterOpen = function(workflowId, broadcast) {
            const startedAt = Date.now();
            if (!workflowId) {
                say('A/C Off is being done in a background tab — this page loads again in a moment');
                setTimeout(function() { location.reload(); }, 12000);
                return;
            }
            say('Working in a background tab…');
            let resultAt = 0;
            const timer = setInterval(function() {
                let result = null, closed = 0;
                try { result = JSON.parse(localStorage.getItem('wp_batch_result_v1_' + workflowId + '_0') || 'null'); } catch (_) {}
                try { closed = Number(localStorage.getItem('wp_batch_closed_v1_' + workflowId + '_0')) || 0; } catch (_) {}
                if (result && result.status === 'failed') {
                    clearInterval(timer);
                    say('Failed: ' + (result.reason || 'see the workflow tab') + ' — the workflow tab was left open', 'error');
                    return;
                }
                if (result && !resultAt) { resultAt = Date.now(); say(result.status === 'skipped' ? 'Nothing to do: ' + (result.reason || '') : 'Done — finishing…', 'ok'); }
                // the WhatsApp message is prepared from this page: wait for it
                const handOff = broadcast && row.__wpHandOffBusy;
                if ((closed || (resultAt && Date.now() - resultAt > 95000)) && !handOff) {
                    clearInterval(timer);
                    say('Done — loading the page again', 'ok');
                    setTimeout(function() { location.reload(); }, broadcast ? 6000 : 1500);
                } else if (Date.now() - startedAt > 5 * 60000) {
                    clearInterval(timer);
                    say('No result after 5 minutes — check the workflow tab', 'error');
                }
            }, 1000);
        };
        wpSetupOrderQuickActions(row);
    }

    function wpSetupOrderQuickActions(row) {
        if (!(row instanceof HTMLElement)) return;

        const orderLink = typeof wpGetTransferHistoryLinkFromRow === 'function'
            ? wpGetTransferHistoryLinkFromRow(row) : null;
        if (!orderLink) return;
        const orderCell = orderLink.closest('td');
        if (!orderCell || orderCell.dataset.wpOrderQuickActionsInstalled === '1') return;
        orderCell.dataset.wpOrderQuickActionsInstalled = '1';

        const transferUrl = orderLink.href;
        const tagsCell = getTransferTagsCell(row);
        const tagText = tagsCell ? String(tagsCell.textContent || '').replace(/\s+/g, ' ').trim().toLowerCase() : '';
        const isUntagged = !tagText || tagText === 'no tag';
        // 1.7.264: this bar on the transfer page itself; and a transfer already sent to Final
        const onTransferPage = Boolean(row.__wpTransferPage);
        const isFinalRow = /\bfinal\b/.test(tagText);

        // Performance (1.7.185): the bar (two dropdowns with all their
        // options, a text box, five buttons, two page-wide listeners) used to
        // be built for every row on every refresh — ~20,000 elements for a
        // 480-row list. It is built the first time it is needed: your click
        // on the order number, or a workflow started for this row.
        let quickApi = null;
        function buildQuickBar() {
        if (quickApi) return quickApi;
        // Portal: never put the action bar inside the table/cell.
        const bar = document.createElement('div');
        bar.className = 'wp-order-quick-popout';
        Object.assign(bar.style, {
            position: 'fixed', display: 'none', alignItems: 'center', flexDirection: 'row',
            flexWrap: 'nowrap', gap: '6px', padding: '6px 7px', background: '#111416',
            border: '1px solid rgba(143,255,213,0.28)', borderRadius: '8px', boxSizing: 'border-box',
            width: 'max-content', maxWidth: 'calc(100vw - 12px)', zIndex: '2147483647',
            boxShadow: '0 10px 28px rgba(0,0,0,.55)', pointerEvents: 'auto'
        });

        function cityText() {
            if (row.__wpCityText) return String(row.__wpCityText);
            const cell = getCityCell(row);
            return cell ? String(cell.textContent || '').replace(/\s+/g, ' ').trim() : '';
        }

        function openQuickWorkflow(options) {
            if (!transferUrl) return;
            const workflowId = 'orderquick_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
            try {
                const url = new URL(transferUrl, window.location.href);
                url.searchParams.set('wpCityTaskBatchId', workflowId);
                url.searchParams.set('wpCityTaskIndex', '0');
                url.searchParams.set('wpCityTaskCustomMessage', String(options.customMessage || ''));
                url.searchParams.set('wpCityTaskNeedsEm', options.needsEm ? '1' : '0');
                url.searchParams.set('wpCityTaskRaiseMessage', String(options.raiseMessage || ''));
                url.searchParams.set('wpCityPriceIncrease', String(options.priceIncrease || ''));
                if (options.broadcastMode === 'send' || options.broadcastMode === 'final') {
                    url.searchParams.set('wpCityBroadcastMode', options.broadcastMode);
                } else {
                    url.searchParams.delete('wpCityBroadcastMode');
                }
                // Same 30s A/C re-enable as the Transfer Overview checkbox.
                if (options.broadcastMode === 'send' && options.reenableAc) {
                    url.searchParams.set('wpCityReenableAc30s', '1');
                } else {
                    url.searchParams.delete('wpCityReenableAc30s');
                }
                // BC / Final BC: the tab also collects the CRM Copy Details
                // (same collector as the Transfer Overview), so the WhatsApp
                // message can be put on the clipboard here.
                // 1.7.266: BC without the group (quickbar "BC") has no WhatsApp hand-off
                const isBroadcast = (options.broadcastMode === 'send' || options.broadcastMode === 'final') && !options.noWhatsApp;
                if (isBroadcast) {
                    url.searchParams.set('wpBatchCopyId', workflowId);
                    url.searchParams.set('wpBatchCopyIndex', '0');
                    url.searchParams.set('wpBatchCopyTotal', '1');
                }
                // 1.7.264: mod's own raises keep their notes (it reads its level from them)
                if (options.director) url.searchParams.set('wpByDirector', '1');
                url.searchParams.set('wpAutoRefresh', 'off');
                if (typeof wpRememberTransferCity === 'function') wpRememberTransferCity(transferUrl, cityText());
                if (typeof wpRecordTransferHistory === 'function') wpRecordTransferHistory({city: cityText(), time: '', partner: '', url: transferUrl});
                try { wpOutcomeTrackWorkflow(transferUrl, cityText(), '', options); } catch (_) {}
                if (typeof wpExtensionOpenInTab === 'function') wpExtensionOpenInTab(url.toString(), {active:false, insert:true, setParent:true});
                else window.open(url.toString(), '_blank');
                const parts = [];
                if (options.needsEm) parts.push('EM');
                if (options.priceIncrease) parts.push('raise ' + raiseLabel(options.priceIncrease));
                if (options.customMessage) parts.push('note "' + options.customMessage + '"');
                if (options.broadcastMode === 'send') parts.push('BC (A/C Off)' + (options.reenableAc ? ' + A/C back on after 30s' : '') + (options.noWhatsApp ? ', no WhatsApp group' : ''));
                if (options.broadcastMode === 'final') parts.push('Final BC (A/C On)');
                wpDashLog(orderLabel() + ' (' + (cityText() || '?') + '): workflow tab opened — ' + (parts.join(', ') || 'no actions'));
                wpDashWatchResults(workflowId, [orderLabel()]);
                if (isBroadcast) {
                    // Final BC fallback minutes: the row's AutoCancel countdown.
                    let rowMinutes = null;
                    try {
                        const acCell = getAutoCancelCell(row);
                        rowMinutes = acCell ? parseAutoCancelMinutes(acCell.textContent || '') : null;
                    } catch (_) {}
                    if (!rowMinutes && Number(row.__wpAcMinutes) > 0) rowMinutes = Number(row.__wpAcMinutes);
                    copyBroadcastMessageWhenReady(workflowId, options.broadcastMode, cityText(), options.priceIncrease, rowMinutes);
                }
                try { if (typeof row.__wpAfterOpen === 'function') row.__wpAfterOpen(workflowId, isBroadcast); } catch (_) {}
                return workflowId;
            } catch (_) {}
            return '';
        }
        // mod mode runs this row's BC through the same path (1.7.164).
        row.__wpQuickWorkflow = openQuickWorkflow;

        function orderLabel() {
            if (row.__wpOrderLabel) return String(row.__wpOrderLabel);
            return String(orderLink.textContent || '').replace(/\s+/g, ' ').trim() || 'Transfer';
        }

        function raiseLabel(value) {
            const config = wpGetManagedCostOptions().find(function(item) { return String(item.value) === String(value); });
            const pct = String(value).match(/^pct:([\d.]+):([\d.]+)$/);
            if (!config && pct) return '+' + pct[1] + '% (+' + pct[2] + '% total)';
            return config ? config.label : '+' + value + '%';
        }

        // Waits for the transfer tab's collected details (and, for Italian
        // cities with a raise, the saved new price), then copies the driver
        // message + details so it is ready to paste into WhatsApp. Progress
        // goes to the dashboard debug panel.
        function copyBroadcastMessageWhenReady(copyId, mode, city, raiseValue, rowMinutes) {
            const key = WP_BATCH_COPY_PREFIX + copyId + '_0';
            const label = orderLabel();
            const startedAt = Date.now();
            let detailsAt = 0;
            let waitLogged = false;
            let minutesWaitLogged = false;
            const raised = Boolean(raiseValue && raiseValue !== '0');
            wpDashLog(label + ': collecting details for the WhatsApp message…');
            // Hold the dashboard auto refresh until this hand-off is finished.
            let released = false;
            const release = function() {
                if (released) return;
                released = true;
                if (!onTransferPage) wpDashSetBusy(false);
            };
            // 1.7.264: the transfer page waits for this before it loads again
            row.__wpHandOffBusy = true;
            const finish = function() { row.__wpHandOffBusy = false; };
            if (!onTransferPage) wpDashSetBusy(true);
            // WhatsApp opens only after the copy: the WhatsApp app takes focus
            // and the browser refuses clipboard writes from an unfocused page.
            const timer = window.setInterval(async function() {
                let stored = null;
                try { stored = JSON.parse(localStorage.getItem(key) || 'null'); } catch (_) {}
                if (!stored) {
                    if (Date.now() - startedAt > 90000) {
                        clearInterval(timer);
                        release();
                        wpDashLog(label + ': details not collected in 90s — use Copy Details on the transfer page', 'error');
                        openCityWhatsAppGroup();
                        finish();
                    }
                    return;
                }
                if (stored.assigned) {
                    clearInterval(timer);
                    release();
                    wpDashLog('✓ ' + label + ': driver already assigned — nothing to send');
                    finish();
                    return;
                }
                if (!detailsAt) {
                    detailsAt = Date.now();
                    wpDashLog(label + ': details collected');
                }
                // Italian cities show the price: wait for the raised one.
                let newPrice = '';
                if (raised && stored.price && wpIsItalianPriceCity(city)) {
                    newPrice = wpReadRaisedDriverCost(copyId, 0);
                    if (!newPrice) {
                        if (Date.now() - detailsAt < 90000) {
                            if (!waitLogged) {
                                waitLogged = true;
                                wpDashLog(label + ': waiting for the raised price to be saved…');
                            }
                            return;
                        }
                        newPrice = wpCalculateRaisedDriverCost(stored.price, raiseValue);
                        wpDashLog(label + ': raised price not reported — ' + (newPrice ? 'calculated ' + newPrice : 'using the old price'), 'warn');
                    } else {
                        wpDashLog(label + ': raised price ' + newPrice + ' received');
                    }
                }
                // Final BC minutes: reported by the tab once A/C is ON, else
                // the row's own countdown (right away, no waiting), else a
                // short wait (25s) for the tab, else 59. A long wait made the
                // dashboard lose focus, so the copy (and WhatsApp) never came.
                let acMinutes = null;
                if (mode === 'final') {
                    try { acMinutes = Number(localStorage.getItem(key + '_acmin')) || null; } catch (_) {}
                    if (!acMinutes && Number(rowMinutes) > 0) acMinutes = Number(rowMinutes);
                    // 1.7.270: our own auto-cancel comes sooner (Booking.com at 2:02…): those minutes
                    try { const ours = wpTopCancelMinutes(row); if (ours !== null && (!acMinutes || ours < acMinutes)) acMinutes = ours; } catch (_) {}
                    // 1.7.117: no waiting at all (like BC). Waiting for the tab
                    // to report its minutes held the copy and WhatsApp back.
                    void minutesWaitLogged;
                    wpDashLog(label + ': last call in ' + (acMinutes ? Math.min(59, acMinutes) : 59) + ' minutes' + (acMinutes ? '' : ' (minutes not found)'), acMinutes ? '' : 'warn');
                }
                clearInterval(timer);
                release();
                const text = wpBuildBroadcastWhatsAppText(mode, [{ stored: stored, city: city, newPrice: newPrice, acMinutes: acMinutes }], '');
                if (text && await wpWhatsAppAutoSend(city, text, label)) { finish(); return; }
                if (text && await wpWriteClipboardText(text)) {
                    wpDashLog('✓ ' + label + ': WhatsApp message copied — paste with Ctrl+V');
                    openCityWhatsAppGroup();
                    wpDashLog(label + ': ' + (city || '?') + ' WhatsApp group opened');
                } else if (text) {
                    // The page was not focused, so the browser refused the
                    // copy. WhatsApp still opens now; one click on the
                    // Terminal line copies the message (a click always can).
                    let done = false;
                    openCityWhatsAppGroup();
                    wpDashLog(label + ': ' + (city || '?') + ' WhatsApp group opened');
                    wpDashLog('📋 ' + label + ': click here to copy the WhatsApp message (the dashboard was not focused)', 'warn', function(line) {
                        if (done) return;
                        const ok = wpCopyTextFromUserGesture(text);
                        if (!ok) { wpDashLog(label + ': copy failed', 'error'); return; }
                        done = true;
                        line.style.textDecoration = 'none';
                        line.style.cursor = 'default';
                        wpDashLog('✓ ' + label + ': WhatsApp message copied — paste with Ctrl+V');
                    });
                } else {
                    wpDashLog(label + ': could not read the details — use Copy Details on the transfer page', 'error');
                    openCityWhatsAppGroup();
                }
                finish();
            }, 700);
        }
        function button(label, title, handler) {
            const b=document.createElement('button'); b.type='button'; b.textContent=label; b.title=title;
            Object.assign(b.style,{height:'27px',background:'#111416',color:'#8fffd5',border:'1px solid rgba(143,255,213,.20)',borderRadius:'6px',padding:'4px 9px',fontSize:'11px',fontWeight:'700',cursor:'pointer',whiteSpace:'nowrap',flex:'0 0 auto'});
            b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();handler();}); return b;
        }

        const raise=document.createElement('select'); raise.title='Choose a raise percentage';
        Object.assign(raise.style,{height:'27px',minWidth:'105px',padding:'3px 7px',background:'#111416',color:'#8fffd5',border:'1px solid rgba(143,255,213,.20)',borderRadius:'6px',fontSize:'11px',outline:'none'});
        let o=document.createElement('option'); o.value=''; o.textContent='Raise %'; raise.appendChild(o);
        (typeof wpGetManagedCostOptions==='function'?wpGetManagedCostOptions():[]).forEach(config=>{o=document.createElement('option');o.value=String(config.value);o.textContent=String(config.label||('+'+config.value+'%'));raise.appendChild(o);});

        // 1.7.264: the driver cost this raise gives, shown as soon as a % is picked
        const priceNote=document.createElement('span'); priceNote.title='Driver cost now and after this raise';
        Object.assign(priceNote.style,{display:'none',height:'27px',lineHeight:'27px',padding:'0 8px',color:'#ffd27a',border:'1px solid rgba(255,210,122,.35)',borderRadius:'6px',fontSize:'11px',fontWeight:'700',whiteSpace:'nowrap',flex:'0 0 auto',boxSizing:'border-box'});
        let priceData=null, priceAsked=false;
        function showPrice(){
            const value=String(raise.value||'').trim();
            if(!value){ priceNote.style.display='none'; try{positionBar();}catch(_){} return; }
            priceNote.style.display='';
            if(!priceData){
                priceNote.textContent='DC …';
                if(!priceAsked){
                    priceAsked=true;
                    Promise.resolve().then(function(){ return wpFetchTransferCrmDetails(transferUrl,false); }).then(function(data){ priceData=data&&data.prices?data.prices:{}; showPrice(); },function(){ priceData={}; showPrice(); });
                }
                try{positionBar();}catch(_){}
                return;
            }
            const money=function(amount){ return (Math.round(Number(amount)*100)/100)+'€'; };
            const dc=priceData.dc===null||priceData.dc===undefined?NaN:Number(priceData.dc);
            const config=wpGetManagedCostOptions().find(function(item){ return String(item.value)===value; });
            const next=config&&config.dcEqualsTc ? (priceData.tc===null||priceData.tc===undefined?NaN:Number(priceData.tc)) : Number(wpCalculateRaisedDriverCost(String(dc),value));
            priceNote.textContent=Number.isFinite(dc)&&Number.isFinite(next)&&next>0 ? 'DC '+money(dc)+' → '+money(next) : 'DC: price not read';
            try{positionBar();}catch(_){}
        }
        raise.addEventListener('change',showPrice);

        const note=document.createElement('select'); note.title='Choose a task note';
        Object.assign(note.style,{height:'27px',minWidth:'230px',maxWidth:'340px',padding:'3px 7px',background:'#111416',color:'#8fffd5',border:'1px solid rgba(143,255,213,.20)',borderRadius:'6px',fontSize:'11px',outline:'none',flex:'0 1 300px'});
        o=document.createElement('option');o.value='';o.textContent='Note';note.appendChild(o);
        const notes=typeof wpBuildManagedTaskMessages==='function'?wpBuildManagedTaskMessages():(Array.isArray(WP_TASK_MESSAGES)?WP_TASK_MESSAGES:[]);
        notes.forEach((message,index)=>{o=document.createElement('option');o.value=String(message);o.textContent=(index+1)+'. '+String(message);note.appendChild(o);});
        // Custom note: last option; shows a text box next to the dropdown.
        o=document.createElement('option');o.value='__custom__';o.textContent='Custom note…';note.appendChild(o);
        const customNote=document.createElement('input'); customNote.type='text'; customNote.placeholder='Custom note…'; customNote.title='Custom note';
        Object.assign(customNote.style,{display:'none',height:'27px',width:'200px',boxSizing:'border-box',padding:'3px 8px',background:'#111416',color:'#e8eef0',border:'1px solid rgba(143,255,213,.30)',borderRadius:'6px',fontSize:'11px',outline:'none',flex:'0 1 200px'});
        customNote.addEventListener('click',e=>e.stopPropagation());
        customNote.addEventListener('keydown',e=>e.stopPropagation());

        // "last resort 10% / final"-type notes: the % picks the raise, and
        // "final" makes Apply a Final BC (raise + send to final in one go).
        function noteText(){ return note.value==='__custom__' ? String(customNote.value||'').trim() : String(note.value||'').trim(); }
        function lastResortPercent(text){ const m=/last\s*resort/i.test(text) ? String(text).match(/(\d+(?:[.,]\d+)?)\s*%/) : null; return m ? parseFloat(m[1].replace(',','.')) : null; }
        function raiseValueForPercent(pct){
            const option=Array.from(raise.options).find(op=>op.value===String(pct));
            return option ? option.value : 'pct:'+pct+':'+pct;
        }
        note.addEventListener('change',function(){
            const custom=note.value==='__custom__';
            customNote.style.display=custom?'':'none';
            if(custom){ customNote.value=''; try{customNote.focus();}catch(_){} }
            const pct=lastResortPercent(noteText());
            if(pct!==null && !raise.value){ const v=raiseValueForPercent(pct); if(Array.from(raise.options).some(op=>op.value===v)) raise.value=v; }
            try{ showPrice(); }catch(_){}
            try{ positionBar(); }catch(_){}
        });

        function getQuickWorkflowOptions(broadcastMode) {
            let raiseValue = String(raise.value || '').trim();
            const selectedNote = noteText();
            const customMessage = /^em$/i.test(selectedNote) ? '' : selectedNote;
            // A last-resort note carries its own raise when none is chosen.
            const lastResort = lastResortPercent(selectedNote);
            if (!raiseValue && lastResort !== null) raiseValue = raiseValueForPercent(lastResort);
            // 1.7.264: a raise on a transfer already sent to Final leaves one
            // note only — "raised a bit more to save".
            if (isFinalRow && raiseValue && !wpRuleExceptionFor('afterfinal', cityText())) {
                return {
                    priceIncrease: raiseValue, raiseMessage: WP_AFTER_FINAL_NOTE, customMessage: '', needsEm: false,
                    broadcastMode: broadcastMode || '', reenableAc: Boolean(reenableBox.checked), afterFinal: true
                };
            }
            return {
                priceIncrease: raiseValue,
                raiseMessage: raiseValue && typeof wpGetBatchRaiseTaskMessage === 'function'
                    ? wpGetBatchRaiseTaskMessage(raiseValue)
                    : '',
                customMessage: customMessage,
                needsEm: isUntagged,
                broadcastMode: broadcastMode || '',
                reenableAc: Boolean(reenableBox.checked)
            };
        }

        // 1.7.266: Apply only writes the notes and changes the price — it never sends to BC or Final BC
        const apply=button('Apply','EM if untagged, the raise and its note, the selected note — nothing is broadcast',function(){
            const options = getQuickWorkflowOptions('');
            if(!isUntagged && !options.priceIncrease && !options.customMessage)return;
            openQuickWorkflow(options);
            closeBar();
        });

        // Re-enable A/C 30s after BC (A/C Off): on by default.
        const reenableWrap=document.createElement('label');
        reenableWrap.title='After BC (A/C Off): reload the transfer 30s later and turn AutoCancel back ON (same as the Transfer Overview option)';
        Object.assign(reenableWrap.style,{display:'inline-flex',alignItems:'center',gap:'4px',height:'27px',padding:'0 6px',color:'#8fffd5',fontSize:'11px',fontWeight:'700',cursor:'pointer',whiteSpace:'nowrap',flex:'0 0 auto',userSelect:'none'});
        const reenableBox=document.createElement('input'); reenableBox.type='checkbox';
        Object.assign(reenableBox.style,{margin:'0',width:'13px',height:'13px',accentColor:'#8fffd5',cursor:'pointer'});
        // On by default for every BC (A/C Off); untick it for a one-off. Final BC never re-enables.
        reenableBox.checked = true;
        reenableBox.addEventListener('click',e=>e.stopPropagation());
        reenableWrap.addEventListener('click',e=>e.stopPropagation());
        const reenableText=document.createElement('span'); reenableText.textContent='A/C 30s';
        reenableWrap.appendChild(reenableBox); reenableWrap.appendChild(reenableText);

        // BC / Final BC also open this city's WhatsApp group (the same
        // background-tab hand-off as the Transfer Overview) once the message
        // is on the clipboard. The dashboard is never redirected.
        function openCityWhatsAppGroup(){
            try{ if(typeof wpOpenCityWhatsApp==='function' && cityText()) wpOpenCityWhatsApp(cityText()); }catch(_){}
        }

        // 1.7.266: BC — the same, but no WhatsApp group message
        const broadcastOnly=button('BC','Apply the selected EM/raise/note workflow, then 1-Step Broadcast with AutoCancel OFF — no WhatsApp group. With no note and no raise picked, the note "sent to BC" is added.',function(){
            const bcOptions = getQuickWorkflowOptions('send');
            bcOptions.noWhatsApp = true;
            if (bcOptions.raiseMessage && !bcOptions.afterFinal) bcOptions.raiseMessage = String(bcOptions.raiseMessage).replace(/,\s*Group\b/i, '').replace(/\s+and\s+Group\b/i, '');
            if (!bcOptions.customMessage && !bcOptions.priceIncrease) bcOptions.customMessage = 'sent to BC';
            openQuickWorkflow(bcOptions);
            closeBar();
        });

        const broadcast=button('BC&G','Apply the selected EM/raise/note workflow, then run native 1-Step Broadcast & mark as EM with AutoCancel OFF, and send the message to the city WhatsApp group. With no note and no raise picked, the note "sent to BC and Group" is added.',function(){
            // Just BC, no note and no raise picked: the usual note is added
            // (a raise already writes "raised to +X% DC/ sent to BC, Group") (1.7.198).
            const bcOptions = getQuickWorkflowOptions('send');
            if (!bcOptions.customMessage && !bcOptions.priceIncrease) bcOptions.customMessage = 'sent to BC and Group';
            openQuickWorkflow(bcOptions); // opens WhatsApp after copying the message
            closeBar();
        });

        const finalBroadcast=button('Final BC','Apply the selected EM/raise/note workflow, then run native 1-Step Broadcast & mark as EM with AutoCancel ON; opens the city WhatsApp group. With no note picked, the note "sent to suggested / final BC" is added.',function(){
            // Just Final BC, no note picked: the usual note is added (1.7.198).
            const finalOptions = getQuickWorkflowOptions('final');
            if (!finalOptions.customMessage && !finalOptions.afterFinal) finalOptions.customMessage = 'sent to suggested / final BC';
            openQuickWorkflow(finalOptions); // opens WhatsApp after copying the message
            closeBar();
        });

        // A/C Off: same result as the transfer page's own A/C Off button
        // (untick AutoCancel, Save and Autocheck, add to the Dashboard's
        // A/C Off window), done by the workflow code in a background tab so
        // the operator never has to switch to it. Raise/note are ignored.
        const acOff=button('A/C Off','Open the transfer in the background, turn AutoCancel OFF, save, and add it to the Dashboard A/C Off window',function(){
            if(!transferUrl)return;
            try{
                const url=new URL(transferUrl, window.location.href);
                url.searchParams.set('wpQuickAcOff','1');
                url.searchParams.set('wpAutoRefresh','off');
                if(typeof wpRememberTransferCity==='function')wpRememberTransferCity(transferUrl, cityText());
                if(typeof wpRecordTransferHistory==='function')wpRecordTransferHistory({city: cityText(), time: '', partner: '', url: transferUrl, action: 'acoff'});
                if(typeof wpExtensionOpenInTab==='function')wpExtensionOpenInTab(url.toString(), {active:false, insert:true, setParent:true});
                else window.open(url.toString(), '_blank');
                wpDashLog(orderLabel() + ' (' + (cityText() || '?') + '): A/C Off tab opened');
                try{ if(typeof row.__wpAfterOpen==='function') row.__wpAfterOpen('', false); }catch(_){}
            }catch(_){}
            closeBar();
        });

        // Final BC: dark red everywhere (no bright outline). A/C Off: green,
        // set apart at the end. The A/C 30s box is no longer shown: BC always
        // turns A/C back on after 30s (reenableBox stays checked).
        finalBroadcast.classList.add('wp-final-bc');
        Object.assign(finalBroadcast.style,{background:'#4a0b10',color:'#ffc2c2',borderColor:'#4a0b10'});
        acOff.classList.add('wp-quick-acoff');
        Object.assign(acOff.style,{color:'#6fd16f',borderColor:'rgba(111,209,111,.5)'});
        const acOffGap=document.createElement('span');
        Object.assign(acOffGap.style,{display:'inline-block',width:'14px',flex:'0 0 14px'});

        // Order: Raise / Note / BC (+ A/C 30s) / Final BC / Apply / gap / A/C Off
        bar.appendChild(raise);
        bar.appendChild(priceNote);
        bar.appendChild(note);
        bar.appendChild(customNote);
        bar.appendChild(broadcastOnly);
        bar.appendChild(broadcast);
        bar.appendChild(finalBroadcast);
        bar.appendChild(apply);
        bar.appendChild(acOffGap);
        bar.appendChild(acOff);
        document.documentElement.appendChild(bar);

        function positionBar(){
            if(bar.style.display==='none')return;
            // Opened from the Dispatch view: anchor to that row's order number.
            const viewAnchor=orderCell.__wpViewAnchor&&document.body.contains(orderCell.__wpViewAnchor)&&document.body.classList.contains('wp-dv-page')?orderCell.__wpViewAnchor:null;
            const r=(viewAnchor||orderCell).getBoundingClientRect(), b=bar.getBoundingClientRect(), gap=7;
            let left=r.left, top=r.top-b.height-gap;
            if(top<6) top=r.bottom+gap;
            left=Math.max(6,Math.min(left,window.innerWidth-b.width-6));
            bar.style.left=Math.round(left)+'px'; bar.style.top=Math.round(top)+'px';
        }
        function closeBar(){
            if(bar.style.display==='none')return;
            bar.style.display='none';
            if(!onTransferPage&&typeof wpSetOrderQuickActionOpen==='function')wpSetOrderQuickActionOpen(false);
            window.removeEventListener('resize',positionBar); window.removeEventListener('scroll',positionBar,true);
        }
        function showBar(){
            document.querySelectorAll('.wp-order-quick-popout').forEach(other=>{if(other!==bar&&typeof other.__wpClose==='function')other.__wpClose();});
            bar.style.display='flex';
            if(!onTransferPage&&typeof wpSetOrderQuickActionOpen==='function')wpSetOrderQuickActionOpen(true);
            try{ showPrice(); }catch(_){}
            // Force layout after display so the popup dimensions are known before positioning.
            void bar.offsetWidth; positionBar();
            window.addEventListener('resize',positionBar); window.addEventListener('scroll',positionBar,true);
        }
        function outside(e){if(bar.style.display==='none')return;if(bar.contains(e.target)||orderCell.contains(e.target)||(orderCell.__wpViewAnchor&&orderCell.__wpViewAnchor.contains(e.target)))return;closeBar();}
        bar.__wpClose=closeBar;
        document.addEventListener('mousedown',outside,true);
        window.addEventListener('keydown',e=>{if(e.key==='Escape'&&bar.style.display!=='none')closeBar();});
        quickApi = { bar: bar, show: showBar, close: closeBar, open: openQuickWorkflow };
        return quickApi;
        }

        // Autopilot / mod start this row's workflow through here.
        row.__wpQuickWorkflow = function(options) { return buildQuickBar().open(options); };
        // The phone app presses this row's own quickbar (1.7.216).
        row.__wpQuickBar = function() { return buildQuickBar(); };

        orderLink.addEventListener('click',function(event){
            if(event.ctrlKey||event.metaKey)return;
            event.preventDefault(); event.stopPropagation();
            const api = buildQuickBar();
            if(api.bar.style.display==='none')api.show();else api.close();
        },true);
    }

    function processRow(row) {

        if (
            !(row instanceof HTMLElement)
        ) {
            return;
        }

        // Expanded-detail rows (Transfer row expand) are not transfers.
        if (row.classList.contains('wp-rx-detail')) {
            return;
        }

        // ORDER# QUICK ACTIONS
        wpSetupOrderQuickActions(row);

        // CITY

        const cityCell =
            getCityCell(row);

        if (cityCell) {

            const rowCity =
                cityCell.textContent
                    .replace(/\s+/g, ' ')
                    .trim();

            const transferLink =
                wpGetTransferHistoryLinkFromRow(row);

            if (transferLink && rowCity) {
                wpRememberTransferCity(
                    transferLink.href,
                    rowCity
                );
            }

            setupCity(
                cityCell
            );

        }

        // PARTNER

        const partnerCell =
            getPartnerCell(row);

        const isBooking =
            setupPartner(
                partnerCell
            );

        // FINAL TASK HIGHLIGHT

        highlightFinalTask(row);

        // TO LOCATION KEYWORDS

        updateToLocationIcon(row);

        // AUTOCANCEL WARNING

        setAutoCancelState(row);

        // TBO

        const tboCell =
            getTBOCell(row);

        applyMinivanUpgradeIcon(
            row,
            cityCell,
            tboCell
        );

        if (tboCell) {

            const minutes =
                parseTBO(
                    tboCell.textContent
                );

            setTBOState(
                row,
                minutes,
                isBooking
            );

        }

        /*
         * The old per-row stopwatch is retired.
         * Reminders is now the only reminder/timer system.
         */
        const oldTimer =
            row.querySelector(
                '.wp-driver-timer'
            );

        if (oldTimer) {
            oldTimer.remove();
        }

        const oldTimerButton =
            row.querySelector(
                '.wp-timer-button'
            );

        if (oldTimerButton) {
            oldTimerButton.remove();
        }

        row.classList.remove(
            'wp-timer-finished'
        );

    }

    // ============================================================
    // PERSISTENT CUSTOM TIMER STORAGE
    //
    // The CRM page is refreshed every 30 seconds. The timer stores
    // its absolute end time so the refresh cannot reset it.
    // ============================================================

    const WP_TIMER_STORAGE_KEY =
        'wp_transfer_custom_timers_v25';

    function getTimerStorage() {

        try {

            return JSON.parse(
                localStorage.getItem(
                    WP_TIMER_STORAGE_KEY
                ) || '{}'
            );

        } catch (error) {

            return {};

        }

    }

    function saveTimerStorage(storage) {

        try {

            localStorage.setItem(
                WP_TIMER_STORAGE_KEY,
                JSON.stringify(storage)
            );

        } catch (error) {

            console.warn(
                'Could not save timer:',
                error
            );

        }

    }





    function cleanupTimerStorage() {

        const storage =
            getTimerStorage();

        const now =
            Date.now();

        let changed = false;

        Object.keys(storage).forEach(function(key) {

            const timer =
                storage[key];

            if (
                !timer ||
                !timer.endAt
            ) {

                delete storage[key];
                changed = true;
                return;

            }

            // Keep completed timers for 10 minutes so a refresh
            // immediately after completion cannot replay them.
            if (
                timer.alarmPlayed &&
                now - timer.endAt > 10 * 60 * 1000
            ) {

                delete storage[key];
                changed = true;

            }

        });

        if (changed) {
            saveTimerStorage(storage);
        }

    }

