    // ============================================================
    // MOVE AUTOCANCEL NEXT TO CITY
    //
    // Desired order:
    // City | AutoCancel | TBO | Tags | Partner | Order# | ... | S | Driver
    //
    // IMPORTANT:
    // We only move AutoCancel. Everything else keeps its existing
    // relative order. This avoids breaking the CRM table structure.
    // ============================================================

    function arrangeColumns() {

        document.querySelectorAll('table.transfers').forEach(function(table) {

            // Expanded-detail rows (Transfer row expand) are skipped.
            const bodyRows = Array.from(
                table.querySelectorAll(':scope > tbody > tr')
            ).filter(function(row) {
                return !row.classList.contains('wp-rx-detail');
            });

            if (!bodyRows.length) {
                return;
            }

            const headerRow = bodyRows.find(function(row) {
                return row.querySelector('th');
            });

            if (!headerRow) {
                return;
            }

            function headerText(cell) {
                return String(cell.textContent || '')
                    .trim()
                    .toLowerCase()
                    .replace(/\s+/g, ' ');
            }

            function getPositions() {
                const headers = wpBaseCells(headerRow);

                return {
                    city: headers.findIndex(function(cell) {
                        return headerText(cell) === 'city';
                    }),
                    partner: headers.findIndex(function(cell) {
                        return headerText(cell) === 'partner';
                    }),
                    tbo: headers.findIndex(function(cell) {
                        return headerText(cell) === 'tbo';
                    }),
                    autocancel: headers.findIndex(function(cell) {
                        return headerText(cell).replace(/\s+/g, '').includes('autocancel');
                    }),
                    order: headers.findIndex(function(cell) {
                        const h = headerText(cell);
                        return h === 'order#' || h === 'order';
                    }),
                    lastTask: headers.findIndex(function(cell) {
                        return headerText(cell).includes('last transfer task');
                    }),
                    date: headers.findIndex(function(cell) {
                        const h = headerText(cell);
                        return h === 'datetime' || h === 'date time';
                    }),
                    traveler: headers.findIndex(function(cell) {
                        const h = headerText(cell);
                        return h === 'traveler' || h === 'traveller';
                    }),
                    tags: headers.findIndex(function(cell) {
                        return headerText(cell) === 'tags';
                    }),
                    from: headers.findIndex(function(cell) {
                        return headerText(cell) === 'from';
                    }),
                    to: headers.findIndex(function(cell) {
                        return headerText(cell) === 'to';
                    }),
                    s: headers.findIndex(function(cell) {
                        return headerText(cell) === 's';
                    }),
                    priority: headers.findIndex(function(cell) {
                        return headerText(cell) === 'priority';
                    }),
                    driver: headers.findIndex(function(cell) {
                        return headerText(cell) === 'driver';
                    })
                };
            }

            let positions = getPositions();

            if (positions.tags === -1) {
                const tagHeader = document.createElement('th');
                tagHeader.textContent = 'Tags';
                tagHeader.className = 'wp-transfer-tags';
                headerRow.appendChild(tagHeader);
                positions = getPositions();
            }

            const requiredKeys = [
                'city',
                'partner',
                'tbo',
                'autocancel',
                'order',
                'lastTask',
                'date',
                'traveler',
                'tags',
                'from',
                'to',
                's',
                'priority',
                'driver'
            ];

            if (requiredKeys.some(function(key) {
                return positions[key] < 0;
            })) {
                return;
            }

            const desiredKeys = [
                'city',
                'partner',
                'tbo',
                'autocancel',
                'order',
                'tags',
                'date',
                'traveler',
                'from',
                'to',
                'lastTask',
                's',
                'priority',
                'driver'
            ];

            function applyCellClasses(cell, key) {
                if (!cell) {
                    return;
                }

                if (key === 'autocancel') {
                    cell.classList.add('wp-autocancel-cell');
                }

                if (key === 'partner') {
                    cell.classList.add('wp-partner-cell');
                }

                if (key === 'from') {
                    cell.classList.add('wp-from-cell');
                }

                if (key === 'to') {
                    cell.classList.add('wp-to-cell');
                }

                if (key === 'lastTask') {
                    cell.classList.add('wp-last-transfer-task');
                }

                if (key === 'tags') {
                    cell.classList.add('wp-transfer-tags');
                }

                if (key === 's') {
                    cell.classList.add('wp-s-cell');
                }
            }

            function wpStyleSCell(cell) {
                if (!cell) {
                    return;
                }

                cell.classList.add('wp-s-cell');

                /* The CRM's S cell shows "<span.transfer_em_hailing>Em</span>
                 * (2d 5h 10m)": the timer is the time spent in EM hailing and
                 * only exists together with that Em label (verified on the live
                 * CRM). Read the full duration BEFORE the display text is
                 * shortened below, so minutes are not lost. */
                const emLabel = cell.querySelector('.transfer_em_hailing');
                const rawText = String(cell.textContent || '').replace(/\s+/g, ' ');
                const rawDays = rawText.match(/(\d+)\s*d\b/i);
                const rawHours = rawText.match(/(\d+)\s*h\b/i);
                const rawMinutes = rawText.match(/(\d+)\s*m\b/i);
                if (rawDays || rawHours || rawMinutes) {
                    const totalMinutes =
                        (rawDays ? parseInt(rawDays[1], 10) * 1440 : 0) +
                        (rawHours ? parseInt(rawHours[1], 10) * 60 : 0) +
                        (rawMinutes ? parseInt(rawMinutes[1], 10) : 0);
                    // Later passes see the shortened text (no minutes), so keep
                    // the largest value read for this cell.
                    if (!(Number(cell.dataset.wpEmMinutes) >= totalMinutes)) {
                        cell.dataset.wpEmMinutes = String(totalMinutes);
                    }
                }

                /* Remove only the visual parentheses from text nodes. We do not
                 * rebuild the S cell or move native CRM elements around. */
                const walker = document.createTreeWalker(
                    cell,
                    NodeFilter.SHOW_TEXT
                );

                const textNodes = [];
                let currentNode;

                while ((currentNode = walker.nextNode())) {
                    textNodes.push(currentNode);
                }

                textNodes.forEach(function(node) {
                    // The Em Hailing label is kept and shown as a red "EM".
                    if (emLabel && emLabel.contains(node)) {
                        if (node.nodeValue !== 'EM') node.nodeValue = 'EM';
                        return;
                    }
                    const cleaned = String(node.nodeValue || '')
                        .replace(/[()]/g, '')
                        // Remove the CRM's standalone H status label.
                        .replace(/\bEm\b/gi, '')
                        .replace(/\bH\b/gi, '')
                        // Keep days/hours only for the S timer.
                        .replace(/(\d+\s*d(?:\s+\d+\s*h)?|\d+\s*h)\s+\d+\s*m\b/gi, '$1')
                        // Under an hour: show the minutes (e.g. "45m").
                        .replace(/\s{2,}/g, ' ')
                        .trim();
                    if (node.nodeValue !== cleaned) node.nodeValue = cleaned;
                });

                if (emLabel) {
                    emLabel.classList.add('wp-s-em-label');
                }

                /* Remove any H / Em wrappers left by an earlier script version.
                 * H and Em should remain plain CRM text. */
                cell.querySelectorAll('.wp-s-pill-h, .wp-s-pill-em').forEach(function(element) {
                    const parent = element.parentNode;
                    if (!parent) {
                        return;
                    }

                    while (element.firstChild) {
                        parent.insertBefore(element.firstChild, element);
                    }
                    parent.removeChild(element);
                });

                const text = String(cell.textContent || '')
                    .replace(/\s+/g, ' ')
                    .trim();

                const dayMatch = text.match(/(\d+)\s*d\b/i);
                const days = dayMatch
                    ? parseInt(dayMatch[1], 10)
                    : 0;
                const emMinutes = Number(cell.dataset.wpEmMinutes) || 0;

                // Red: more than 2 days in EM hailing AND the Em label is
                // there. Otherwise 1 day or more stays orange.
                const wantRed = Boolean(emLabel && emMinutes > 2 * 24 * 60);
                const wantOrange = !wantRed && days >= 1;
                if (wantRed) cell.classList.add('wp-s-red'); else cell.classList.remove('wp-s-red');
                if (wantOrange) cell.classList.add('wp-s-orange'); else cell.classList.remove('wp-s-orange');
            }

            /*
             * Snapshot every row against the CURRENT header positions before
             * changing the header. This is critical: once the header is moved,
             * its indices no longer describe the current data-row indices.
             *
             * A missing synthetic Tags cell is handled explicitly. When the
             * header has Tags but a data row has one fewer cell, everything
             * after Tags is shifted left by one in that row.
             */
            const headerCellsBefore = wpBaseCells(headerRow);
            const rowSnapshots = new Map();

            bodyRows
                .filter(function(row) {
                    return row !== headerRow;
                })
                .forEach(function(row) {

                    const cells = wpBaseCells(row);
                    const tagCellExisting = row.querySelector(':scope > td.wp-transfer-tags');
                    const missingTagCell =
                        !tagCellExisting &&
                        positions.tags >= 0 &&
                        cells.length === headerCellsBefore.length - 1;

                    const snapshot = {};

                    requiredKeys.forEach(function(key) {
                        const pos = positions[key];

                        if (key === 'tags' && missingTagCell) {
                            snapshot[key] = null;
                            return;
                        }

                        let rowIndex = pos;

                        if (missingTagCell && pos > positions.tags) {
                            rowIndex -= 1;
                        }

                        snapshot[key] = cells[rowIndex] || null;
                    });

                    if (!snapshot.tags && tagCellExisting) {
                        snapshot.tags = tagCellExisting;
                    }

                    rowSnapshots.set(row, snapshot);
                });

            // Snapshot the header cells before reordering.
            const headerByKey = {};
            requiredKeys.forEach(function(key) {
                headerByKey[key] = headerCellsBefore[positions[key]] || null;
            });

            // Performance (1.7.185): this ran every 4 s and re-inserted every
            // cell of every row even when the order was already right (the
            // browser then lays the whole table out again). Cells are moved
            // only when they are not in the wanted order.
            const alreadyOrdered = function(row, wanted) {
                const base = wpBaseCells(row);
                if (base.length < wanted.length) return false;
                for (let i = 0; i < wanted.length; i++) {
                    if (base[i] !== wanted[i]) return false;
                }
                return true;
            };

            // Reorder the header.
            const headerWanted = desiredKeys.map(function(key) { return headerByKey[key]; }).filter(Boolean);
            const headerOrdered = alreadyOrdered(headerRow, headerWanted);
            desiredKeys.forEach(function(key) {
                const cell = headerByKey[key];
                if (!cell) {
                    return;
                }

                applyCellClasses(cell, key);
                if (!headerOrdered) headerRow.appendChild(cell);
            });

            // Rebuild every data row from its semantic snapshot.
            rowSnapshots.forEach(function(snapshot, row) {

                if (!snapshot.tags) {
                    snapshot.tags = document.createElement('td');
                    snapshot.tags.className = 'wp-transfer-tags';
                }

                const rowWanted = desiredKeys.map(function(key) { return snapshot[key]; }).filter(Boolean);
                const rowOrdered = alreadyOrdered(row, rowWanted);
                desiredKeys.forEach(function(key) {
                    const cell = snapshot[key];
                    if (!cell) {
                        return;
                    }

                    applyCellClasses(cell, key);
                    if (!rowOrdered) row.appendChild(cell);
                });

                // If the CRM inserted an unexpected extra cell into the row,
                // remove only the trailing extras. The semantic cells above
                // have already been restored in the correct order.
                while (wpBaseCells(row).length > wpBaseCells(headerRow).length) {
                    const baseCells = wpBaseCells(row);
                    baseCells[baseCells.length - 1].remove();
                }

                wpStyleSCell(row.querySelector('td.wp-s-cell'));
            });

            // Populate Tags only after the semantic order is final.
            rowSnapshots.forEach(function(snapshot, row) {
                const taskCell = row.querySelector('td.wp-last-transfer-task');
                const tagCell = row.querySelector('td.wp-transfer-tags');

                if (!taskCell || !tagCell) {
                    return;
                }

                const sourceText =
                    taskCell.dataset.wpOriginalTask ||
                    String(taskCell.textContent || '')
                        .replace(/\s+/g, ' ')
                        .trim();

                wpUpdateTransferTag(row, sourceText);
            });
        });
    }

    // ============================================================
    // TRANSFER FOCUS MODE
    // ============================================================

    let WP_TRANSFER_FOCUS_MODE = '';

    function wpGetTransferFocusLinkCell(row) {
        if (!row) {
            return null;
        }

        const preferred =
            row.querySelector('td.order-number a[href]');

        if (preferred) {
            return preferred.closest('td');
        }

        const links =
            Array.from(
                row.querySelectorAll('a[href]')
            );

        for (const link of links) {
            const href =
                String(
                    link.getAttribute('href') ||
                    ''
                );

            if (!href) {
                continue;
            }

            if (
                /\/admin\/transfers\//i.test(href) &&
                !/\/admin\/transfers\/index_v2(?:\/|$)/i.test(href)
            ) {
                return link.closest('td');
            }
        }

        return null;
    }

    function wpClearTransferFocus() {
        document
            .querySelectorAll('table.transfers.wp-transfer-focus-active')
            .forEach(function(table) {
                table.classList.remove(
                    'wp-transfer-focus-active'
                );
            });

        document
            .querySelectorAll(
                'table.transfers .wp-transfer-focus-match, ' +
                'table.transfers .wp-transfer-focus-keep'
            )
            .forEach(function(element) {
                element.classList.remove(
                    'wp-transfer-focus-match',
                    'wp-transfer-focus-keep',
                    'wp-transfer-focus-whole'
                );
            });

        WP_TRANSFER_FOCUS_MODE = '';
    }

    function wpApplyTransferFocus(mode) {
        if (
            WP_TRANSFER_FOCUS_MODE === mode
        ) {
            wpClearTransferFocus();
            return;
        }

        wpClearTransferFocus();
        WP_TRANSFER_FOCUS_MODE = mode;

        document
            .querySelectorAll('table.transfers')
            .forEach(function(table) {
                const rows =
                    Array.from(
                        table.querySelectorAll(':scope > tbody > tr')
                    );

                let hasMatch = false;

                rows.forEach(function(row) {
                    const partnerCell =
                        row.querySelector('td.partner');

                    const tagsCell =
                        row.querySelector('td.wp-transfer-tags');

                    const isBooking =
                        Boolean(
                            partnerCell &&
                            partnerCell.classList.contains('wp-booking')
                        );

                    const isAirbnb =
                        Boolean(
                            partnerCell &&
                            partnerCell.classList.contains('wp-airbnb')
                        );

                    const isNoTag =
                        Boolean(
                            tagsCell &&
                            tagsCell.querySelector('.wp-transfer-tag-no-tag')
                        );

                    const isFinalBc =
                        Boolean(
                            tagsCell &&
                            tagsCell.querySelector('.wp-transfer-tag-final')
                        );

                    const tboCell =
                        row.querySelector('td.wp-tbo-cell');

                    const isTboRed =
                        Boolean(
                            tboCell &&
                            (
                                row.classList.contains('wp-tbo-red') ||
                                row.classList.contains('wp-tbo-flash') ||
                                tboCell.classList.contains('wp-tbo-red') ||
                                tboCell.classList.contains('wp-tbo-flash')
                            )
                        );

                    const sCell =
                        row.querySelector('td.wp-s-cell');

                    const isSOrange =
                        Boolean(
                            sCell &&
                            sCell.classList.contains('wp-s-orange')
                        );

                    const isSRed =
                        Boolean(
                            sCell &&
                            sCell.classList.contains('wp-s-red')
                        );

                    const autoCancelCell =
                        row.querySelector('td.wp-autocancel-cell');

                    const isAutoCancelOrange =
                        Boolean(
                            autoCancelCell &&
                            autoCancelCell.classList.contains('wp-autocancel-orange')
                        );

                    const isAutoCancelRed =
                        Boolean(
                            autoCancelCell &&
                            autoCancelCell.classList.contains('wp-autocancel-red')
                        );

                    const cityCell =
                        row.querySelector('td.wp-city-link') ||
                        row.querySelector('td.city');

                    const rowCity =
                        wpNormalizeCityKey(
                            cityCell ? cityCell.textContent : ''
                        );

                    let match = false;

                    if (mode === 'booking') {
                        match = isBooking;
                    } else if (mode === 'airbnb') {
                        match = isAirbnb;
                    } else if (mode === 'no-tag') {
                        match = isNoTag;
                    } else if (mode === 'final-bc') {
                        match = isFinalBc;
                    } else if (mode === 'tbo-red') {
                        match = isTboRed;
                    } else if (mode === 's-orange') {
                        match = isSOrange;
                    } else if (mode === 's-red') {
                        match = isSRed;
                    } else if (mode === 'autocancel-orange') {
                        // Clicking an orange timer focuses every transfer
                        // with less than one hour remaining: orange + red.
                        match = isAutoCancelOrange || isAutoCancelRed;
                    } else if (mode === 'autocancel-red') {
                        match = isAutoCancelRed;
                    } else if (mode.indexOf('city:') === 0) {
                        match = rowCity === mode.slice(5);
                    }

                    if (!match) {
                        return;
                    }

                    hasMatch = true;
                    row.classList.add(
                        'wp-transfer-focus-match'
                    );

                    // 1.7.296: a city's transfers are shown whole
                    if (mode.indexOf('city:') === 0) {
                        row.classList.add(
                            'wp-transfer-focus-whole'
                        );
                    }

                    /*
                     * When a focus is active, keep the contextual columns
                     * visible on every matching row. This is intentional:
                     * City, Partner, TBO, Tags and S should never be dimmed
                     * because they are the information needed to understand
                     * why the row matched the focus.
                     */
                    if (cityCell) {
                        cityCell.classList.add(
                            'wp-transfer-focus-keep'
                        );
                    }

                    if (partnerCell) {
                        partnerCell.classList.add(
                            'wp-transfer-focus-keep'
                        );
                    }

                    if (tboCell) {
                        tboCell.classList.add(
                            'wp-transfer-focus-keep'
                        );
                    }

                    if (tagsCell) {
                        tagsCell.classList.add(
                            'wp-transfer-focus-keep'
                        );
                    }

                    if (sCell) {
                        sCell.classList.add(
                            'wp-transfer-focus-keep'
                        );
                    }

                    /* Keep the AutoCancel number/timer visible for the
                     * rows that actually match the active focus. */
                    if (autoCancelCell) {
                        autoCancelCell.classList.add(
                            'wp-transfer-focus-keep'
                        );
                    }

                    const linkCell =
                        wpGetTransferFocusLinkCell(row);

                    if (linkCell) {
                        linkCell.classList.add(
                            'wp-transfer-focus-keep'
                        );
                    }
                });

                if (hasMatch) {
                    table.classList.add(
                        'wp-transfer-focus-active'
                    );
                }
            });
    }

    function wpInstallTransferFocusHandlers() {
        if (
            window.__wpTransferFocusHandlersInstalled
        ) {
            return;
        }

        window.__wpTransferFocusHandlersInstalled = true;

        document.addEventListener(
            'click',
            function(event) {
                const target =
                    event.target instanceof Element
                        ? event.target
                        : null;

                if (!target) {
                    return;
                }

                const cityCell =
                    target.closest('td.wp-city-link');

                if (
                    !event.ctrlKey &&
                    cityCell &&
                    cityCell.closest('table.transfers')
                ) {
                    event.preventDefault();
                    event.stopPropagation();

                    const cityKey =
                        wpNormalizeCityKey(
                            cityCell.textContent || ''
                        );

                    if (cityKey) {
                        wpApplyTransferFocus('city:' + cityKey);
                    }

                    return;
                }

                const partnerCell =
                    target.closest('td.partner');

                if (
                    partnerCell &&
                    partnerCell.closest('table.transfers')
                ) {
                    if (
                        partnerCell.classList.contains('wp-booking')
                    ) {
                        event.preventDefault();
                        event.stopPropagation();
                        wpApplyTransferFocus('booking');
                        return;
                    }

                    if (
                        partnerCell.classList.contains('wp-airbnb')
                    ) {
                        event.preventDefault();
                        event.stopPropagation();
                        wpApplyTransferFocus('airbnb');
                        return;
                    }
                }

                const autoCancelCell =
                    target.closest('td.wp-autocancel-cell');

                if (
                    autoCancelCell &&
                    autoCancelCell.closest('table.transfers')
                ) {
                    if (autoCancelCell.classList.contains('wp-autocancel-red')) {
                        event.preventDefault();
                        event.stopPropagation();
                        wpApplyTransferFocus('autocancel-red');
                        return;
                    }

                    if (autoCancelCell.classList.contains('wp-autocancel-orange')) {
                        event.preventDefault();
                        event.stopPropagation();
                        wpApplyTransferFocus('autocancel-orange');
                        return;
                    }
                }

                const sCell =
                    target.closest('td.wp-s-cell');

                if (
                    sCell &&
                    sCell.closest('table.transfers')
                ) {
                    if (sCell.classList.contains('wp-s-red')) {
                        event.preventDefault();
                        event.stopPropagation();
                        wpApplyTransferFocus('s-red');
                        return;
                    }

                    if (sCell.classList.contains('wp-s-orange')) {
                        event.preventDefault();
                        event.stopPropagation();
                        wpApplyTransferFocus('s-orange');
                        return;
                    }
                }

                const finalBc =
                    target.closest(
                        'td.wp-transfer-tags .wp-transfer-tag-final'
                    );

                if (
                    finalBc &&
                    finalBc.closest('table.transfers')
                ) {
                    event.preventDefault();
                    event.stopPropagation();
                    wpApplyTransferFocus('final-bc');
                    return;
                }

                const tboCell =
                    target.closest('td.wp-tbo-cell');

                if (
                    tboCell &&
                    tboCell.closest('table.transfers')
                ) {
                    const tboRow = tboCell.closest('tr');
                    const tboIsRed = Boolean(
                        tboRow &&
                        (
                            tboRow.classList.contains('wp-tbo-red') ||
                            tboRow.classList.contains('wp-tbo-flash') ||
                            tboCell.classList.contains('wp-tbo-red') ||
                            tboCell.classList.contains('wp-tbo-flash')
                        )
                    );

                    if (tboIsRed) {
                        event.preventDefault();
                        event.stopPropagation();
                        wpApplyTransferFocus('tbo-red');
                        return;
                    }
                }

                const noTag =
                    target.closest(
                        'td.wp-transfer-tags .wp-transfer-tag-no-tag'
                    );

                if (
                    noTag &&
                    noTag.closest('table.transfers')
                ) {
                    event.preventDefault();
                    event.stopPropagation();
                    wpApplyTransferFocus('no-tag');
                }
            },
            true
        );

        document.addEventListener(
            'keydown',
            function(event) {
                if (event.key === 'Escape') {
                    wpClearTransferFocus();
                }
            }
        );
    }

    // ============================================================
    // PROCESS PAGE
    // ============================================================

    function wpSoftenPriorityAtRisk() {

        document
            .querySelectorAll('table.transfers td.priority')
            .forEach(function(cell) {

                // Performance (1.7.185): the mark was removed and put back on
                // every pass; now it is only taken off elements that should
                // no longer have it.
                const marked = Array.from(cell.querySelectorAll('.wp-soft-at-risk'));

                const elements = Array.from(
                    cell.querySelectorAll('*')
                );

                let target = elements.find(function(el) {
                    const text = String(el.textContent || '')
                        .replace(/\s+/g, ' ')
                        .trim()
                        .toLowerCase();
                    return text === 'at risk';
                });

                if (!target) {
                    const directText = String(cell.textContent || '')
                        .replace(/\s+/g, ' ')
                        .trim()
                        .toLowerCase();
                    if (directText === 'at risk') {
                        target = cell;
                    }
                }

                const keep = target && target !== cell ? target : null;
                marked.forEach(function(el) {
                    if (el !== keep) el.classList.remove('wp-soft-at-risk');
                });

                if (!keep) {
                    return;
                }

                keep.classList.add('wp-soft-at-risk');
            });
    }

    function processPage() {

        wpRemoveTransferDetailsRedDot();

        wpInstallTransferFocusHandlers();

        wpSoftenPriorityAtRisk();

        // Do this first so all subsequent styling sees the
        // new visual column order.
        arrangeColumns();

        // Performance: only process actual transfer-table rows.
        // The old selector scanned every <tr> on the dashboard, including
        // unrelated CRM panels and hidden UI rows.
        document
            .querySelectorAll('table.transfers > tbody > tr')
            .forEach(
                function (row) {

                    processRow(row);

                }
            );

        try { wpAddPudoColumn(); } catch (_) {}
        try { wpRowCrmRefresh(); } catch (_) {}

    }

    // ============================================================
    // PU / DO COLUMN (1.7.121)
    // ============================================================
    // Right after DateTime: PICKUP (starts at an airport / port / station),
    // DROP-OFF (ends at one) or PU + DO, with ✈ ⚓ 🚆 for the place type.
    // The header cell and every row's cell are added in the same pass, right
    // after the DateTime cell, so the columns always stay aligned.
    function wpAddPudoColumn() {
        if (wpIsTransferDetailPage()) return;
        if (!document.getElementById('wp-pudo-style')) {
            const style = document.createElement('style');
            style.id = 'wp-pudo-style';
            style.textContent = [
                'table.transfers th.wp-pudo-cell, table.transfers td.wp-pudo-cell, table.transfers th.wp-loc-cell, table.transfers td.wp-loc-cell{white-space:nowrap!important;text-align:left!important;width:1%!important}',
                // Calm tags: muted text on a faint box, a hint of colour only.
                'table.transfers td.wp-pudo-cell .wp-pudo-chip{display:inline-block;padding:0 6px;border-radius:4px;font-size:10px;font-weight:600;line-height:16px;letter-spacing:.03em;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.10);color:#b9c2c7}',
                'table.transfers td.wp-pudo-cell .wp-pudo-chip.is-pu{color:#a9d6c7}',
                'table.transfers td.wp-pudo-cell .wp-pudo-chip.is-do{color:#d8c29f}',
                'table.transfers td.wp-pudo-cell .wp-pudo-chip.is-both{color:#b3c4dc}',
                // Car: vehicle type from the CRM page (loaded after the page).
                'table.transfers th.wp-car-cell, table.transfers td.wp-car-cell{white-space:nowrap!important;text-align:center!important;width:1%!important;max-width:84px!important;overflow:hidden!important;text-overflow:ellipsis!important;font-size:11px!important}',
                'table.transfers td.wp-car-cell{color:#aab4b9!important}',
                // 1.7.296: a minivan that is not Booking.com / Airbnb
                'table.transfers td.wp-car-cell.wp-car-minivan{color:#8fffd5!important;font-weight:700!important;background:rgba(143,255,213,.13)!important;box-shadow:inset 0 0 0 1px rgba(143,255,213,.45)!important}',
                // Location icons: the same small badges as the city popup.
                'table.transfers td.wp-loc-cell .wp-loc-badge{display:inline-flex;align-items:center;justify-content:center;width:20px;height:16px;border-radius:4px;font-size:11px;line-height:1;box-sizing:border-box;background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.10);margin-right:3px;vertical-align:middle}'
            ].join('\n');
            (document.head || document.documentElement).appendChild(style);
        }
        document.querySelectorAll('table.transfers').forEach(function(table) {
            const rows = Array.from(table.querySelectorAll(':scope > tbody > tr, :scope > thead > tr'));
            const header = rows.find(function(row) { return row.querySelector('th'); });
            if (!header) return;
            const headerDate = Array.from(header.children).find(function(cell) {
                const text = String(cell.textContent || '').replace(/\s+/g, ' ').trim().toLowerCase();
                return cell.classList.contains('date') || text === 'datetime' || text === 'date time';
            });
            if (!headerDate) return;
            // DateTime's position ignoring our own column (arrangeColumns()
            // may have moved it; it is put back right after DateTime below).
            const withoutPudo = function(list) {
                return Array.from(list).filter(function(cell) { return !cell.classList.contains('wp-pudo-cell') && !cell.classList.contains('wp-loc-cell') && !cell.classList.contains('wp-car-cell'); });
            };
            const dateIndex = withoutPudo(header.children).indexOf(headerDate);
            // Every transfer row needs its DateTime cell.
            const dataRows = rows.filter(function(row) {
                return row !== header && !row.classList.contains('wp-rx-detail') && row.querySelector('td');
            });
            const dateCells = dataRows.map(function(row) {
                return {
                    row: row,
                    date: row.querySelector(':scope > td.date') || withoutPudo(row.children)[dateIndex] || null,
                    cell: row.querySelector(':scope > td.wp-pudo-cell')
                };
            });
            if (dateCells.some(function(entry) { return !entry.date; })) return;
            // DateTime | Car | PU / DO | Loc
            let carTh = header.querySelector(':scope > th.wp-car-cell');
            if (!carTh) {
                carTh = document.createElement('th');
                carTh.className = 'wp-car-cell';
                carTh.textContent = 'Car';
            }
            if (headerDate.nextElementSibling !== carTh) headerDate.insertAdjacentElement('afterend', carTh);
            let th = header.querySelector(':scope > th.wp-pudo-cell');
            if (!th) {
                th = document.createElement('th');
                th.className = 'wp-pudo-cell';
                th.textContent = 'PU / DO';
            }
            if (carTh.nextElementSibling !== th) carTh.insertAdjacentElement('afterend', th);
            let locTh = header.querySelector(':scope > th.wp-loc-cell');
            if (!locTh) {
                locTh = document.createElement('th');
                locTh.className = 'wp-loc-cell';
                locTh.textContent = 'Loc';
            }
            if (th.nextElementSibling !== locTh) th.insertAdjacentElement('afterend', locTh);
            dateCells.forEach(function(entry) {
                let cell = entry.cell;
                if (!cell) {
                    cell = document.createElement('td');
                    cell.className = 'wp-pudo-cell';
                }
                let carCell = entry.row.querySelector(':scope > td.wp-car-cell');
                if (!carCell) {
                    carCell = document.createElement('td');
                    carCell.className = 'wp-car-cell';
                }
                if (entry.date.nextElementSibling !== carCell) entry.date.insertAdjacentElement('afterend', carCell);
                if (carCell.nextElementSibling !== cell) carCell.insertAdjacentElement('afterend', cell);
                let locCell = entry.row.querySelector(':scope > td.wp-loc-cell');
                if (!locCell) {
                    locCell = document.createElement('td');
                    locCell.className = 'wp-loc-cell';
                }
                if (cell.nextElementSibling !== locCell) cell.insertAdjacentElement('afterend', locCell);
                const fromTypes = wpDetectLocationTypesFromText(wpLocationCellText(wpGetRowLocationCell(entry.row, 'from')));
                const toTypes = wpDetectLocationTypesFromText(wpLocationCellText(wpGetRowLocationCell(entry.row, 'to')));
                const pu = fromTypes.airport || fromTypes.port || fromTypes.train;
                const dropoff = toTypes.airport || toTypes.port || toTypes.train;
                const icons = [];
                if (fromTypes.airport || toTypes.airport) icons.push('airport');
                if (fromTypes.port || toTypes.port) icons.push('port');
                if (fromTypes.train || toTypes.train) icons.push('train');
                const label = pu && dropoff ? 'PU + DO' : pu ? 'PICKUP' : dropoff ? 'DROP-OFF' : '';
                const signature = label + '|' + icons.join('');
                if (cell.dataset.wpPudo === signature && locCell.dataset.wpLoc === signature) return;
                cell.dataset.wpPudo = signature;
                locCell.dataset.wpLoc = signature;
                cell.textContent = '';
                if (label) {
                    const chip = document.createElement('span');
                    chip.className = 'wp-pudo-chip ' + (pu && dropoff ? 'is-both' : pu ? 'is-pu' : 'is-do');
                    chip.textContent = label;
                    cell.appendChild(chip);
                }
                locCell.textContent = '';
                icons.forEach(function(type) {
                    const badge = document.createElement('span');
                    badge.className = 'wp-loc-badge';
                    badge.textContent = type === 'airport' ? '✈️' : type === 'port' ? '⚓' : '🚆';
                    badge.title = type === 'airport' ? 'Airport' : type === 'port' ? 'Port' : 'Train / station';
                    locCell.appendChild(badge);
                });
            });
        });
    }

    // ============================================================
    // CRM DATA FOR THE TABLE: real price tags + car (1.7.130)
    // ============================================================
    // Price tags come from the CRM's real prices, not from the notes:
    //   +N%    DC now vs the DC before its first change (Admin History)
    //   dc=tc  DC equals TC
    //   -N TC  TC below its original TC
    // Each row's CRM page is read in the background AFTER the page has
    // loaded (3 at a time). Results are kept for 6 h (localStorage) so a
    // refresh paints them at once, and re-read when older than 5 min.
    function wpCrmPriceTags(data) {
        const out = [];
        if (!data || !data.prices) return out;
        const dc = Number(data.prices.dc);
        const tc = Number(data.prices.tc);
        const tcOrigin = Number(data.prices.tcOrigin);
        if (!Number.isFinite(dc) || data.prices.dc === null) return out;
        const money = function(value) { return (Math.round(value * 10) / 10) + '€'; };
        if (Number.isFinite(tc) && tc > 0 && Math.abs(dc - tc) < 0.05) {
            out.push({ text: 'dc = tc', type: 'dc-tc', title: 'DC ' + money(dc) + ' = TC ' + money(tc) + ' (CRM)' });
        } else if (Number.isFinite(tc) && tc > 0 && dc > tc) {
            // Above DC = TC (1.7.230): the same blue tag, with how far the
            // driver cost is over the traveler cost.
            const over = Math.round((dc / tc - 1) * 1000) / 10;
            out.push({ text: '+' + (over < 0.1 ? '0.1' : over) + '%', type: 'dc-tc', title: 'DC ' + money(dc) + ' is ' + money(dc - tc) + ' above TC ' + money(tc) + ' (CRM)' });
        } else {
            const history = (data.costChanges || [])
                .map(function(change, index) { return { change: change, index: index }; })
                .filter(function(entry) { return entry.change.field === 'DC' && Number(entry.change.from) > 0; });
            if (history.length) {
                const first = history.slice().sort(function(a, b) {
                    return ((Date.parse(a.change.when) || 0) - (Date.parse(b.change.when) || 0)) || (b.index - a.index);
                })[0].change;
                const base = Number(first.from);
                const pct = Math.round((dc / base - 1) * 100);
                if (pct >= 1) {
                    out.push({
                        text: '+' + pct + '%',
                        type: pct >= 20 ? '20' : pct >= 10 ? '10' : 'raised',
                        title: 'DC ' + money(base) + ' → ' + money(dc) + ' (CRM Admin History)'
                    });
                }
            }
        }
        if (Number.isFinite(tcOrigin) && data.prices.tcOrigin !== null && Number.isFinite(tc) && tc < tcOrigin - 0.05) {
            out.push({ text: '-' + (Math.round((tcOrigin - tc) * 10) / 10) + ' TC', type: 'tc-minus', title: 'TC ' + money(tcOrigin) + ' → ' + money(tc) + ' (CRM)' });
        }
        return out;
    }

    var WP_ROW_CRM_KEY = 'wp_row_crm_v1';
    var WP_ROW_CRM_FRESH = 5 * 60 * 1000;
    var WP_ROW_CRM_KEEP = 6 * 60 * 60 * 1000;
    var wpRowCrmStore = null;
    var wpRowCrmQueue = [];
    var wpRowCrmQueued = new Set();
    var wpRowCrmBusy = 0;
    var wpRowCrmStarted = false;
    var wpRowCrmReady = false;

    function wpRowCrmLoad() {
        if (wpRowCrmStore) return wpRowCrmStore;
        try { wpRowCrmStore = JSON.parse(localStorage.getItem(WP_ROW_CRM_KEY) || '{}') || {}; } catch (_) { wpRowCrmStore = {}; }
        const now = Date.now();
        Object.keys(wpRowCrmStore).forEach(function(path) {
            if (!wpRowCrmStore[path] || now - wpRowCrmStore[path].at > WP_ROW_CRM_KEEP) delete wpRowCrmStore[path];
        });
        return wpRowCrmStore;
    }

    function wpRowCrmPath(row) {
        const link = typeof wpGetTransferHistoryLinkFromRow === 'function' ? wpGetTransferHistoryLinkFromRow(row) : null;
        if (!link) return '';
        try { return new URL(link.getAttribute('href') || link.href, location.href).pathname; } catch (_) { return ''; }
    }

    // Price tags into the Tags cell (next to the note tag) + the Car cell.
    function wpRowCrmPaint(row) {
        const path = row && row.dataset.wpCrmPath;
        const entry = path ? wpRowCrmLoad()[path] : null;
        // Own "Price" column next to Tags (falls back to the Tags cell).
        const tagCell = row.querySelector(':scope > td.wp-price-cell') || row.querySelector(':scope > td.wp-transfer-tags');
        // Performance (1.7.182): repainted for every row every 4 s; skipped
        // when the same tags are already there (in the same cell).
        const signature = JSON.stringify([entry && entry.tags || [], entry ? String(entry.car || '') : '']);
        const wanted = entry && entry.tags ? entry.tags.length : 0;
        const carNow = row.querySelector(':scope > td.wp-car-cell');
        // 1.7.296: minivan transfers that are not Booking.com / Airbnb are highlighted
        if (carNow) {
            let minivan = false;
            try {
                const partner = String((getPartnerCell(row) || {}).textContent || '').toLowerCase().replace(/\s+/g, '');
                minivan = Boolean(entry) && wpEmCarClass(entry.car) === 2 && !/booking\.?com|airbnb/.test(partner);
            } catch (_) {}
            if (carNow.classList.contains('wp-car-minivan') !== minivan) carNow.classList.toggle('wp-car-minivan', minivan);
        }
        if (row.dataset.wpCrmSig === signature && tagCell &&
            tagCell.querySelectorAll('.wp-price-tag').length === wanted &&
            row.querySelectorAll(':scope > td .wp-price-tag').length === wanted &&
            (!carNow || carNow.textContent === (entry ? String(entry.car || '') : ''))) {
            return;
        }
        row.dataset.wpCrmSig = signature;
        if (tagCell) {
            row.querySelectorAll(':scope > td .wp-price-tag').forEach(function(node) { node.remove(); });
            (entry && entry.tags || []).forEach(function(tag) {
                const badge = document.createElement('span');
                badge.className = 'wp-transfer-tag wp-price-tag wp-transfer-tag-' + tag.type;
                badge.textContent = tag.text;
                badge.title = tag.title || '';
                badge.style.marginLeft = '3px';
                tagCell.appendChild(badge);
            });
        }
        const carCell = row.querySelector(':scope > td.wp-car-cell');
        if (carCell) {
            const car = entry ? String(entry.car || '') : '';
            if (carCell.textContent !== car) carCell.textContent = car;
            carCell.title = car;
        }
    }

    // Price column right after Tags, kept in place on every run (the column
    // arranging can move unknown cells).
    function wpEnsurePriceColumn() {
        document.querySelectorAll('table.transfers').forEach(function(table) {
            const rows = Array.from(table.querySelectorAll(':scope > thead > tr, :scope > tbody > tr'));
            const header = rows.find(function(row) { return row.querySelector(':scope > th'); });
            if (!header) return;
            const tagsTh = header.querySelector(':scope > th.wp-transfer-tags');
            if (!tagsTh) return;
            let th = header.querySelector(':scope > th.wp-price-cell');
            if (!th) {
                th = document.createElement('th');
                th.className = 'wp-price-cell';
                th.textContent = 'Price';
            }
            if (tagsTh.nextElementSibling !== th) tagsTh.insertAdjacentElement('afterend', th);
            const index = Array.from(header.children).indexOf(th);
            rows.forEach(function(row) {
                if (row === header || row.classList.contains('wp-rx-detail') || !row.querySelector(':scope > td')) return;
                let td = row.querySelector(':scope > td.wp-price-cell');
                if (!td) {
                    td = document.createElement('td');
                    td.className = 'wp-price-cell';
                }
                const tagsTd = row.querySelector(':scope > td.wp-transfer-tags');
                if (tagsTd) {
                    if (tagsTd.nextElementSibling !== td) tagsTd.insertAdjacentElement('afterend', td);
                } else if (row.children[index] !== td) {
                    row.insertBefore(td, row.children[index] || null);
                }
            });
        });
    }

    var wpTodayScanAt = 0;
    function wpRowCrmRefresh() {
        if (wpIsTransferDetailPage()) return;
        try { wpEnsurePriceColumn(); } catch (_) {}
        // Today panel: count today's transfers (at most every 3 s).
        if (Date.now() - wpTodayScanAt > 3000) {
            wpTodayScanAt = Date.now();
            window.setTimeout(function() { try { wpTodayScan(); } catch (_) {} }, 0);
        }
        const store = wpRowCrmLoad();
        const now = Date.now();
        document.querySelectorAll('table.transfers > tbody > tr').forEach(function(row) {
            if (row.classList.contains('wp-rx-detail') || !row.querySelector('td')) return;
            const path = wpRowCrmPath(row);
            if (!path) return;
            if (row.dataset.wpCrmPath !== path) row.dataset.wpCrmPath = path;
            wpRowCrmPaint(row);
            const entry = store[path];
            if ((!entry || now - entry.at > WP_ROW_CRM_FRESH) && !wpRowCrmQueued.has(path)) {
                wpRowCrmQueued.add(path);
                wpRowCrmQueue.push(path);
            }
        });
        if (!wpRowCrmStarted) {
            wpRowCrmStarted = true;
            // Only after the page itself has finished loading.
            const start = function() { window.setTimeout(function() { wpRowCrmReady = true; wpRowCrmPump(); }, 800); };
            if (document.readyState === 'complete') start();
            else window.addEventListener('load', start, { once: true });
        } else {
            wpRowCrmPump();
        }
    }

    // The expanded view has priority: while it loads, the row loader starts
    // nothing new (Chrome allows ~6 connections per site, and the loader's
    // page + history requests were making the expanded view wait).
    var wpRowCrmPausedFor = 0;
    function wpRowCrmPause(on) {
        wpRowCrmPausedFor = Math.max(0, wpRowCrmPausedFor + (on ? 1 : -1));
        if (!wpRowCrmPausedFor) wpRowCrmPump();
    }

    function wpRowCrmPump() {
        if (!wpRowCrmReady || wpRowCrmPausedFor > 0) return;
        while (wpRowCrmBusy < 2 && wpRowCrmQueue.length) {
            const path = wpRowCrmQueue.shift();
            wpRowCrmBusy++;
            wpFetchTransferCrmDetails(path, true).then(function(data) {
                const store = wpRowCrmLoad();
                store[path] = { at: Date.now(), tags: wpCrmPriceTags(data), car: data && data.carType || '' };
                try { localStorage.setItem(WP_ROW_CRM_KEY, JSON.stringify(store)); } catch (_) {}
                document.querySelectorAll('table.transfers > tbody > tr').forEach(function(row) {
                    if (row.dataset.wpCrmPath === path) wpRowCrmPaint(row);
                });
            }).catch(function() {}).then(function() {
                wpRowCrmQueued.delete(path);
                wpRowCrmBusy--;
                wpRowCrmPump();
            });
        }
    }

    // ============================================================
    // DRIVER COST INCREASE CONTROL
    // ============================================================

    // These are the percentage options shown above Driver Cost.
    // They use the original Driver Cost as the base, so selecting
    // 10% and then 20% does NOT compound the increase.
    const WP_DRIVER_COST_INCREASES = [
        5,
        8,
        9,
        10,
        12,
        15,
        20,
        25,
        30
    ];

    // Special option: increase Driver Cost by 8%, but write the
    // standard 20% text into the task field. This is used when a
    // transfer has already been raised and needs another increase.
    const WP_DRIVER_COST_SPECIAL_INCREASES = [
        {
            value: '8plus20task',
            costPercent: 8,
            taskPercent: 20,
            label: '+8% (task 20%)'
        },
        {
            // Driver Cost becomes exactly the Traveler Cost.
            value: 'dctc',
            costPercent: 0,
            taskPercent: 0,
            dcEqualsTc: true,
            label: 'DC = TC'
        }
    ];

    const WP_DC_EQUALS_TC_TASK = 'raised to DC = TC/ sent to BC, Group';

    function wpApplyDriverCostEqualsTravelerCost(field) {
        if (!field) return false;
        const tcField = document.getElementById('transfer_traveler_cost');
        const tc = wpParseDriverCost(tcField ? tcField.value : '');
        if (tc === null || tc <= 0) return false;
        if (!field.dataset.wpDriverCostBase) {
            const original = wpParseDriverCost(field.value);
            if (original !== null) field.dataset.wpDriverCostBase = String(original);
        }
        field.value = String(tc);
        field.dispatchEvent(new Event('input', { bubbles: true }));
        field.dispatchEvent(new Event('change', { bubbles: true }));
        return true;
    }

    function wpParseDriverCost(value) {

        const cleaned =
            String(value || '')
                .replace(/[^\d,.-]/g, '')
                .replace(',', '.');

        const number =
            parseFloat(cleaned);

        return Number.isFinite(number)
            ? number
            : null;

    }

    function wpFindDriverCostField() {

        /*
         * Exact CRM element from the transfer-cost table:
         *
         * <li id="transfer_drivers_cost_input">
         *     <input id="transfer_drivers_cost" ... value="78.6">
         * </li>
         *
         * Use the exact ID first so we never accidentally pick
         * Partner Final TC / Origin Cost / Clean TC / Profit.
         */

        const exact =
            document.getElementById(
                'transfer_drivers_cost'
            );

        if (exact) {
            return exact;
        }

        // Fallback in case the CRM changes only the input ID.
        const container =
            document.getElementById(
                'transfer_drivers_cost_input'
            );

        if (container) {

            const field =
                container.querySelector(
                    'input:not([type="hidden"]), textarea'
                );

            if (field) {
                return field;
            }

        }

        return null;

    }

    function wpApplyDriverCostIncrease(
        field,
        percent
    ) {

        if (!field) {
            return;
        }

        if (
            !field.dataset.wpDriverCostBase
        ) {

            const original =
                wpParseDriverCost(
                    field.value
                );

            if (original === null) {
                return;
            }

            field.dataset.wpDriverCostBase =
                String(original);

        }

        const base =
            parseFloat(
                field.dataset.wpDriverCostBase
            );

        if (!Number.isFinite(base)) {
            return;
        }

        const result =
            base * (1 + percent / 100);

        /*
         * Driver Cost should always be a whole number after the increase.
         * Round UP so we never lose money because of decimals.
         *
         * Example:
         * 52.01 -> 53
         * 52.76 -> 53
         * 53.00 -> 53
         */
        const roundedResult =
            Math.ceil(result - 1e-9); // 30 * 1.1 = 33.000000000000004 stays 33

        /*
         * Preserve the CRM's normal numeric input behaviour:
         * write the calculated integer and fire both events.
         */
        field.value =
            String(roundedResult);

        field.dispatchEvent(
            new Event(
                'input',
                {
                    bubbles: true
                }
            )
        );

        field.dispatchEvent(
            new Event(
                'change',
                {
                    bubbles: true
                }
            )
        );

    }

    function wpSetupDriverCostControl() {

        const field =
            wpFindDriverCostField();

        if (!field) {
            return;
        }

        if (
            field.dataset
                .wpDriverCostControlInstalled === 'true'
        ) {
            return;
        }

        const base =
            wpParseDriverCost(
                field.value
            );

        if (base === null) {
            return;
        }

        field.dataset.wpDriverCostBase =
            String(base);

        field.dataset
            .wpDriverCostControlInstalled =
            'true';

        const control =
            document.createElement(
                'div'
            );

        control.className =
            'wp-driver-cost-control';

        const label =
            document.createElement(
                'span'
            );

        label.className =
            'wp-driver-cost-control-label';

        label.textContent =
            'Increase:';

        const select =
            document.createElement(
                'select'
            );

        select.className =
            'wp-driver-cost-increase';

        select.title =
            'Increase Driver Cost';

        const defaultOption =
            document.createElement(
                'option'
            );

        defaultOption.value =
            '';

        defaultOption.textContent =
            'Choose %';

        select.appendChild(
            defaultOption
        );

        const noIncrease =
            document.createElement(
                'option'
            );

        noIncrease.value =
            '0';

        noIncrease.textContent =
            'No increase';

        select.appendChild(
            noIncrease
        );

        wpGetManagedCostOptions().forEach(
            function(config) {

                const option =
                    document.createElement(
                        'option'
                    );

                option.value =
                    String(config.value);

                option.textContent =
                    config.label;

                select.appendChild(
                    option
                );

            }
        );



        control.appendChild(
            label
        );

        control.appendChild(
            select
        );

        wpAddDropdownManagerButton(
            control,
            'Driver Cost options',
            wpOpenCostDropdownManager
        );

        /*
         * Put the selector immediately above the Driver Cost input.
         * The controls live only in the transfer page, not the list.
         */
        const parent =
            field.closest(
                '#transfer_drivers_cost_input'
            ) ||
            field.parentElement;

        if (!parent) {
            return;
        }

        /*
         * Exact placement:
         * Driver Cost container -> dropdown -> Driver Cost input
         */
        control.style.display =
            'flex';

        control.style.width =
            '100%';

        control.style.boxSizing =
            'border-box';

        control.style.justifyContent =
            'center';

        parent.insertBefore(
            control,
            field
        );

        select.addEventListener(
            'change',
            function() {

                if (
                    select.value === ''
                ) {
                    return;
                }

                let costPercent =
                    parseFloat(
                        select.value
                    );

                let taskPercent =
                    costPercent;

                const managedCostOption =
                    wpGetManagedCostOptions().find(
                        function(config) {
                            return config.value === select.value;
                        }
                    );

                if (managedCostOption) {
                    costPercent =
                        managedCostOption.costPercent;
                    taskPercent =
                        managedCostOption.taskPercent;
                }

                // Raise suggested (EM Project): 'pct:<raise now>:<total>'.
                const suggestedValue = String(select.value).match(/^pct:([\d.]+):([\d.]+)$/);
                if (suggestedValue) {
                    costPercent = parseFloat(suggestedValue[1]);
                    taskPercent = parseFloat(suggestedValue[2]);
                }

                const dcEqualsTc = Boolean(managedCostOption && managedCostOption.dcEqualsTc);
                const dcBeforeRaise = parseFloat(String(field.value || '').replace(',', '.'));

                if (dcEqualsTc) {
                    // Treated like a real raise below (task text + A/C off).
                    if (!wpApplyDriverCostEqualsTravelerCost(field)) return;
                    costPercent = 1;
                    const taskInput = wpFindTaskMessageInput(wpFindRefundSelect());
                    if (taskInput) {
                        taskInput.value = WP_DC_EQUALS_TC_TASK;
                        taskInput.dispatchEvent(new Event('input', { bubbles: true }));
                        taskInput.dispatchEvent(new Event('change', { bubbles: true }));
                    }
                } else {
                    wpApplyDriverCostIncrease(
                        field,
                        costPercent
                    );
                }

                // Restore the original transfer-page behaviour: selecting a
                // real increase from this dropdown automatically prepares the
                // matching raise task text in the CRM task composer. The
                // ordered batch workflow can still clear this exact text after
                // its explicit raise task has been created, so it cannot become
                // a duplicate there.
                if (!dcEqualsTc && costPercent > 0 && typeof wpSetTaskMessageFromDriverCostIncrease === 'function') {
                    wpSetTaskMessageFromDriverCostIncrease(taskPercent);
                }

                // Who raised: the CRM keeps no name for manual raises, so the
                // extension notes the ones made here as "you" (price chip).
                try {
                    const raisedId = (location.pathname.match(/transfers\/(\d+)/) || [])[1];
                    const dcAfterRaise = parseFloat(String(field.value || '').replace(',', '.'));
                    if (raisedId && Number.isFinite(dcAfterRaise)) {
                        const raises = JSON.parse(localStorage.getItem('wp_my_raises_v1') || '{}') || {};
                        Object.keys(raises).forEach(function(key) { if (!raises[key] || Date.now() - raises[key].at > 3 * 86400000) delete raises[key]; });
                        raises[raisedId] = { from: Number.isFinite(dcBeforeRaise) ? dcBeforeRaise : null, to: dcAfterRaise, at: Date.now() };
                        localStorage.setItem('wp_my_raises_v1', JSON.stringify(raises));
                    }
                } catch (_) {}

                // Selecting any real price increase normally means AutoCancel
                // should be turned off for this transfer. EXCEPTION: if the CRM
                // displays its specific Auto-cancellation Threshold warning,
                // AutoCancel must remain enabled for that ride.
                const autoCancelCheckbox =
                    wpFindAutoCancelCheckbox();

                const hasAutoCancelThresholdWarning =
                    wpTransferHasAutoCancelThresholdWarning();

                if (
                    autoCancelCheckbox &&
                    costPercent > 0 &&
                    !hasAutoCancelThresholdWarning
                ) {
                    if (autoCancelCheckbox.checked) {
                        // This AutoCancel disable is caused automatically by
                        // the Driver Cost percentage selection, so treat it
                        // as an intentional disable for the leave warning.
                        wpSetAcOffIntentionalDisable(true);

                        autoCancelCheckbox.checked = false;
                        autoCancelCheckbox.dispatchEvent(
                            new Event(
                                'input',
                                { bubbles: true }
                            )
                        );
                        autoCancelCheckbox.dispatchEvent(
                            new Event(
                                'change',
                                { bubbles: true }
                            )
                        );
                    }
                }

                // Do NOT write a task note into the CRM task field merely because
                // Driver Cost was changed. The selected raise is handled by the
                // batch/quick-action workflow when a note is explicitly requested.

            }
        );

    }

    // ============================================================
    // TRANSFER DROPDOWN OPTION MANAGER
    // ============================================================

    const WP_TRANSFER_DROPDOWN_SETTINGS_KEY =
        'wp_transfer_dropdown_settings_v1';

    function wpGetDropdownSettings() {
        const fallback = {
            task: { hidden: [], custom: [] },
            driver: { hidden: [], custom: [] },
            cost: { hidden: [], custom: [] }
        };

        try {
            const raw = localStorage.getItem(
                WP_TRANSFER_DROPDOWN_SETTINGS_KEY
            );
            if (!raw) return fallback;

            const parsed = JSON.parse(raw);
            if (!parsed || typeof parsed !== 'object') return fallback;

            return {
                task: {
                    hidden: Array.isArray(parsed.task && parsed.task.hidden) ? parsed.task.hidden.map(String) : [],
                    custom: Array.isArray(parsed.task && parsed.task.custom) ? parsed.task.custom.map(String) : []
                },
                driver: {
                    hidden: Array.isArray(parsed.driver && parsed.driver.hidden) ? parsed.driver.hidden.map(String) : [],
                    custom: Array.isArray(parsed.driver && parsed.driver.custom) ? parsed.driver.custom.map(String) : []
                },
                cost: {
                    hidden: Array.isArray(parsed.cost && parsed.cost.hidden) ? parsed.cost.hidden.map(String) : [],
                    custom: Array.isArray(parsed.cost && parsed.cost.custom) ? parsed.cost.custom.map(String) : []
                }
            };
        } catch (error) {
            return fallback;
        }
    }

    function wpSaveDropdownSettings(settings) {
        try {
            localStorage.setItem(
                WP_TRANSFER_DROPDOWN_SETTINGS_KEY,
                JSON.stringify(settings)
            );
        } catch (error) {
            console.warn('Could not save transfer dropdown settings:', error);
        }
    }

    function wpGetManagedTextOptions(type, defaults) {
        const settings = wpGetDropdownSettings()[type];
        const hidden = new Set(settings.hidden.map(String));
        const result = defaults
            .map(String)
            .filter(function(value) { return !hidden.has(value); });

        settings.custom.forEach(function(value) {
            value = String(value || '').trim();
            if (value && !result.includes(value) && !hidden.has(value)) {
                result.push(value);
            }
        });

        return result;
    }

    function wpGetManagedCostOptions() {
        const settings = wpGetDropdownSettings().cost;
        const hidden = new Set(settings.hidden.map(String));
        const result = [];

        WP_DRIVER_COST_INCREASES.forEach(function(percent) {
            const value = String(percent);
            if (!hidden.has(value)) {
                result.push({
                    value: value,
                    label: '+' + percent + '%',
                    costPercent: percent,
                    taskPercent: percent
                });
            }
        });

        WP_DRIVER_COST_SPECIAL_INCREASES.forEach(function(config) {
            if (!hidden.has(String(config.value))) {
                result.push({
                    value: String(config.value),
                    label: config.label,
                    costPercent: config.costPercent,
                    taskPercent: config.taskPercent,
                    dcEqualsTc: Boolean(config.dcEqualsTc)
                });
            }
        });

        settings.custom.forEach(function(raw) {
            const percent = Number(raw);
            if (!Number.isFinite(percent) || percent <= 0) return;
            const value = String(percent);
            if (hidden.has(value) || result.some(function(item) { return item.value === value; })) return;
            result.push({
                value: value,
                label: '+' + percent + '%',
                costPercent: percent,
                taskPercent: percent
            });
        });

        return result;
    }

    function wpOpenDropdownManager(type, title, getRows, addOption, lockedValues) {
        document.querySelectorAll('.wp-dropdown-manager-overlay').forEach(function(node) {
            node.remove();
        });

        const overlay = document.createElement('div');
        overlay.className = 'wp-dropdown-manager-overlay';

        const modal = document.createElement('div');
        modal.className = 'wp-dropdown-manager-modal';

        const head = document.createElement('div');
        head.className = 'wp-dropdown-manager-head';

        const titleEl = document.createElement('div');
        titleEl.className = 'wp-dropdown-manager-title';
        titleEl.textContent = 'Manage ' + title;

        const close = document.createElement('button');
        close.type = 'button';
        close.className = 'wp-dropdown-manager-close';
        close.textContent = '×';
        close.addEventListener('click', function() { overlay.remove(); });

        head.appendChild(titleEl);
        head.appendChild(close);

        const list = document.createElement('div');
        list.className = 'wp-dropdown-manager-list';

        const render = function() {
            list.innerHTML = '';
            getRows().forEach(function(row) {
                const line = document.createElement('div');
                line.className = 'wp-dropdown-manager-row';

                const text = document.createElement('div');
                text.className = 'wp-dropdown-manager-row-text';
                text.textContent = row.label;
                line.appendChild(text);

                if (lockedValues && lockedValues.has(String(row.value))) {
                    const locked = document.createElement('span');
                    locked.className = 'wp-dropdown-manager-locked';
                    locked.textContent = 'required';
                    line.appendChild(locked);
                } else {
                    const remove = document.createElement('button');
                    remove.type = 'button';
                    remove.className = 'wp-dropdown-manager-remove';
                    remove.textContent = 'Remove';
                    remove.addEventListener('click', function() {
                        const settings = wpGetDropdownSettings();
                        const state = settings[type];
                        const value = String(row.value);
                        if (!state.hidden.includes(value)) state.hidden.push(value);
                        state.custom = state.custom.filter(function(item) { return String(item) !== value; });
                        wpSaveDropdownSettings(settings);
                        render();
                        wpRefreshManagedDropdowns();
                    });
                    line.appendChild(remove);
                }

                list.appendChild(line);
            });

            if (!list.children.length) {
                const empty = document.createElement('div');
                empty.className = 'wp-dropdown-manager-row-text';
                empty.textContent = 'No options available.';
                empty.style.opacity = '0.65';
                list.appendChild(empty);
            }
        };

        const add = document.createElement('div');
        add.className = 'wp-dropdown-manager-add';

        const input = document.createElement('input');
        input.type = type === 'cost' ? 'number' : 'text';
        if (type === 'cost') {
            input.min = '0.1';
            input.step = '0.1';
            input.placeholder = 'Increase % (e.g. 18)';
        } else {
            input.placeholder = 'New option';
        }

        const addButton = document.createElement('button');
        addButton.type = 'button';
        addButton.textContent = 'Add permanently';

        const doAdd = function() {
            const value = String(input.value || '').trim();
            if (!value) return;
            if (addOption(value)) {
                input.value = '';
                render();
                wpRefreshManagedDropdowns();
            }
        };

        addButton.addEventListener('click', doAdd);
        input.addEventListener('keydown', function(event) {
            if (event.key === 'Enter') doAdd();
        });

        add.appendChild(input);
        add.appendChild(addButton);

        modal.appendChild(head);
        modal.appendChild(list);
        modal.appendChild(add);
        overlay.appendChild(modal);
        document.body.appendChild(overlay);

        overlay.addEventListener('click', function(event) {
            if (event.target === overlay) overlay.remove();
        });

        render();
        input.focus();
    }

    function wpOpenTaskDropdownManager() {
        wpOpenDropdownManager(
            'task',
            'Task Text options',
            function() {
                const settings = wpGetDropdownSettings().task;
                const hidden = new Set(settings.hidden.map(String));
                const rows = [];

                WP_TASK_MESSAGES.forEach(function(value, index) {
                    if (!hidden.has(String(value))) {
                        rows.push({
                            value: value,
                            label: (index + 1) + '. ' + value
                        });
                    }
                });

                settings.custom.forEach(function(value) {
                    value = String(value || '').trim();
                    if (value && !hidden.has(value) && !WP_TASK_MESSAGES.includes(value)) {
                        rows.push({
                            value: value,
                            label: 'Custom: ' + value
                        });
                    }
                });

                return rows;
            },
            function(value) {
                const settings = wpGetDropdownSettings();
                if (!settings.task.custom.includes(value) && !WP_TASK_MESSAGES.includes(value)) settings.task.custom.push(value);
                settings.task.hidden = settings.task.hidden.filter(function(item) { return String(item) !== value; });
                wpSaveDropdownSettings(settings);
                return true;
            },
            new Set()
        );
    }

    function wpOpenDriverDropdownManager() {
        wpOpenDropdownManager(
            'driver',
            'Driver Message options',
            function() {
                const settings = wpGetDropdownSettings().driver;
                const hidden = new Set(settings.hidden.map(String));
                const rows = [];

                WP_DRIVER_MESSAGES.forEach(function(value, index) {
                    if (!hidden.has(String(value))) {
                        rows.push({
                            value: value,
                            label: (index + 1) + '. ' + value
                        });
                    }
                });

                settings.custom.forEach(function(value) {
                    value = String(value || '').trim();
                    if (value && !hidden.has(value) && !WP_DRIVER_MESSAGES.includes(value)) {
                        rows.push({
                            value: value,
                            label: 'Custom: ' + value
                        });
                    }
                });

                return rows;
            },
            function(value) {
                const settings = wpGetDropdownSettings();
                if (!settings.driver.custom.includes(value) && !WP_DRIVER_MESSAGES.includes(value)) settings.driver.custom.push(value);
                settings.driver.hidden = settings.driver.hidden.filter(function(item) { return String(item) !== value; });
                wpSaveDropdownSettings(settings);
                return true;
            },
            new Set([''])
        );
    }

    function wpOpenCostDropdownManager() {
        wpOpenDropdownManager(
            'cost',
            'Driver Cost options',
            function() {
                return wpGetManagedCostOptions().map(function(item) {
                    return { value: item.value, label: item.label };
                });
            },
            function(value) {
                const percent = Number(value);
                if (!Number.isFinite(percent) || percent <= 0) return false;
                const settings = wpGetDropdownSettings();
                const normalized = String(percent);
                if (!settings.cost.custom.some(function(item) { return String(item) === normalized; })) {
                    settings.cost.custom.push(normalized);
                }
                settings.cost.hidden = settings.cost.hidden.filter(function(item) { return String(item) !== normalized; });
                wpSaveDropdownSettings(settings);
                return true;
            },
            new Set()
        );
    }

    function wpAddDropdownManagerButton(container, title, handler) {
        if (!container || container.querySelector('.wp-dropdown-manager-btn')) return;
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'wp-dropdown-manager-btn';
        button.textContent = '⚙';
        button.title = 'Manage options';
        button.addEventListener('click', function(event) {
            event.preventDefault();
            event.stopPropagation();
            handler();
        });
        container.appendChild(button);
    }

    function wpBuildManagedTaskMessages() {
        return wpGetManagedTextOptions('task', WP_TASK_MESSAGES);
    }

    function wpBuildManagedDriverMessages() {
        return wpGetManagedTextOptions('driver', WP_DRIVER_MESSAGES);
    }

    function wpRefreshManagedDropdowns() {
        const taskSelect = document.querySelector('.wp-task-quick-select');
        if (taskSelect) {
            const previous = taskSelect.value;
            const managed = wpBuildManagedTaskMessages();
            taskSelect.innerHTML = '';
            const placeholder = document.createElement('option');
            placeholder.value = '';
            placeholder.textContent = 'Task text...';
            taskSelect.appendChild(placeholder);
            managed.forEach(function(message, index) {
                const option = document.createElement('option');
                option.value = message;
                option.textContent = (index + 1) + '. ' + message;
                taskSelect.appendChild(option);
            });
            taskSelect.value = managed.includes(previous) ? previous : '';
        }

        document.querySelectorAll('.wp-driver-copy-message').forEach(function(select) {
            const previous = select.value;
            const managed = wpBuildManagedDriverMessages();
            select.innerHTML = '';
            const none = document.createElement('option');
            none.value = '';
            none.textContent = '0. None';
            select.appendChild(none);
            managed.forEach(function(message, index) {
                const option = document.createElement('option');
                option.value = message;
                option.textContent = (index + 1) + '. ' + message;
                select.appendChild(option);
            });
            select.value = managed.includes(previous) ? previous : '';
            wpRefreshLastChanceDriverMessageOptions(select);
        });

        document.querySelectorAll('.wp-driver-cost-increase').forEach(function(select) {
            const previous = select.value;
            const managed = wpGetManagedCostOptions();
            select.innerHTML = '';
            const choose = document.createElement('option');
            choose.value = '';
            choose.textContent = 'Choose %';
            select.appendChild(choose);
            const none = document.createElement('option');
            none.value = '0';
            none.textContent = 'No increase';
            select.appendChild(none);
            managed.forEach(function(item) {
                const option = document.createElement('option');
                option.value = item.value;
                option.textContent = item.label;
                select.appendChild(option);
            });
            select.value = Array.from(select.options).some(function(option) { return option.value === previous; }) ? previous : '';
        });
    }

    // ============================================================
    // TASK QUICK-INSERT DROPDOWN
    // ============================================================

    const WP_TASK_MESSAGES = [
        'em',
        'lmb < 2hrs',
        'sent to BC and Group',
        'sent to suggested',
        'sent to heroes',
        'dc = tc to save',
        'raised a bit more to save',
        'sent to BC, Group and suggested',
        'sent to suggested / final bc',
        'final BC',
        'last resort 10% / final'
    ];

    function wpFindRefundSelect() {

        /*
         * This is the CRM's task-type dropdown. Its current default is
         * often "Refund", which is easy to click accidentally.
         *
         * Find the select that contains both Task and Refund options.
         */
        return Array.from(
            document.querySelectorAll('select')
        ).find(function(select) {

            const options =
                Array.from(
                    select.options || []
                ).map(function(option) {
                    return wpNormalizeDetailText(
                        option.textContent
                    ).toLowerCase();
                });

            return (
                options.some(function(option) {
                    return option === 'task' ||
                           option.startsWith('task ');
                }) &&
                options.some(function(option) {
                    return option === 'refund' ||
                           option.startsWith('refund ');
                })
            );

        }) || null;

    }

    function wpSetTaskTypeDefault() {

        const select =
            wpFindRefundSelect();

        if (!select) {
            return;
        }

        const taskOption =
            Array.from(
                select.options || []
            ).find(function(option) {

                const value =
                    wpNormalizeDetailText(
                        option.textContent
                    ).toLowerCase();

                return (
                    value === 'task' ||
                    value.startsWith('task ')
                );

            });

        if (!taskOption) {
            return;
        }

        /*
         * Only change it when the CRM has it on something else.
         * This prevents unnecessary change events.
         */
        if (
            select.selectedIndex !==
            taskOption.index
        ) {

            select.value =
                taskOption.value;

            select.selectedIndex =
                taskOption.index;

            select.dispatchEvent(
                new Event(
                    'change',
                    {
                        bubbles: true
                    }
                )
            );

        }

    }

    function wpFindTaskMessageInput(refundSelect) {

        if (!refundSelect) {
            return null;
        }

        const containers = [
            refundSelect.closest('tr'),
            refundSelect.parentElement,
            refundSelect.parentElement?.parentElement,
            refundSelect.parentElement?.parentElement?.parentElement
        ].filter(Boolean);

        for (const container of containers) {

            const fields =
                Array.from(
                    container.querySelectorAll(
                        'input:not([type="hidden"]), textarea'
                    )
                );

            const field =
                fields.find(function(candidate) {

                    const type =
                        (candidate.type || '')
                            .toLowerCase();

                    return (
                        type !== 'checkbox' &&
                        type !== 'button' &&
                        type !== 'submit'
                    );

                });

            if (field) {
                return field;
            }

        }

        return null;

    }

    function wpGetCurrentAcMinutesForDriverMessage() {

        /*
         * Use the SAME exact Auto-Cancellation text parser as the
         * A/C Off feature.  This avoids accidentally picking up another
         * countdown elsewhere on the transfer page.
         *
         * Expected examples:
         *   "Auto-Cancellation scheduled in 29m"
         *   "Auto-Cancellation scheduled in 1h 20m"
         *
         * If the CRM does not expose that value, use the requested
         * 59-minute fallback.
         */

        try {

            const sources = [];

            if (document.body) {
                sources.push(document.body.innerText || '');
            }

            const checkbox = wpFindAutoCancelCheckbox();

            if (checkbox) {

                let ancestor = checkbox.parentElement;

                for (let depth = 0; ancestor && depth < 6; depth += 1) {
                    sources.push(
                        ancestor.innerText ||
                        ancestor.textContent ||
                        ''
                    );
                    ancestor = ancestor.parentElement;
                }

            }

            for (const source of sources) {

                const minutes =
                    wpParseAcOffMinutes(source);

                // The shared parser returns 0 for a phrase without a number
                // ("…Auto-Cancellation … in" with no time), which used to put
                // "0 minutes" in messages 7 / 8. Only a real time counts, and
                // the message never says more than 59 minutes.
                if (Number.isFinite(minutes) && minutes > 0) {
                    return Math.min(59, minutes);
                }

            }

        } catch (error) {
            console.warn(
                'Could not read current AutoCancel minutes for driver message:',
                error
            );
        }

        return 59;

    }

    function wpGetDriverMessageMinutes() {

        return wpGetCurrentAcMinutesForDriverMessage();

    }

    function wpFormatDriverMessageWithAcMinutes(message) {

        const selectedMessage = String(message || '');

        const minutes =
            wpGetDriverMessageMinutes();

        const isLastChance =
            selectedMessage === WP_DRIVER_MESSAGES[6] ||
            /^7\.\s*LAST CHANCE FOR THIS ONE!/i.test(selectedMessage);

        const isLastCall =
            selectedMessage === WP_DRIVER_MESSAGES[7] ||
            /^8\.\s*LAST CALL!/i.test(selectedMessage);

        if (isLastChance) {
            return (
                'LAST CHANCE FOR THIS ONE! It will be canceled in ' +
                minutes +
                ' minutes 🗣️'
            );
        }

        if (isLastCall) {
            return (
                'LAST CALL! Ακυρώνεται σε ' +
                minutes +
                ' λεπτά, υπάρχει διαθεσιμότητα; 🚨'
            );
        }

        return selectedMessage;

    }

    function wpSetTaskMessageFromDriverCostIncrease(percent) {

        const numericPercent =
            Number(percent);

        if (!Number.isFinite(numericPercent) || numericPercent <= 0) {
            return;
        }

        // For any percentage selected in the Driver Cost dropdown,
        // use the same task format that was previously hard-coded for
        // +10% and +20%.
        // 1.7.264: already sent to Final → "raised a bit more to save"
        let afterFinal = false;
        try { afterFinal = wpPageHasFinalNote() && !wpRuleExceptionFor('afterfinal', wpFindTransferCity() || ''); } catch (_) {}
        const desiredMessage = afterFinal ? WP_AFTER_FINAL_NOTE :
            'raised to +' +
            numericPercent +
            '% DC/ sent to BC, Group';

        const taskTypeSelect =
            wpFindRefundSelect();

        const targetInput =
            wpFindTaskMessageInput(
                taskTypeSelect
            );

        if (!targetInput) {
            return;
        }

        targetInput.value =
            desiredMessage;

        targetInput.dispatchEvent(
            new Event(
                'input',
                { bubbles: true }
            )
        );

        targetInput.dispatchEvent(
            new Event(
                'change',
                { bubbles: true }
            )
        );

        const quickSelect =
            document.querySelector(
                '.wp-task-quick-select'
            );

        if (quickSelect) {
            quickSelect.value =
                desiredMessage;
        }

    }

    function wpRefreshLastChanceDriverMessageOptions(select) {

        if (!select) {
            return;
        }

        const minutes =
            wpGetDriverMessageMinutes();

        const options =
            Array.from(select.options || []);

        options.forEach(function(option, index) {

            if (option.value === WP_DRIVER_MESSAGES[6]) {
                option.textContent =
                    '7. LAST CHANCE FOR THIS ONE! It will be canceled in ' +
                    minutes +
                    ' minutes 🗣️';
            }

            if (option.value === WP_DRIVER_MESSAGES[7]) {
                option.textContent =
                    '8. LAST CALL! Ακυρώνεται σε ' +
                    minutes +
                    ' λεπτά, υπάρχει διαθεσιμότητα; 🚨';
            }

        });

    }

    function wpSetupTaskQuickInsert() {

        wpSetTaskTypeDefault();

        const taskTypeSelect =
            wpFindRefundSelect();

        if (!taskTypeSelect) {
            return;
        }

        if (
            document.querySelector(
                '.wp-task-quick-insert'
            )
        ) {
            return;
        }

        const targetInput =
            wpFindTaskMessageInput(
                taskTypeSelect
            );

        if (!targetInput) {
            return;
        }

        const wrapper =
            document.createElement('span');

        wrapper.className =
            'wp-task-quick-insert';

        const select =
            document.createElement('select');

        select.className =
            'wp-task-quick-select';

        select.title =
            'Quick insert task text';

        const placeholder =
            document.createElement('option');

        placeholder.value =
            '';

        placeholder.textContent =
            'Task text...';

        select.appendChild(
            placeholder
        );

        wpBuildManagedTaskMessages().forEach(
            function(message, index) {

                const option =
                    document.createElement(
                        'option'
                    );

                option.value =
                    message;

                option.textContent =
                    (index + 1) +
                    '. ' +
                    message;

                select.appendChild(
                    option
                );

            }
        );

        wrapper.appendChild(
            select
        );

        /*
         * Default to message #1 ("em") whenever the CRM task text box
         * is empty. Existing text is never overwritten.
         */
        if (
            !String(
                targetInput.value || ''
            ).trim()
        ) {

            const managedTaskMessages =
                wpBuildManagedTaskMessages();

            if (managedTaskMessages.length) {
                select.value =
                    managedTaskMessages[0];

                targetInput.value =
                    managedTaskMessages[0];
            }

            targetInput.dispatchEvent(
                new Event(
                    'input',
                    {
                        bubbles: true
                    }
                )
            );

            targetInput.dispatchEvent(
                new Event(
                    'change',
                    {
                        bubbles: true
                    }
                )
            );

        }

        /*
         * Put the dropdown in the SAME task-creation row, in the empty
         * space to the right of the task message textarea.
         *
         * Do not use position:fixed or getBoundingClientRect():
         * the CRM redraws this area, which made the old dropdown jump.
         */
        const inputParent =
            targetInput.parentElement;

        if (!inputParent) {
            return;
        }

        inputParent.insertBefore(
            wrapper,
            targetInput.nextSibling
        );

        wpAddDropdownManagerButton(
            wrapper,
            'Task Text options',
            wpOpenTaskDropdownManager
        );

        select.addEventListener(
            'change',
            function() {

                if (!select.value) {
                    return;
                }

                const resolvedMessage =
                    wpFormatDriverMessageWithAcMinutes(
                        select.value
                    );

                targetInput.value =
                    resolvedMessage;

                targetInput.dispatchEvent(
                    new Event(
                        'input',
                        {
                            bubbles: true
                        }
                    )
                );

                targetInput.dispatchEvent(
                    new Event(
                        'change',
                        {
                            bubbles: true
                        }
                    )
                );

            }
        );

    }

    // ============================================================
    // SUGGESTED DRIVER AUTOMATION - PHASE 1
    // ============================================================

    const WP_SUGGESTED_RESULT_KEY =
        'wp_suggested_driver_result_v1';

        null;


    function wpFindHailingLink() {

        // The CRM's real Hailing control is an AJAX link. Use its stable
        // data-action selector rather than relying on the visible label.
        const direct = document.querySelector(
            'a.direct[data-action="hailing"]'
        );
        if (direct) return direct;

        // Keep the old label lookup only as a minimal compatibility fallback
        // for CRM variants that may not expose data-action.
        return Array.from(
            document.querySelectorAll('a')
        ).find(function(link) {

            const label =
                wpNormalizeDetailText(
                    link.textContent || ''
                ).toLowerCase();

            return (
                label.includes('hailing') &&
                label.includes('find driver')
            );

        }) || null;

    }

    var wpRedDotLink = null;
    var wpRedDotMissAt = 0;
    function wpRemoveTransferDetailsRedDot() {

        try {
            // Performance (1.7.182): this ran every 1.2 s over every link of
            // the page. The link is remembered; a miss is retried after 10 s.
            if (!(wpRedDotLink && wpRedDotLink.isConnected) && Date.now() - wpRedDotMissAt < 10000) return;
            const links = wpRedDotLink && wpRedDotLink.isConnected ? [wpRedDotLink] : Array.from(document.querySelectorAll('a'));

            const link = links.find(function(anchor) {
                const text = String(anchor.textContent || '')
                    .replace(/\s+/g, ' ')
                    .trim()
                    .replace(/[•·●]/g, '')
                    .replace(/\s+/g, ' ')
                    .trim()
                    .toLowerCase();

                return text === 'transfer details' ||
                    text.startsWith('transfer details ');
            });

            if (!link) {
                wpRedDotLink = null;
                wpRedDotMissAt = Date.now();
                return;
            }
            wpRedDotLink = link;

            link.classList.add('wp-transfer-details-clean-dot');

            /*
             * Some CRM builds render the red marker as a real child element
             * instead of ::before/::after. Remove only a tiny red marker
             * sitting immediately before the Transfer Details label.
             */
            const walker = document.createTreeWalker(
                link,
                NodeFilter.SHOW_ELEMENT
            );

            const candidates = [];
            let node = walker.nextNode();

            while (node) {
                const rect = node.getBoundingClientRect();
                const style = getComputedStyle(node);
                const bg = String(style.backgroundColor || '').toLowerCase();
                const fg = String(style.color || '').toLowerCase();
                const text = String(node.textContent || '')
                    .replace(/\s+/g, ' ')
                    .trim();

                const isTiny =
                    rect.width <= 12 &&
                    rect.height <= 12;

                const isRed =
                    bg.includes('255, 0, 0') ||
                    bg.includes('220, 0, 0') ||
                    bg.includes('221, 0, 0') ||
                    fg.includes('255, 0, 0') ||
                    fg.includes('220, 0, 0') ||
                    fg.includes('221, 0, 0');

                if (isTiny && isRed && text === '') {
                    candidates.push(node);
                }

                node = walker.nextNode();
            }

            candidates.forEach(function(marker) {
                marker.style.setProperty('display', 'none', 'important');
            });
        } catch (error) {
            // Never let the cosmetic cleanup affect the rest of the script.
        }
    }

    function wpAddHailingLinkAutoCancelStatus() {

        const hailingLink =
            wpFindHailingLink();

        if (!hailingLink) {
            return;
        }

        if (
            document.getElementById(
                'wp-hailing-link-autocancel-status'
            )
        ) {
            return;
        }

        const badge =
            document.createElement(
                'span'
            );

        badge.id =
            'wp-hailing-link-autocancel-status';

        const enabled =
            wpGetAutoCancelEnabled();

        const initialEnabled =
            enabled === true;

        badge.title =
            initialEnabled
                ? 'AC: ON'
                : 'AC: OFF';

        badge.innerHTML =
            '<span class="wp-hailing-link-autocancel-label">' +
            (
                initialEnabled
                    ? 'AC: ON'
                    : 'AC: OFF'
            ) +
            '</span>';

        badge.classList.toggle(
            'is-on',
            initialEnabled
        );

        badge.classList.toggle(
            'is-off',
            !initialEnabled
        );

        hailingLink.parentElement.insertBefore(
            badge,
            hailingLink
        );

    }


    function wpExtractSuggestedDriversFromPage(
        maxDrivers,
        requiredPax,
        requiredLuggage
    ) {

        const limit =
            Math.min(
                5,
                Math.max(
                    1,
                    Number(maxDrivers) || 5
                )
            );

        function normalizePhone(value) {

            const raw =
                String(value || '')
                    .replace(/[^\d+]/g, '')
                    .replace(/^00/, '+');

            return raw.length >= 10
                ? raw
                : '';

        }

        function normalizeVehicleType(value) {

            return String(value || '')
                .replace(/\s+/g, ' ')
                .trim()
                .toLowerCase();

        }

        function parseCapabilityLine(
            line
        ) {

            const result = [];

            const rx =
                /\b(Sedan|Mini\s*Van|Minivan|Mini\s*Bus|Minibus|SUV|Van|Bus)\b\s+Pass\s*:\s*(\d+)\s*-\s*(\d+)\s+Lgg\s*:\s*(\d+)\s*-\s*(\d+)/ig;

            let match;

            while (
                (match = rx.exec(line))
            ) {

                result.push({
                    type:
                        match[1]
                            .replace(/\s+/g, ' ')
                            .trim(),
                    paxMin:
                        Number(match[2]),
                    paxMax:
                        Number(match[3]),
                    luggageMin:
                        Number(match[4]),
                    luggageMax:
                        Number(match[5])
                });

            }

            return result;

        }

        function getCarTypes(
            card
        ) {

            const capabilities =
                [];

            const lines =
                (
                    card.innerText ||
                    card.textContent ||
                    ''
                )
                    .split(/\r?\n/)
                    .map(function(line) {
                        return wpNormalizeDetailText(line);
                    })
                    .filter(Boolean);

            lines.forEach(function(line) {

                parseCapabilityLine(
                    line
                ).forEach(function(capability) {

                    capabilities.push(
                        capability
                    );

                });

            });

            /*
             * Individual driver cards can expose a collapsed Vehicle Details
             * toggle. When it is present, read any visible vehicle text
             * around the toggle as well.
             */
            const toggles =
                Array.from(
                    card.querySelectorAll(
                        'a.vehicle-details-toggle'
                    )
                );

            toggles.forEach(function(toggle) {

                let sibling =
                    toggle.nextElementSibling;

                for (
                    let i = 0;
                    i < 4 &&
                    sibling;
                    i++
                ) {

                    const value =
                        wpNormalizeDetailText(
                            sibling.innerText ||
                            sibling.textContent ||
                            ''
                        );

                    if (value) {

                        const types =
                            value.match(
                                /\b(?:Sedan|Mini\s*Van|Minivan|Mini\s*Bus|Minibus|SUV|Van|Bus)\b/ig
                            ) || [];

                        types.forEach(function(type) {

                            const normalizedType =
                                type
                                    .replace(
                                        /\s+/g,
                                        ' '
                                    )
                                    .trim();

                            if (
                                !capabilities.some(function(existing) {

                                    return (
                                        normalizeVehicleType(
                                            existing.type
                                        ) ===
                                        normalizeVehicleType(
                                            normalizedType
                                        )
                                    );

                                })
                            ) {

                                capabilities.push({
                                    type:
                                        normalizedType,
                                    paxMin:
                                        null,
                                    paxMax:
                                        null,
                                    luggageMin:
                                        null,
                                    luggageMax:
                                        null
                                });

                            }

                        });

                    }

                    sibling =
                        sibling.nextElementSibling;

                }

            });

            return capabilities;

        }

        function getName(
            card,
            phone
        ) {

            const links =
                Array.from(
                    card.querySelectorAll(
                        'a'
                    )
                );

            for (
                const link of links
            ) {

                const href =
                    link.href ||
                    link.getAttribute(
                        'href'
                    ) ||
                    '';

                const value =
                    wpNormalizeDetailText(
                        link.textContent
                    );

                if (!value) {
                    continue;
                }

                if (
                    /(?:wa\.me|whatsapp\.com\/send)/i.test(
                        href
                    )
                ) {
                    continue;
                }

                if (
                    value.replace(/\D/g, '') ===
                    phone.replace(/\D/g, '')
                ) {
                    continue;
                }

                if (
                    /broadcast suggested drivers/i.test(
                        value
                    ) ||
                    /for broadcast request/i.test(
                        value
                    )
                ) {
                    continue;
                }

                return value;

            }

            const lines =
                (
                    card.innerText ||
                    card.textContent ||
                    ''
                )
                    .split(/\r?\n/)
                    .map(function(line) {
                        return wpNormalizeDetailText(line);
                    })
                    .filter(Boolean);

            for (
                const line of lines
            ) {

                if (
                    line.replace(/\D/g, '') ===
                    phone.replace(/\D/g, '')
                ) {
                    continue;
                }

                if (
                    /^Mark\b/i.test(line) ||
                    /broadcast request/i.test(line) ||
                    /(?:Pass|Lgg)\s*:/i.test(line) ||
                    /^\+?\d[\d\s().-]+$/.test(line)
                ) {
                    continue;
                }

                if (
                    line.length >= 2 &&
                    line.length <= 160
                ) {
                    return line;
                }

            }

            return 'Suggested driver';

        }

        function driverMatchesOrder(
            capabilities
        ) {

            const pax =
                Number(requiredPax) || 0;

            const luggage =
                Number(requiredLuggage) || 0;

            /*
             * If the order does not expose capacity requirements, don't
             * filter out drivers.
             */
            if (
                pax <= 0 &&
                luggage <= 0
            ) {
                return true;
            }

            /*
             * A specific capacity match is enough. Vehicle-type-only entries
             * without capacity values are retained as a fallback.
             */
            let hasUnknownCapacity =
                false;

            for (
                const capability of capabilities
            ) {

                if (
                    capability.paxMax == null ||
                    capability.luggageMax == null
                ) {

                    hasUnknownCapacity =
                        true;

                    continue;

                }

                if (
                    capability.paxMax >= pax &&
                    capability.luggageMax >= luggage
                ) {
                    return true;
                }

            }

            return hasUnknownCapacity;

        }

        /*
         * Only inspect the actual requested-driver cards. We deliberately
         * stop after obtaining the first 5 suitable drivers.
         */
        const cards =
            Array.from(
                document.querySelectorAll(
                    'table.container.requested'
                )
            );

        const drivers =
            [];

        for (
            const card of cards
        ) {

            if (
                drivers.length >= limit
            ) {
                break;
            }

            const waLinks =
                Array.from(
                    card.querySelectorAll(
                        'a'
                    )
                ).filter(function(link) {

                    const href =
                        link.href ||
                        link.getAttribute(
                            'href'
                        ) ||
                        '';

                    return /(?:wa\.me|whatsapp\.com\/send)/i.test(
                        href
                    );

                });

            for (
                const link of waLinks
            ) {

                if (
                    drivers.length >= limit
                ) {
                    break;
                }

                const rawPhone =
                    link.textContent ||
                    (
                        (
                            link.href ||
                            ''
                        ).match(
                            /\+?\d[\d\s().-]{7,}\d/
                        ) || []
                    )[0] ||
                    '';

                const phone =
                    normalizePhone(
                        rawPhone
                    );

                if (!phone) {
                    continue;
                }

                if (
                    drivers.some(function(existing) {
                        return (
                            existing.phone ===
                            phone
                        );
                    })
                ) {
                    continue;
                }

                const capabilities =
                    getCarTypes(
                        card
                    );

                if (
                    !driverMatchesOrder(
                        capabilities
                    )
                ) {
                    continue;
                }

                drivers.push({
                    name:
                        getName(
                            card,
                            phone
                        ),
                    phone:
                        phone,
                    carType:
                        capabilities
                            .map(function(capability) {
                                return capability.type;
                            })
                            .filter(function(type, index, array) {
                                return array.indexOf(type) === index;
                            })
                            .join(' + ')
                });

            }

        }

        return drivers;

    }



    function wpPublishSuggestedDriverResult(
        drivers
    ) {

        let message = '';

        try {

            message =
                sessionStorage.getItem(
                    'wp_hailing_driver_message_v1'
                ) || '';

        } catch (error) {}

        const driverList =
            Array.isArray(
                drivers
            )
                ? drivers.slice(
                    0,
                    5
                )
                : [];

        const result = {
            drivers:
                driverList,
            numbers:
                driverList.map(function(driver) {
                    return driver.phone;
                }),
            message:
                message,
            timestamp:
                Date.now()
        };

        try {

            localStorage.setItem(
                WP_SUGGESTED_RESULT_KEY,
                JSON.stringify(result)
            );

        } catch (error) {

            console.warn(
                'Could not publish suggested-driver result:',
                error
            );

        }

    }

    function wpSetupHailingDriverScanner() {

        if (
            window.__wpHailingDriverScanStarted
        ) {
            return false;
        }

        window.__wpHailingDriverScanStarted =
            true;

        const bodyText =
            document.body?.innerText ||
            '';

        const looksLikeHailing =
            bodyText.toLowerCase().includes(
                'broadcast suggested drivers'
            ) ||
            document.querySelector(
                'a.display-broadcast-drivers'
            ) ||
            document.querySelector(
                'table.container.requested'
            );

        if (!looksLikeHailing) {
            return false;
        }

        const broadcast =
            document.querySelector(
                'a.display-broadcast-drivers'
            );

        if (broadcast) {

            try {
                broadcast.click();
            } catch (error) {}

        }

        /*
         * The helper waits only long enough for the Broadcast cards to be
         * populated. It takes the first 5 suitable drivers and immediately
         * publishes them.
         */
        let requirements = {
            pax: 0,
            luggage: 0
        };

        try {

            const rawRequirements =
                sessionStorage.getItem(
                    'wp_hailing_requirements_v1'
                );

            if (rawRequirements) {

                requirements =
                    JSON.parse(
                        rawRequirements
                    );

            }

        } catch (error) {}

        let attempts =
            0;

        const retry =
            setInterval(
                function() {

                    attempts++;

                    const drivers =
                        wpExtractSuggestedDriversFromPage(
                            5,
                            requirements.pax,
                            requirements.luggage
                        );

                    if (
                        drivers.length >= 5 ||
                        attempts >= 8
                    ) {

                        clearInterval(
                            retry
                        );

                        wpPublishSuggestedDriverResult(
                            drivers.slice(
                                0,
                                5
                            )
                        );

                    }

                },
                250
            );

        return true;

    }


    function wpNormalizeCityKey(value) {

        return String(value || '')
            .trim()
            .replace(/\s+/g, ' ')
            .toLowerCase();

    }

    // ============================================================
    // TRANSFER -> CITY CONTEXT
    // ============================================================
    // When a transfer is opened from the transfer list / Transfer Overview,
    // we already know the exact city from the row. Keep that authoritative
    // city in shared localStorage so the newly opened transfer tab does not
    // have to guess from unrelated text elsewhere on the detail page.
    const WP_TRANSFER_CITY_CONTEXT_KEY =
        'wp_transfer_city_context_v1';

    function wpTransferCityContextKey(url) {
        try {
            const parsed = new URL(url, window.location.href);
            return parsed.origin + parsed.pathname;
        } catch (error) {
            return String(url || '');
        }
    }

    // A city name never has digits, "%" or one of our tag words in it.
    function wpLooksLikeCityName(value) {
        const text = String(value || '').trim();
        return Boolean(text) && text.length <= 40 &&
            !/[\d%€]/.test(text) &&
            !/^(pickup|drop-?off|pu \+ do|dc = tc|no tag|final bc|bc|bc & g|hero|high vol|sedan|minivan|van)\b/i.test(text);
    }

    function wpRememberTransferCity(url, city) {
        const cleanCity = wpNormalizeDetailText(city || '');
        if (!url || !cleanCity || !wpLooksLikeCityName(cleanCity)) return;

        try {
            const key = wpTransferCityContextKey(url);
            const raw = localStorage.getItem(WP_TRANSFER_CITY_CONTEXT_KEY);
            const data = raw ? JSON.parse(raw) : {};

            data[key] = {
                city: cleanCity,
                savedAt: Date.now()
            };

            // Keep the shared map small and discard entries older than 12h.
            const cutoff = Date.now() - (12 * 60 * 60 * 1000);
            Object.keys(data).forEach(function(entryKey) {
                if (!data[entryKey] || Number(data[entryKey].savedAt || 0) < cutoff) {
                    delete data[entryKey];
                }
            });

            localStorage.setItem(
                WP_TRANSFER_CITY_CONTEXT_KEY,
                JSON.stringify(data)
            );
        } catch (error) {}
    }

    function wpGetRememberedTransferCity(url) {
        if (!url) return '';

        try {
            const key = wpTransferCityContextKey(url);
            const raw = localStorage.getItem(WP_TRANSFER_CITY_CONTEXT_KEY);
            if (!raw) return '';

            const data = JSON.parse(raw);
            const entry = data && data[key];
            if (!entry || !entry.city || !wpLooksLikeCityName(entry.city)) return '';

            const savedAt = Number(entry.savedAt || 0);
            if (savedAt && Date.now() - savedAt > (12 * 60 * 60 * 1000)) {
                delete data[key];
                localStorage.setItem(
                    WP_TRANSFER_CITY_CONTEXT_KEY,
                    JSON.stringify(data)
                );
                return '';
            }

            return wpNormalizeDetailText(entry.city);
        } catch (error) {
            return '';
        }
    }

    function wpFindTransferCity() {

        const rememberedCity =
            wpGetRememberedTransferCity(window.location.href);

        if (rememberedCity) {
            return rememberedCity;
        }

        /*
         * IMPORTANT:
         * Never use the flight / "Pre" section to determine the city.
         * On a transfer page, the city we want is the city represented by
         * the actual From/Pickup and, when necessary, To destination
         * sections.
         */

        const cities =
            Object.keys(
                WHATSAPP_LINKS
            ).sort(function(a, b) {

                return b.length - a.length;

            });

        const preferred =
            [
                'Herakleion',
                'Heraklion',
                'Chania',
                'Paphos',
                'Larnaca',
                'Naples'
            ];

        function findCity(
            value
        ) {

            const normalized =
                wpNormalizeCityKey(
                    value
                );

            if (!normalized) {
                return '';
            }

            /*
             * Piraeus is handled as Athens for the transfer workflow.
             * This means the transfer displays "Athens", uses the Athens
             * WhatsApp group, and uses the Athens timezone.
             */
            if (
                normalized ===
                'piraeus' ||
                normalized.includes(
                    'piraeus'
                )
            ) {
                return 'Athens';
            }

            /*
             * Exact match first.
             */
            for (
                const city of preferred
            ) {

                if (
                    normalized ===
                    wpNormalizeCityKey(city)
                ) {
                    return city;
                }

            }

            for (
                const city of cities
            ) {

                if (
                    normalized ===
                    wpNormalizeCityKey(city)
                ) {
                    return city;

                }

            }

            /*
             * Then allow a city name inside an address such as:
             * "Athens International Airport (ATH)"
             */
            for (
                const city of preferred
            ) {

                if (
                    normalized.includes(
                        wpNormalizeCityKey(city)
                    )
                ) {
                    return city;
                }

            }

            for (
                const city of cities
            ) {

                if (
                    normalized.includes(
                        wpNormalizeCityKey(city)
                    )
                ) {
                    return city;
                }

            }

            /*
             * Manual transfer-page aliases. These are checked last so
             * they cannot override the existing WhatsApp-city resolver.
             */
            for (
                const city of preferred
            ) {

                if (
                    normalized.includes(
                        wpNormalizeCityKey(city)
                    )
                ) {
                    return city;
                }

            }

            return '';

        }

        function textOf(
            element
        ) {

            if (!element) {
                return '';
            }

            return wpNormalizeDetailText(
                element.value ||
                element.textContent ||
                ''
            );

        }

        function findCityInFieldContainer(
            container
        ) {

            if (!container) {
                return '';
            }

            /*
             * Only inspect this small container. Do not walk up through
             * the page because that can accidentally include the Pre/flight
             * section and return its origin city.
             */
            const fields =
                Array.from(
                    container.querySelectorAll(
                        'input, textarea, select'
                    )
                );

            for (
                const field of fields
            ) {

                const city =
                    findCity(
                        textOf(field)
                    );

                if (city) {
                    return city;
                }

            }

            return findCity(
                textOf(container)
            );

        }

        function findSectionCity(
            sectionLabel
        ) {

            const labels =
                Array.from(
                    document.querySelectorAll(
                        'label, th, td, span, div, p, b, strong, button'
                    )
                ).filter(function(element) {

                    return (
                        textOf(element)
                            .toLowerCase() ===
                        sectionLabel
                    );

                });

            for (
                const label of labels
            ) {

                /*
                 * First inspect immediate siblings. On the CRM transfer
                 * page the actual From/To panel is adjacent to its label.
                 */
                const siblings =
                    Array.from(
                        label.parentElement?.children ||
                        []
                    );

                for (
                    const sibling of siblings
                ) {

                    if (
                        sibling ===
                        label
                    ) {
                        continue;
                    }

                    const city =
                        findCityInFieldContainer(
                            sibling
                        );

                    if (city) {
                        return city;
                    }

                }

                /*
                 * Then inspect the label's immediate parent, but NOT
                 * several ancestors. This prevents "Pre" / flight data from
                 * contaminating the result.
                 */
                const parent =
                    label.parentElement;

                const parentCity =
                    findCityInFieldContainer(
                        parent
                    );

                if (parentCity) {
                    return parentCity;
                }

                /*
                 * Finally, inspect the next sibling of the label's parent.
                 */
                const next =
                    parent?.nextElementSibling;

                const nextCity =
                    findCityInFieldContainer(
                        next
                    );

                if (nextCity) {
                    return nextCity;
                }

            }

            return '';

        }

        /*
         * 1. Actual pickup / From city.
         */
        const fromCity =
            findSectionCity(
                'from'
            );

        if (fromCity) {
            return fromCity;
        }

        /*
         * 2. Some transfers label the pickup section as Pickup.
         */
        const pickupCity =
            findSectionCity(
                'pickup'
            );

        if (pickupCity) {
            return pickupCity;
        }

        /*
         * 3. If the pickup is not a named city, inspect the actual To
         * section. This is still safer than looking at the flight header.
         */
        const toCity =
            findSectionCity(
                'to'
            );

        if (toCity) {
            return toCity;
        }

        /*
         * Deliberately no whole-page fallback.
         *
         * A whole-page scan is exactly what caused cases such as:
         * Flight: Budapest -> ...
         * From: Athens International Airport
         *
         * to be detected as Budapest.
         *
         * When the CRM does not expose a From/To value we would rather show
         * no city than silently use the wrong city.
         */
        return '';

    }

    // ---- WhatsApp Web auto-send (1.7.123) ----
    // The message goes to the background, which queues it for the WhatsApp
    // Web tab (wp-whatsapp.js). Returns true when queued; false means the
    // caller keeps the old copy + open-the-group behaviour.
    // var: the Terminal header can be built before this line has run.
    function wpWhatsAppAutoSendOn() {
        try { return localStorage.getItem('wp_wa_autosend_v1') !== '0'; } catch (_) { return true; }
    }
    var wpWhatsAppFallbacks = {};
    var wpWhatsAppListening = false;
    function wpWhatsAppListen() {
        if (wpWhatsAppListening) return;
        wpWhatsAppListening = true;
        chrome.runtime.onMessage.addListener(function(message) {
            if (!message || message.type !== 'WP_WA_RESULT') return;
            const name = message.label || message.city || 'WhatsApp';
            const waiter = wpWhatsAppWaiters[message.jobId];
            if (message.progress) {
                const pending = wpWhatsAppFallbacks[message.jobId];
                if (pending) pending.heardAt = Date.now();
                if (waiter) waiter.heardAt = Date.now();
                wpDashLog(name + ': ' + message.info);
                return;
            }
            // Heroes: the sender waits for this result (no copy fallback).
            if (waiter) {
                delete wpWhatsAppWaiters[message.jobId];
                waiter.resolve(message);
                return;
            }
            wpWhatsAppFail(message.jobId, name, message.ok, message.info);
        });
    }
    // Final result of one job (sent / not sent). Not sent: offer the old
    // copy + open-the-group as a clickable Terminal line.
    function wpWhatsAppFail(jobId, name, ok, info) {
        const fallback = wpWhatsAppFallbacks[jobId];
        delete wpWhatsAppFallbacks[jobId];
        if (fallback && fallback.watchdog) clearTimeout(fallback.watchdog);
        if (ok) {
            wpDashLog('✓ ' + name + ': WhatsApp message ' + info);
            return;
        }
        wpDashLog(name + ': WhatsApp not sent — ' + info, 'error');
        if (fallback) {
            let done = false;
            wpDashLog('📋 ' + name + ': click here to copy the message and open the ' + fallback.city + ' group', 'warn', function(line) {
                if (done) return;
                if (!wpCopyTextFromUserGesture(fallback.text)) { wpDashLog(name + ': copy failed', 'error'); return; }
                done = true;
                line.style.textDecoration = 'none';
                line.style.cursor = 'default';
                wpOpenCityWhatsApp(fallback.city);
                wpDashLog('✓ ' + name + ': message copied — paste with Ctrl+V');
            });
        }
    }
    function wpWhatsAppInviteCode(url) {
        return (String(url || '').match(/chat\.whatsapp\.com\/(?:invite\/)?([A-Za-z0-9]+)/) || [])[1] || '';
    }

    // Crete / Cyprus have one group per area: pick it from the route
    // (airport codes, place names). null = not clear → ask in the Terminal.
    const WP_WA_ISLAND_AREAS = {
        crete: [
            { name: 'Chania', link: 'Chania', code: /\bCHQ\b/, words: /chania|daskalogiannis|souda|platanias|kissamos|agia marina|kolymvari|georgioupoli|falasarna|akrotiri|kalyves|almyrida|maleme/i },
            { name: 'Herakleion', link: 'Herakleion', code: /\bHER\b/, words: /heraklion|herakleion|iraklion|kazantzakis|hersonissos|chersonissos|malia|agios nikolaos|elounda|stalis|analipsi|gouves|sissi|ierapetra|lasithi|amoudara|agia pelagia/i }
        ],
        cyprus: [
            { name: 'Paphos', link: 'Paphos', code: /\bPFO\b/, words: /paphos|pafos|coral bay|peyia|\bpolis\b|kissonerga|chlorakas|geroskipou/i },
            { name: 'Larnaca', link: 'Larnaca', code: /\bLCA\b/, words: /larnaca|larnaka|ayia napa|agia napa|protaras|paralimni|pernera|oroklini/i }
        ]
    };
    function wpWhatsAppIslandPick(areas, hint) {
        const hits = areas.filter(function(area) { return area.words.test(String(hint || '')) || area.code.test(String(hint || '')); });
        return hits.length === 1 ? hits[0] : null;
    }

    // Where a city's message goes: [{ name, code }]. Cities with two groups
    // (Welcomers + Dispatchers) get both; Crete / Cyprus one area (or ask).
    function wpWhatsAppTargets(city, hint) {
        const key = wpNormalizeCityKey(city);
        const multi = typeof WP_MULTI_WHATSAPP_GROUPS !== 'undefined' && WP_MULTI_WHATSAPP_GROUPS[key];
        if (multi) {
            return {
                targets: Object.keys(multi).map(function(group) {
                    return { name: city + ' ' + group, code: wpWhatsAppInviteCode(multi[group]), expect: [city] };
                })
            };
        }
        const areas = WP_WA_ISLAND_AREAS[key];
        if (areas) {
            const spellings = { Chania: ['Chania', 'Hania', 'Xania'], Herakleion: ['Herakleion', 'Heraklion', 'Iraklion'], Paphos: ['Paphos', 'Pafos'], Larnaca: ['Larnaca', 'Larnaka'] };
            const options = areas.map(function(area) {
                return { name: area.name, code: wpWhatsAppInviteCode(WHATSAPP_LINKS[area.link]), expect: spellings[area.name] || [area.name] };
            });
            const pick = wpWhatsAppIslandPick(areas, hint);
            return pick ? { targets: options.filter(function(o) { return o.name === pick.name; }), picked: true } : { ask: options };
        }
        let code = '';
        Object.keys(WHATSAPP_LINKS).some(function(linkKey) {
            if (wpNormalizeCityKey(linkKey) !== key) return false;
            code = wpWhatsAppInviteCode(WHATSAPP_LINKS[linkKey]);
            return true;
        });
        return { targets: [{ name: city, code: code, expect: [city] }] };
    }

    // options: { hint: text to pick Crete/Cyprus areas from, image: data URL
    // sent after the text }. True when queued (or waiting for your pick).
    async function wpWhatsAppAutoSend(city, text, label, options) {
        if (!wpWhatsAppAutoSendOn() || !city || !text) return false;
        if (!(typeof chrome !== 'undefined' && chrome.runtime && chrome.runtime.sendMessage)) return false;
        options = options || {};
        const name = label || city;
        const plan = wpWhatsAppTargets(city, options.hint || text);
        if (plan.ask) {
            let chosen = false;
            wpDashLog(name + ': which ' + city + ' WhatsApp group? The route does not say — click one below', 'warn');
            plan.ask.forEach(function(option) {
                wpDashLog('▸ send to ' + option.name, 'warn', function(line) {
                    if (chosen) return;
                    chosen = true;
                    line.style.textDecoration = 'none';
                    wpWhatsAppQueue(option, text, name, options.image);
                });
            });
            return true;
        }
        if (plan.picked) wpDashLog(name + ': ' + city + ' → ' + plan.targets[0].name + ' group (from the route)');
        let queued = false;
        for (const target of plan.targets) {
            if (await wpWhatsAppQueue(target, text, plan.targets.length > 1 ? name + ' → ' + target.name : name, options.image)) queued = true;
        }
        return queued;
    }

    async function wpWhatsAppQueue(target, text, name, image) {
        wpWhatsAppListen();
        const city = target.name;
        text = wpWithAtAll(city, text);
        const code = target.code || '';
        try {
            const response = await chrome.runtime.sendMessage({ type: 'WP_WA_SEND', city: city, text: text, label: name, code: code, image: image || '', expect: target.expect || [city] });
            if (!response || !response.ok) throw new Error(response && response.error || 'no answer');
            const pending = { city: city, text: text, heardAt: 0 };
            wpWhatsAppFallbacks[response.jobId] = pending;
            wpDashLog(name + ': sending to the ' + city + ' WhatsApp group' + (response.opened ? ' (opening WhatsApp Web)' : '') + '…');
            // No word from the WhatsApp tab in 60s: say so instead of silence.
            // (While you pick a group in the chooser it keeps waiting.)
            const watch = function() {
                if (wpWhatsAppFallbacks[response.jobId] !== pending) return;
                if (pending.heardAt && Date.now() - pending.heardAt < 180000) {
                    pending.watchdog = setTimeout(watch, 15000);
                    return;
                }
                wpWhatsAppFail(response.jobId, name, false, pending.heardAt
                    ? 'WhatsApp Web stopped responding'
                    : 'no answer from WhatsApp Web in 60s — open web.whatsapp.com in this Chrome, refresh it and try again');
            };
            pending.watchdog = setTimeout(watch, 60000);
            return true;
        } catch (error) {
            const reason = String(error && error.message || error);
            wpDashLog(name + ': WhatsApp auto-send unavailable (' + reason + ')' +
                (/context invalidated|receiving end/i.test(reason) ? ' — the extension was reloaded: refresh this CRM tab (F5)' : '') +
                ' — copying instead', 'error');
            return false;
        }
    }

    // ---- Send to heroes (1.7.132) ----
    // One hero at a time through WhatsApp Web. A hero who is not a saved
    // contact is saved first (1.7.281: no pause — when saving does not
    // work the message still goes to that number and the Terminal says so).
    var wpWhatsAppWaiters = {};
    var wpHeroRunActive = false;

    async function wpWhatsAppSendAndWait(phone, name, text, label, contactName, contact) {
        wpWhatsAppListen();
        let response;
        contact = contact || {};
        try {
            response = await chrome.runtime.sendMessage({ type: 'WP_WA_SEND', city: name, phone: phone, text: text, label: label, contactName: contactName || '', contactFirst: contact.first || '', contactLast: contact.last || '', contactOnly: Boolean(contact.only) });
        } catch (error) {
            return { ok: false, info: 'auto-send unavailable (' + (error && error.message || error) + ') — refresh this CRM tab (F5)' };
        }
        if (!response || !response.ok) return { ok: false, info: response && response.error || 'no answer from the extension' };
        wpDashLog(label + ': opening the chat…');
        return new Promise(function(resolve) {
            const waiter = { resolve: resolve, heardAt: Date.now() };
            wpWhatsAppWaiters[response.jobId] = waiter;
            const watch = function() {
                if (wpWhatsAppWaiters[response.jobId] !== waiter) return;
                if (Date.now() - waiter.heardAt < 90000) { setTimeout(watch, 5000); return; }
                delete wpWhatsAppWaiters[response.jobId];
                resolve({ ok: false, info: 'no answer from WhatsApp Web — is it open and logged in?' });
            };
            setTimeout(watch, 5000);
        });
    }

    function wpWaitForTerminalClick(text) {
        return new Promise(function(resolve) {
            let done = false;
            wpDashLog(text, 'warn', function(line) {
                if (done) return;
                done = true;
                line.style.textDecoration = 'none';
                line.style.cursor = 'default';
                resolve();
            });
        });
    }


    // people: [{ name, phone }] — heroes or CRM-suggested drivers. Saved
    // as "<name> - <role> <city>" when not a contact yet.
    // 1.7.281: a hero's WhatsApp contact: First name = the hero's name,
    // Last name = "<city> <car type>" — new ones are saved that way, saved
    // ones with another name are renamed to it.
    function wpHeroContactName(hero, city) {
        const car = String(hero && (hero.car || hero.carType) || '').replace(/\s+/g, ' ').trim();
        const cityName = String(city || '').replace(/\s+/g, ' ').trim().replace(/\b[a-z]/g, function(letter) { return letter.toUpperCase(); });
        return { first: String(hero && hero.name || '').replace(/\s+/g, ' ').trim(), last: (cityName + (car ? ' ' + car : '')).trim() };
    }
    // options.contactOnly: no message, only saved / renamed (1.7.281).
    async function wpSendToPeople(heroes, city, text, label, role, options) {
        options = options || {};
        if (wpHeroRunActive) {
            wpDashLog(label + ': a send run is still going — wait for it to finish', 'warn');
            return;
        }
        if (!text && !options.contactOnly) {
            wpDashLog(label + ': no transfer details to send', 'error');
            return;
        }
        wpHeroRunActive = true;
        let sent = 0;
        try {
            wpDashLog(label + ': ' + (options.contactOnly ? 'saving / renaming ' : 'sending to ') + heroes.length + ' ' + city + ' ' + (role === 'Hero' ? 'hero' + (heroes.length === 1 ? '' : 'es') : 'driver' + (heroes.length === 1 ? '' : 's')) + ', one by one');
            for (let i = 0; i < heroes.length; i++) {
                const hero = heroes[i];
                const heroLabel = label + ' → ' + hero.name + ' (' + (i + 1) + '/' + heroes.length + ')';
                // Heroes: "<name>" + "<city> <car type>"; others as before ("<name> - <role> <city>").
                const contact = role === 'Hero' ? wpHeroContactName(hero, city) : null;
                if (contact && options.contactOnly) contact.only = true;
                // 1.7.296: a hero's own text (their transfers), worded differently when they already got one
                let heroText = hero.text || text;
                const again = role === 'Hero' && !options.contactOnly && heroText && wpHeroToldRecently(hero.phone);
                if (again) heroText = wpHeroAgainText(heroText);
                const result = await wpWhatsAppSendAndWait(hero.phone, hero.name, heroText, heroLabel, contact ? (contact.first + ' ' + contact.last).trim() : hero.name + ' - ' + (role || 'Hero') + ' ' + city, contact);
                if (result.ok) {
                    sent++;
                    if (role === 'Hero' && !options.contactOnly) wpHeroToldMark(hero.phone);
                    wpDashLog('✓ ' + heroLabel + ': ' + result.info + (again ? ' (worded as a second message)' : ''), /not saved as a contact|still named/.test(String(result.info || '')) ? 'warn' : undefined);
                } else {
                    // 1.7.281: no pause any more — the next one goes
                    wpDashLog(heroLabel + ': not ' + (options.contactOnly ? 'saved' : 'sent') + ' — ' + result.info, 'error');
                }
            }
        } finally {
            wpHeroRunActive = false;
        }
        wpDashLog((sent ? '✓ ' : '') + label + ': done — ' + (options.contactOnly ? 'saved / named ' : 'sent to ') + sent + ' of ' + heroes.length, sent ? '' : 'warn');
    }

    function wpOpenCityWhatsApp(
        city
    ) {

        const normalized =
            wpNormalizeCityKey(
                city
            );

        /*
         * Resolve the configured WhatsApp link by the SAME normalized city
         * key used everywhere else in the script. The old implementation
         * used WHATSAPP_LINKS[city] directly, which fails when the CRM
         * displays a different case/spacing variant such as "ATHENS" or
         * " Athens ".
         */
        let resolvedUrl =
            '';

        Object.keys(
            WHATSAPP_LINKS
        ).some(function(key) {

            if (
                wpNormalizeCityKey(key) ===
                normalized
            ) {

                resolvedUrl =
                    WHATSAPP_LINKS[key];

                return true;

            }

            return false;

        });

        /*
         * Keep the existing city-specific aliases.
         */
        if (!resolvedUrl) {

            const directMap = {
                'chania':
                    WHATSAPP_LINKS.Chania,
                'herakleion':
                    WHATSAPP_LINKS.Herakleion,
                'heraklion':
                    WHATSAPP_LINKS.Herakleion,
                'paphos':
                    WHATSAPP_LINKS.Paphos,
                'larnaca':
                    WHATSAPP_LINKS.Larnaca
            };

            resolvedUrl =
                directMap[normalized] || '';

        }

        if (
            !resolvedUrl
        ) {
            return;
        }

        // With WhatsApp auto-send on, groups open in WhatsApp Web (the
        // existing web.whatsapp.com tab), never in the desktop app.
        const inviteCode = (String(resolvedUrl).match(/chat\.whatsapp\.com\/(?:invite\/)?([A-Za-z0-9]+)/) || [])[1];
        if (inviteCode && wpWhatsAppAutoSendOn()) {
            try {
                // The city goes along (1.7.234), so the WhatsApp tab can find
                // the group by name inside the page instead of reloading on its link.
                chrome.runtime.sendMessage({ type: 'WP_WA_OPEN', url: 'https://web.whatsapp.com/accept?code=' + inviteCode, city: String(normalized || '') });
                return;
            } catch (_) {}
        }

        /*
         * Preserve the existing City -> WhatsApp behavior. The helper opens
         * WhatsApp in a background tab and closes that helper tab, so the
         * CRM / Transfer Overview tab is never redirected or replaced.
         */
        wpOpenCityWhatsAppUrl(
            resolvedUrl
        );

    }

    // ============================================================
    // TRANSFER PAGE CITY CUSTOM NOTES
    // ============================================================

    const WP_TRANSFER_CITY_NOTES_KEY =
        'wp_transfer_city_custom_notes_v1';

    function wpGetTransferCityNotes() {

        try {

            const raw =
                localStorage.getItem(
                    WP_TRANSFER_CITY_NOTES_KEY
                );

            if (!raw) {
                return {};
            }

            const parsed =
                JSON.parse(raw);

            if (
                parsed &&
                typeof parsed === 'object' &&
                !Array.isArray(parsed)
            ) {
                return parsed;
            }

        } catch (error) {}

        return {};

    }

    function wpSaveTransferCityNotes(
        notes
    ) {

        try {

            localStorage.setItem(
                WP_TRANSFER_CITY_NOTES_KEY,
                JSON.stringify(notes)
            );

        } catch (error) {}

    }

    function wpPositionTransferCityNotesPanel() {

        const panel =
            document.getElementById(
                'wp-transfer-city-notes-panel'
            );

        if (!panel) {
            return;
        }

        /* Notes are deliberately snapped directly underneath Hero Drivers.
         * No other overlay participates in this vertical stack, so the notes
         * panel can never drift between Hero, Suggested Drivers, or A/C UI. */
        const heroPanel =
            document.getElementById(
                'wp-hero-drivers-panel'
            );

        let top = 96;

        if (heroPanel) {
            try {
                const rect = heroPanel.getBoundingClientRect();
                if (rect && Number.isFinite(rect.bottom)) {
                    top = Math.max(14, Math.ceil(rect.bottom) + 8);
                }
            } catch (error) {}
        }

        panel.style.top = top + 'px';

        // Keep the A/C + Save control physically snapped underneath Notes.
        // The Notes panel can move when Hero Drivers expands/collapses, so
        // refresh the button position every time Notes is repositioned.
        if (typeof wpPositionAcSaveFloatingButton === 'function') {
            requestAnimationFrame(function() {
                wpPositionAcSaveFloatingButton();
            });
        }

    }

    function wpSetupTransferCityNotes() {

        if (!wpIsTransferDetailPage()) {
            return;
        }

        const city =
            wpFindTransferCity();

        if (!city) {
            return;
        }

        const key =
            wpNormalizeCityKey(city);

        if (!key) {
            return;
        }

        let panel =
            document.getElementById(
                'wp-transfer-city-notes-panel'
            );

        if (panel) {

            if (
                panel.dataset.cityKey !== key
            ) {
                panel.remove();
                panel = null;
            } else {
                wpPositionTransferCityNotesPanel();
                return;
            }

        }

        panel =
            document.createElement(
                'div'
            );

        panel.id =
            'wp-transfer-city-notes-panel';

        panel.dataset.cityKey =
            key;

        const title =
            document.createElement(
                'div'
            );

        const notesCollapseToggle =
            document.createElement(
                'button'
            );

        notesCollapseToggle.type =
            'button';
        notesCollapseToggle.className =
            'wp-panel-collapse-toggle wp-notes-collapse-toggle';
        notesCollapseToggle.textContent =
            'Notes';
        notesCollapseToggle.title =
            'Show Notes';

        notesCollapseToggle.addEventListener(
            'click',
            function(event) {
                event.preventDefault();
                event.stopPropagation();

                panel.classList.remove(
                    'is-collapsed'
                );

                wpPositionTransferCityNotesPanel();
            }
        );

        title.className =
            'wp-city-notes-title';

        const titleText =
            document.createElement(
                'span'
            );

        titleText.textContent =
            '📝 ' + city + ' Notes';

        const saved =
            document.createElement(
                'span'
            );

        saved.className =
            'wp-city-notes-saved';

        saved.textContent =
            'Saved';

        title.appendChild(
            titleText
        );

        const notesCollapse =
            document.createElement(
                'button'
            );

        notesCollapse.type = 'button';
        notesCollapse.className = 'wp-city-notes-collapse';
        notesCollapse.textContent = '×';
        notesCollapse.title = 'Hide Notes';

        title.appendChild(notesCollapse);

        const textarea =
            document.createElement(
                'textarea'
            );

        textarea.placeholder =
            'Write your permanent notes for ' +
            city + '...';

        const notes =
            wpGetTransferCityNotes();

        textarea.value =
            typeof notes[key] === 'string'
                ? notes[key]
                : '';

        const actions =
            document.createElement(
                'div'
            );

        actions.className =
            'wp-city-notes-actions';

        const clearButton =
            document.createElement(
                'button'
            );

        clearButton.type =
            'button';

        clearButton.textContent =
            'Clear';

        clearButton.title =
            'Clear the saved notes for ' + city;

        actions.appendChild(
            saved
        );

        actions.appendChild(
            clearButton
        );

        notesCollapse.addEventListener(
            'click',
            function(event) {
                event.preventDefault();
                event.stopPropagation();

                panel.classList.add(
                    'is-collapsed'
                );

                wpPositionTransferCityNotesPanel();
            }
        );

        panel.appendChild(
            notesCollapseToggle
        );

        panel.appendChild(
            title
        );

        panel.appendChild(
            textarea
        );

        panel.appendChild(
            actions
        );

        document.body.appendChild(
            panel
        );

        let saveTimer = null;

        const wpAutoResizeCityNotes =
            function() {

                textarea.style.height = 'auto';

                const minHeight = 48;
                const maxHeight = 240;
                const nextHeight = Math.min(
                    maxHeight,
                    Math.max(minHeight, textarea.scrollHeight)
                );

                textarea.style.height =
                    nextHeight + 'px';

                textarea.style.overflowY =
                    textarea.scrollHeight > maxHeight
                        ? 'auto'
                        : 'hidden';

                wpPositionTransferCityNotesPanel();
            };

        const saveNow =
            function() {

                const current =
                    wpGetTransferCityNotes();

                const value =
                    textarea.value;

                if (value.trim()) {
                    current[key] = value;
                } else {
                    delete current[key];
                }

                wpSaveTransferCityNotes(
                    current
                );

                saved.textContent =
                    'Saved';

                saved.style.opacity =
                    '0.9';

            };

        textarea.addEventListener(
            'input',
            function() {

                wpAutoResizeCityNotes();

                saved.textContent =
                    'Saving…';

                saved.style.opacity =
                    '0.75';

                if (saveTimer) {
                    clearTimeout(saveTimer);
                }

                saveTimer =
                    setTimeout(
                        saveNow,
                        350
                    );

            }
        );

        clearButton.addEventListener(
            'click',
            function(event) {

                event.preventDefault();
                event.stopPropagation();

                textarea.value = '';
                wpAutoResizeCityNotes();

                const current =
                    wpGetTransferCityNotes();

                delete current[key];

                wpSaveTransferCityNotes(
                    current
                );

                saved.textContent =
                    'Cleared';

                textarea.focus();

            }
        );

        wpAutoResizeCityNotes();
        wpPositionTransferCityNotesPanel();

        setTimeout(
            wpPositionTransferCityNotesPanel,
            250
        );

    }

    function wpSetupTransferCityNotesObserver() {

        if (
            window.__wpTransferCityNotesObserver
        ) {
            return;
        }

        if (!wpIsTransferDetailPage()) {
            return;
        }

        let notesRefreshTimer = null;

        window.__wpTransferCityNotesObserver =
            new MutationObserver(function() {

                if (
                    !wpIsTransferDetailPage()
                ) {
                    return;
                }

                if (notesRefreshTimer) {
                    clearTimeout(notesRefreshTimer);
                }

                notesRefreshTimer = setTimeout(function() {
                    notesRefreshTimer = null;
                    wpSetupTransferCityNotes();
                }, 120);

            });

        window.__wpTransferCityNotesObserver.observe(
            document.body,
            {
                childList: true,
                subtree: true
            }
        );

    }

    function wpSetupTransferCityNotesStorageSync() {

        if (
            window.__wpTransferCityNotesStorageHandler
        ) {
            return;
        }

        window.__wpTransferCityNotesStorageHandler =
            function(event) {

                if (
                    event.key !==
                    WP_TRANSFER_CITY_NOTES_KEY
                ) {
                    return;
                }

                const panel =
                    document.getElementById(
                        'wp-transfer-city-notes-panel'
                    );

                if (!panel) {
                    return;
                }

                const textarea =
                    panel.querySelector(
                        'textarea'
                    );

                if (!textarea) {
                    return;
                }

                const key =
                    panel.dataset.cityKey || '';

                const notes =
                    wpGetTransferCityNotes();

                textarea.value =
                    typeof notes[key] === 'string'
                        ? notes[key]
                        : '';

            };

        window.addEventListener(
            'storage',
            window.__wpTransferCityNotesStorageHandler
        );

    }

    function wpAddTransferCityToCopyArea() {

        const existingCityLink = document.querySelector('#wp-transfer-city-link');
        if (existingCityLink) {
            const existingCity = wpFindTransferCity();
            if (existingCity) {
                wpApplyTransferCapacityDisplay(existingCity, existingCityLink);
            }
            return;
        }

        const city =
            wpFindTransferCity();

        if (!city) {
            return;
        }

        const copyButton =
            Array.from(
                document.querySelectorAll(
                    'button, input[type="button"], input[type="submit"], a'
                )
            ).find(function(element) {

                const label =
                    wpNormalizeDetailText(
                        element.textContent ||
                        element.value ||
                        ''
                    ).toLowerCase();

                return (
                    label === 'copy details for em' ||
                    label.includes('copy details for em')
                );

            });

        if (!copyButton) {
            return;
        }

        const cityLink =
            document.createElement(
                'span'
            );

        cityLink.id =
            'wp-transfer-city-link';

        cityLink.className =
            'wp-transfer-city-link';

        cityLink.textContent =
            city;

        cityLink.title =
            'Open ' +
            city +
            ' WhatsApp group';

        /*
         * Reuse the exact same price-tooltip code used by dashboard
         * city cells. This gives the transfer-page city the same
         * suggested-price hover behaviour.
         */
        setupCityPriceTooltip(
            cityLink,
            getTransferCityHoverData
        );

        cityLink.addEventListener(
            'click',
            function(event) {

                event.preventDefault();
                event.stopPropagation();

                const normalized =
                    wpNormalizeCityKey(city);

                if (normalized === 'crete') {
                    wpShowCityWhatsAppChooser(
                        'Crete',
                        {
                            'Herakleion': WHATSAPP_LINKS.Herakleion,
                            'Crete': WHATSAPP_LINKS.Crete
                        }
                    );
                    return;
                }

                if (normalized === 'cyprus') {
                    wpShowCityWhatsAppChooser(
                        'Cyprus',
                        {
                            'Paphos': WHATSAPP_LINKS.Paphos,
                            'Larnaca': WHATSAPP_LINKS.Larnaca
                        }
                    );
                    return;
                }

                if (WP_MULTI_WHATSAPP_GROUPS[normalized]) {
                    wpShowCityWhatsAppChooser(
                        city,
                        WP_MULTI_WHATSAPP_GROUPS[normalized]
                    );
                    return;
                }

                wpOpenCityWhatsApp(city);

            }
        );

        /*
         * Put it immediately to the LEFT of Copy Details for EM.
         * This is the empty area the user marked in the screenshot.
         */
        copyButton.parentElement.insertBefore(
            cityLink,
            copyButton
        );

        // Keep the city name in its own box. Add the booked car type in a
        // separate box just to its left and retry a few times while the CRM
        // finishes rendering the Car Type row.
        window.setTimeout(function() { wpApplyTransferCapacityDisplay(city, cityLink); }, 250);
        window.setTimeout(function() { wpApplyTransferCapacityDisplay(city, cityLink); }, 700);
        window.setTimeout(function() { wpApplyTransferCapacityDisplay(city, cityLink); }, 1400);
        window.setTimeout(function() { wpApplyTransferCapacityDisplay(city, cityLink); }, 2400);



    }




