    function wpNormalizeDetailText(value) {

        return String(value || '')
            .replace(/\u00a0/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();

    }

    function wpFindLabelElement(labelText, occurrence) {

        const wanted =
            wpNormalizeDetailText(labelText).toLowerCase();

        const matches = [];

        document.querySelectorAll(
            'label, th, td, span, div, p, b, strong'
        ).forEach(function(element) {

            const text =
                wpNormalizeDetailText(element.textContent).toLowerCase();

            if (text === wanted) {
                matches.push(element);
            }

        });

        return matches[occurrence || 0] || null;

    }

    function wpValueNearLabel(labelText, occurrence) {

        const label =
            wpFindLabelElement(
                labelText,
                occurrence
            );

        if (!label) {
            return '';
        }

        // Prefer the nearest table/form row.
        const containers = [
            label.closest('tr'),
            label.closest('.form-group'),
            label.parentElement
        ].filter(Boolean);

        for (const container of containers) {

            const field =
                container.querySelector(
                    'input:not([type="hidden"]), textarea, select'
                );

            if (field) {

                const value =
                    wpNormalizeDetailText(
                        field.value || field.textContent
                    );

                if (value) {
                    return value;
                }

            }

            const children =
                Array.from(container.children || []);

            for (const child of children) {

                if (child === label) continue;

                const value =
                    wpNormalizeDetailText(child.textContent);

                if (
                    value &&
                    value.toLowerCase() !==
                        wpNormalizeDetailText(labelText).toLowerCase()
                ) {
                    return value;
                }

            }

        }

        return '';

    }





    function wpParseCRMClipboardText(clipboardText) {

        let raw =
            (clipboardText || '')
                .replace(/\r\n/g, '\n')
                .trim();

        if (!raw) {
            return null;
        }

        /*
         * CRM Copy Details exists in a few slightly different formats.
         * Parse the labelled Pax/Lug and Price fields first so they can
         * never leak into the route/From -> To column.
         */
        let price = '';

        const priceMatch =
            raw.match(
                /(?:,|\n|\s+)Price\s*:\s*([^,\n]+)\s*$/i
            );

        if (priceMatch) {
            price = priceMatch[1].trim();
            raw = raw.slice(0, priceMatch.index).trim();
            raw = raw.replace(/(?:,|\s)+$/, '').trim();
        }

        let paxLug = '';

        const paxLugMatch =
            raw.match(
                /Pax\s*\/\s*Lug\s*:\s*(\d+)\s*\/\s*(\d+)/i
            );

        if (paxLugMatch) {
            paxLug =
                'Pax/Lug: ' +
                paxLugMatch[1] + '/' + paxLugMatch[2];

            raw =
                raw
                    .slice(0, paxLugMatch.index)
                    .trim()
                    .replace(/(?:,|\s)+$/, '')
                    .trim();
        }

        let dateTime = '';
        let route = '';

        /* The batch collector stores details already formatted on separate
         * lines ("Tomorrow, 13:00" / route / "Pax/Lug: 2/3") and the image
         * reads them back through this parser. Split those by line: splitting
         * by comma broke any route whose address contains commas (the date
         * swallowed the pickup and half the drop-off). */
        const lines = raw.split('\n').map(function(line) { return line.trim(); }).filter(Boolean);
        if (lines.length >= 2 && /\b\d{1,2}:\d{2}\b/.test(lines[0])) {
            return {
                dateTime: lines[0],
                route: lines.slice(1).join(' ').trim(),
                paxLug: paxLug,
                price: price
            };
        }

        /* Preferred CRM format: Today, 11:20, <route> */
        const parts = raw.split(',');

        if (parts.length >= 3 && /\b\d{1,2}:\d{2}\b/.test(parts[1])) {
            dateTime = parts[0].trim() + ', ' + parts[1].trim();
            route = parts.slice(2).join(',').trim();
        } else {
            /* Fallback format: Tomorrow 13:50 <route> */
            const timeMatch = raw.match(/\b(\d{1,2}:\d{2})\b/);

            if (timeMatch) {
                const beforeTime = raw.slice(0, timeMatch.index).trim();
                const afterTime = raw.slice(timeMatch.index + timeMatch[0].length).trim();
                const dayMatch = beforeTime.match(/^(Today|Tomorrow|Mon|Tue|Wed|Thu|Fri|Sat|Sun)\b/i);

                dateTime = dayMatch
                    ? dayMatch[1] + ', ' + timeMatch[1]
                    : timeMatch[1];

                route = afterTime.replace(/^,\s*/, '').trim();
            } else {
                route = raw.trim();
            }
        }

        return {
            dateTime: dateTime,
            route: route,
            paxLug: paxLug,
            price: price
        };

    }

    async function wpReadCRMClipboard() {

        if (
            !navigator.clipboard ||
            typeof navigator.clipboard.readText !== 'function'
        ) {
            return null;
        }

        try {

            const clipboardText =
                await navigator.clipboard.readText();

            return wpParseCRMClipboardText(
                clipboardText
            );

        } catch (error) {

            console.warn(
                'Could not read CRM clipboard text:',
                error
            );

            return null;

        }

    }

    async function wpBuildDriverMessageFromCRMClipboard(
        prefix,
        includePrice
    ) {

        const data =
            await wpReadCRMClipboard();

        if (!data) {
            return null;
        }

        const lines = [];

        if (String(prefix || '').trim()) {
            lines.push(prefix, '');
        }

        lines.push(
            data.dateTime,
            data.route
        );

        if (data.paxLug) {
            lines.push(data.paxLug);
        }

        if (
            includePrice &&
            data.price
        ) {
            lines.push(
                'Price: ' +
                data.price
            );
        }

        return lines.join('\n');

    }


    async function wpCopyText(text) {

        if (
            navigator.clipboard &&
            typeof navigator.clipboard.writeText === 'function'
        ) {
            await navigator.clipboard.writeText(text);
            return;
        }

        const textarea =
            document.createElement('textarea');

        textarea.value = text;
        textarea.style.position = 'fixed';
        textarea.style.opacity = '0';

        document.body.appendChild(textarea);
        textarea.focus();
        textarea.select();

        document.execCommand('copy');
        textarea.remove();

    }

    function wpInstallDriverCopy(button) {

        if (!button || button.dataset.wpDriverCopyInstalled === 'true') {
            return;
        }

        button.dataset.wpDriverCopyInstalled = 'true';

        const wrapper =
            document.createElement('span');

        wrapper.className =
            'wp-driver-copy-wrap';

        const select =
            document.createElement('select');

        select.className =
            'wp-driver-copy-message';

        select.title =
            'Choose the message copied before the transfer details';

        // Keep the full Driver Message dropdown.  7 and 8 are still
        // dynamic and use the current AutoCancel countdown when copied.
        const noneOption =
            document.createElement('option');

        noneOption.value = '';
        noneOption.textContent = '0. None';
        select.appendChild(noneOption);

        wpBuildManagedDriverMessages().forEach(function(message, index) {

            const option =
                document.createElement('option');

            option.value = message;

            option.textContent =
                (index + 1) + '. ' + message;

            select.appendChild(option);

        });

        // Default Copy Details message: first available option.
        const managedDriverMessages = wpBuildManagedDriverMessages();
        select.value = managedDriverMessages.length ? managedDriverMessages[0] : '';

        const priceLabel =
            document.createElement('label');

        priceLabel.className =
            'wp-driver-copy-price-option';

        const priceCheckbox =
            document.createElement('input');

        priceCheckbox.type =
            'checkbox';

        priceCheckbox.className =
            'wp-driver-copy-price';

        const italianPriceCities = new Set([
            'bari', 'bologna', 'brindisi', 'cagliari', 'catania',
            'florence', 'genoa', 'milan', 'naples', 'olbia', 'palermo',
            'pisa', 'rimini', 'rome', 'turin', 'venice', 'verona'
        ]);

        const transferCityForPrice = typeof wpFindTransferCity === 'function'
            ? wpNormalizeCityKey(wpFindTransferCity() || '')
            : '';

        priceCheckbox.checked =
            italianPriceCities.has(transferCityForPrice);

        const priceText =
            document.createElement('span');

        priceText.textContent =
            'Price';

        priceLabel.appendChild(priceCheckbox);
        priceLabel.appendChild(priceText);

        const status =
            document.createElement('span');

        status.className =
            'wp-driver-copy-status';

        wrapper.appendChild(select);
        wrapper.appendChild(priceLabel);
        wrapper.appendChild(status);

        // Refresh 7/8 immediately and whenever the dropdown is opened,
        // so the displayed text matches the live AutoCancel timer.
        wpRefreshLastChanceDriverMessageOptions(select);

        select.addEventListener(
            'focus',
            function() {
                wpRefreshLastChanceDriverMessageOptions(select);
            }
        );

        select.addEventListener(
            'mousedown',
            function() {
                wpRefreshLastChanceDriverMessageOptions(select);
            }
        );

        button.insertAdjacentElement(
            'afterend',
            wrapper
        );

        wpAddDropdownManagerButton(
            wrapper,
            'Driver Message options',
            wpOpenDriverDropdownManager
        );

        button.addEventListener(
            'click',
            function() {

                // The batch collector performs one automatic native CRM click
                // to capture the raw transfer details. Only that synthetic
                // click must bypass our formatter. Manual clicks — including
                // clicks made later on a transfer opened from Transfer
                // Overview — must always run the selected Driver Message
                // formatting.
                try {
                    if (sessionStorage.getItem(WP_BATCH_COLLECTOR_ACTIVE_KEY) === 'true') {
                        return;
                    }
                } catch (error) {}

                /*
                 * IMPORTANT:
                 * Do NOT block the CRM's original click handler.
                 * Let it place the official transfer details in the
                 * clipboard first, then read that exact clipboard text.
                 */
                const prefix =
                    wpFormatDriverMessageWithAcMinutes(
                        select.value
                    );

                setTimeout(
                    async function() {

                        try {

                            const message =
                                await
                                wpBuildDriverMessageFromCRMClipboard(
                                    prefix,
                                    priceCheckbox.checked
                                );

                            if (!message) {

                                status.textContent =
                                    'Could not read CRM copy';

                                return;

                            }

                            await wpCopyText(
                                message
                            );

                            try {
                                sessionStorage.setItem(
                                    'wp_last_driver_message_v1',
                                    message
                                );
                            } catch (storageError) {
                                console.warn(
                                    'Could not save last driver message:',
                                    storageError
                                );
                            }

                            status.textContent =
                                'Copied ✓';

                            setTimeout(function() {

                                status.textContent = '';

                            }, 1800);

                        } catch (error) {

                            console.error(
                                'Could not copy formatted driver details:',
                                error
                            );

                            status.textContent =
                                'Copy failed';

                        }

                    },
                    0
                );

            },
            false
        );

    }

    function wpInjectClipboardPageHook() {
        if (window.__wpClipboardPageHookRequested) return;
        window.__wpClipboardPageHookRequested = true;

        if (document.getElementById('wp-transfer-assistant-clipboard-hook')) return;

        const script = document.createElement('script');
        script.id = 'wp-transfer-assistant-clipboard-hook';
        script.src = chrome.runtime.getURL('wp-clipboard-hook.js');
        script.onload = function () {
            try { script.remove(); } catch (_) {}
        };

        (document.head || document.documentElement).appendChild(script);
    }

    wpInjectClipboardPageHook();

    function wpInjectBroadcastPageHook() {
        if (window.__wpBroadcastPageHookRequested) return;
        window.__wpBroadcastPageHookRequested = true;
        if (document.getElementById('wp-transfer-assistant-broadcast-hook')) return;
        const script = document.createElement('script');
        script.id = 'wp-transfer-assistant-broadcast-hook';
        script.src = chrome.runtime.getURL('wp-broadcast-hook.js');
        script.onload = function () { try { script.remove(); } catch (_) {} };
        (document.head || document.documentElement).appendChild(script);
    }
    wpInjectBroadcastPageHook();
    let wpBroadcastHookSuccessAt = 0;
    let wpBroadcastHookErrorAt = 0;
    let wpBroadcastHookLastError = null;
    window.addEventListener('message', function(event) {
        if (!event || event.source !== window) return;
        const data = event.data;
        if (!data || data.source !== 'wp-transfer-assistant-broadcast-hook') return;
        if (data.type === 'one-step-broadcast-started') wpBroadcastHookSuccessAt = Date.now();
        if (data.type === 'one-step-broadcast-success') wpBroadcastHookSuccessAt = Date.now();
        if (data.type === 'one-step-broadcast-error') {
            wpBroadcastHookErrorAt = Date.now();
            wpBroadcastHookLastError = {
                status: data.status || 0,
                source: data.source || 'unknown',
                reason: data.reason || ''
            };
        }
    });
    // Stage-based diagnostics for the broadcast workflow only (never for the
    // existing task/price/save workflow). Logged/stored only on failure, per
    // the requirement not to spam the console or storage on success.
    function wpBroadcastDiag(stage, detail) {
        try {
            console.warn('[WP Transfer Assistant] Broadcast failed at stage: ' + stage + (detail ? (' — ' + detail) : ''));
            sessionStorage.setItem('wp_city_broadcast_last_failure_v1', JSON.stringify({
                stage: stage,
                detail: detail || '',
                at: Date.now()
            }));
        } catch (_) {}
    }
    async function wpWaitForBroadcastHookSuccess(timeout) {
        const started = Date.now(), baseline = wpBroadcastHookSuccessAt, errorBaseline = wpBroadcastHookErrorAt;
        while (Date.now() - started < (timeout || 120000)) {
            if (wpBroadcastHookSuccessAt > baseline) return true;
            if (wpBroadcastHookErrorAt > errorBaseline) {
                const info = wpBroadcastHookLastError;
                wpBroadcastDiag(
                    'generate_suggestions request failed',
                    info ? ('source=' + info.source + (info.reason ? (' reason=' + info.reason) : '') + (info.status ? (' status=' + info.status) : '')) : ''
                );
                return false;
            }
            await new Promise(function(resolve) { setTimeout(resolve, 100); });
        }
        wpBroadcastDiag('generate_suggestions request timed out', 'no response from page hook within ' + (timeout || 120000) + 'ms');
        return false;
    }

    // ============================================================
    // CITY WINDOW -> OPEN ALL + COPY BROADCAST DETAILS
    // ============================================================

    const WP_BATCH_COPY_PREFIX =
        'wp_city_batch_copy_v1_';

    // Set only while the batch collector performs its automatic CRM click.
    // Manual clicks on Copy Details must still use the normal Driver Message
    // dropdown even when the transfer was originally opened from Transfer
    // Overview with wpBatchCopy* parameters in the URL.
    const WP_BATCH_COLLECTOR_ACTIVE_KEY =
        'wp_batch_copy_collector_active_v1';

    function wpGetBatchCopyParams() {
        try {
            const params = new URLSearchParams(window.location.search);
            const batchId = params.get('wpBatchCopyId');
            const index = parseInt(params.get('wpBatchCopyIndex') || '', 10);
            if (!batchId || !Number.isFinite(index)) return null;
            return { batchId: batchId, index: index };
        } catch (error) {
            return null;
        }
    }

    function wpFindNativeCopyDetailsButton() {
        return Array.from(document.querySelectorAll(
            'button, input[type="button"], input[type="submit"], a'
        )).find(function(element) {
            const text = wpNormalizeDetailText(
                element.textContent || element.value || ''
            ).toLowerCase();
            return text === 'copy details for em' ||
                   text.includes('copy details for em');
        }) || null;
    }

    function wpFormatBatchTransferDetails(details) {
        const parsed = wpParseCRMClipboardText(details);
        if (!parsed) {
            return String(details || '').trim();
        }

        const lines = [];

        if (parsed.dateTime) {
            lines.push(parsed.dateTime);
        }

        if (parsed.route) {
            lines.push(parsed.route);
        }

        if (parsed.paxLug) {
            lines.push(parsed.paxLug);
        }

        return lines.join('\n').trim();
    }

    function wpStoreBatchCopyResult(batchId, index, details) {
        try {
            // The CRM copy can come back with a driver message in front
            // ("LAST CHANCE FOR THIS ONE! …"): keep only the transfer details,
            // starting at the date / time line.
            const detailLines = String(details || '').replace(/\r\n/g, '\n').split('\n');
            const firstTimeLine = detailLines.findIndex(function(line) { return /\b\d{1,2}:\d{2}\b/.test(line); });
            if (firstTimeLine > 0) details = detailLines.slice(firstTimeLine).join('\n');
            const parsed = wpParseCRMClipboardText(details);
            const formattedDetails = wpFormatBatchTransferDetails(details);
            localStorage.setItem(
                WP_BATCH_COPY_PREFIX + batchId + '_' + index,
                JSON.stringify({
                    index: index,
                    details: formattedDetails,
                    price: parsed && parsed.price ? parsed.price : '',
                    carType: (function() {
                        try { return wpFindBookedCarType() || ''; } catch (_) { return ''; }
                    })()
                })
            );
        } catch (error) {}
    }

    // ============================================================
    // DASHBOARD OPS TERMINAL
    // ============================================================
    // A terminal-style log of everything the dashboard automates: workflow
    // tabs it opens, details collection, raised prices, clipboard, WhatsApp
    // and the results the tabs report back. Status bar: running / done /
    // skipped / failed workflows, the A/C Off watch and the auto refresh.
    // Collapsing it leaves a pill to the right of the EMP File button. The
    // log, stats and result watchers survive the dashboard's auto refresh
    // (sessionStorage), and the refresh is held while a WhatsApp copy is
    // still pending (wpDashSetBusy).
    const WP_DASH_TERM_KEY = 'wp_dash_terminal_v1';
    const WP_DASH_WATCH_KEY = 'wp_dash_watch_v1';
    const WP_DASH_TAG_COLORS = {
        QB: '#8fffd5', RADAR: '#74a7ff', WA: '#6fd16f', CLIP: '#ffd27a',
        PRICE: '#ffb347', 'A/C': '#6fd16f', RES: '#dfe4e6', SYS: '#7d8a90', DIR: '#c9a3ff'
    };
    const WP_DASH_TAG_LABELS = {
        QB: 'Quickbar', RADAR: 'Overview', WA: 'WhatsApp', CLIP: 'Clipboard',
        PRICE: 'Price', 'A/C': 'A/C', RES: 'Result', SYS: 'System', DIR: 'mod'
    };
    let wpDashState = null;
    let wpDashBusyCount = 0;
    let wpDashTicker = null;

    function wpDashLoadState() {
        if (wpDashState) return wpDashState;
        let saved = null;
        try { saved = JSON.parse(sessionStorage.getItem(WP_DASH_TERM_KEY) || 'null'); } catch (_) {}
        wpDashState = {
            lines: saved && Array.isArray(saved.lines) ? saved.lines.slice(-150) : [],
            collapsed: Boolean(saved && saved.collapsed),
            unread: Number(saved && saved.unread) || 0,
            unreadErrors: Number(saved && saved.unreadErrors) || 0,
            stats: Object.assign({ ok: 0, skip: 0, err: 0 }, (saved && saved.stats) || {})
        };
        return wpDashState;
    }

    function wpDashSaveState() {
        try { sessionStorage.setItem(WP_DASH_TERM_KEY, JSON.stringify(wpDashState)); } catch (_) {}
    }

    function wpDashTagFor(text) {
        const t = String(text || '');
        if (/— (done|workflow done|skipped|failed)/.test(t)) return 'RES';
        if (/WhatsApp group opened/.test(t)) return 'WA';
        if (/cop(y|ied)|clipboard/i.test(t)) return 'CLIP';
        if (/raised price/i.test(t)) return 'PRICE';
        if (/^(City Manager|City Radar)/.test(t)) return 'RADAR';
        if (/A\/C Off (tab|window)|re-enable/i.test(t)) return 'A/C';
        // mod lines, and the workflow steps it starts while running (1.7.165).
        if (/^(✓ )?(🎬 |🤖 )?(mod|D[i]rector|Autopilot)\b/.test(t) || (typeof wpDirector !== 'undefined' && wpDirector && wpDirector.running)) return 'DIR';
        return 'QB';
    }

