            const top = add('div', 'wpr-name', null, node);
            add('span', null, name, top);
            if (opts.state !== undefined) add('span', 'wpr-state ' + (opts.state ? 'is-on' : 'is-off'), opts.state ? 'ON' : 'OFF', top);
