                const rule = { kind: 'except', of: of, city: key, cityName: known ? wpRuleCityName(key) : typed, mode: /^pct:/.test(choice) ? 'pct' : /^min:/.test(choice) ? 'minutes' : 'off', at: Date.now(), text: '' };
                if (rule.mode === 'pct') rule.percent = Number(choice.slice(4));
