            '#wp-director-card .dc-btn{flex:1 1 0;border:0;border-radius:999px;padding:10px 12px;font-size:15px;font-weight:650;cursor:pointer;transition:filter .12s ease,transform .12s ease}',
            '#wp-director-card .dc-btn:hover{filter:brightness(1.12);transform:translateY(-1px)}',
            '#wp-director-card .dc-yes{background:#2fbf71;color:#06210f}',
            '#wp-director-card .dc-yes.is-final{background:#ff6b5e;color:#2a0603}',
